/**
 * Virtualized Data Grid Component
 * Uses AG Grid for high-performance rendering of large datasets
 * 
 * Features:
 * - Row virtualization (only renders visible rows)
 * - Column virtualization for wide tables
 * - Built-in sorting and filtering
 * - Real-time data updates
 * - Dark theme styling
 */

import React, { useMemo, useCallback, useRef } from 'react';
import { AgGridReact } from 'ag-grid-react';
import type { 
  ColDef, 
  GridApi, 
  GridReadyEvent,
  RowClassParams,
  GetRowIdParams,
  ValueFormatterParams
} from 'ag-grid-community';
import 'ag-grid-community/styles/ag-grid.css';
import 'ag-grid-community/styles/ag-theme-alpine.css';
import { colors } from '@/styles/theme';

// AG Grid license for enterprise features
import { LicenseManager } from 'ag-grid-enterprise';
// For development/demo - in production, use real license key
if (import.meta.env.VITE_AG_GRID_LICENSE_KEY) {
  LicenseManager.setLicenseKey(import.meta.env.VITE_AG_GRID_LICENSE_KEY);
}

export interface VirtualizedGridProps<T> {
  /** Data array to display */
  rowData: T[];
  /** Column definitions */
  columnDefs: ColDef<T>[];
  /** Unique ID field for each row */
  getRowId: (params: GetRowIdParams<T>) => string;
  /** Height of each row in pixels */
  rowHeight?: number;
  /** Container height */
  height?: number | string;
  /** Enable row selection */
  rowSelection?: 'single' | 'multiple' | false;
  /** Callback when selection changes */
  onSelectionChanged?: (selectedRows: T[]) => void;
  /** Callback when row is clicked */
  onRowClicked?: (row: T) => void;
  /** Custom row styling based on data */
  getRowClass?: (params: RowClassParams<T>) => string | undefined;
  /** Loading state */
  loading?: boolean;
  /** Enable server-side row model for very large datasets */
  serverSide?: boolean;
  /** Suppress pagination (use for infinite scroll) */
  suppressPagination?: boolean;
  /** Additional class name */
  className?: string;
}

// Custom dark theme CSS variables
const darkThemeStyles = `
  .ag-theme-alpine-dark-custom {
    --ag-background-color: ${colors.backgrounds.primary};
    --ag-header-background-color: ${colors.backgrounds.tertiary};
    --ag-odd-row-background-color: ${colors.backgrounds.secondary};
    --ag-row-hover-color: rgba(255, 255, 255, 0.08);
    --ag-selected-row-background-color: rgba(24, 144, 255, 0.2);
    --ag-border-color: ${colors.backgrounds.border};
    --ag-header-foreground-color: ${colors.text.secondary};
    --ag-foreground-color: ${colors.text.primary};
    --ag-row-border-color: ${colors.backgrounds.border};
    --ag-cell-horizontal-padding: 12px;
  }
  
  .ag-theme-alpine-dark-custom .ag-header-cell {
    font-weight: 600;
    font-size: 12px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
  }
  
  .ag-theme-alpine-dark-custom .ag-cell {
    font-size: 13px;
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  }
  
  .ag-theme-alpine-dark-custom .highlight-row {
    animation: rowHighlight 1s ease-out;
  }
  
  @keyframes rowHighlight {
    0% { background-color: rgba(82, 196, 26, 0.3); }
    100% { background-color: transparent; }
  }
`;

export function VirtualizedGrid<T>({
  rowData,
  columnDefs,
  getRowId,
  rowHeight = 40,
  height = 600,
  rowSelection = false,
  onSelectionChanged,
  onRowClicked,
  getRowClass,
  loading = false,
  suppressPagination = true,
  className = '',
}: VirtualizedGridProps<T>) {
  const gridRef = useRef<AgGridReact<T>>(null);
  const gridApiRef = useRef<GridApi<T> | null>(null);

  // Default column properties
  const defaultColDef = useMemo<ColDef<T>>(() => ({
    sortable: true,
    resizable: true,
    filter: true,
    minWidth: 80,
    flex: 1,
  }), []);

  // Grid ready handler
  const onGridReady = useCallback((params: GridReadyEvent<T>) => {
    gridApiRef.current = params.api;
    // Auto-size columns on initial load
    params.api.sizeColumnsToFit();
  }, []);

  // Selection change handler
  const handleSelectionChanged = useCallback(() => {
    if (onSelectionChanged && gridApiRef.current) {
      const selectedRows = gridApiRef.current.getSelectedRows();
      onSelectionChanged(selectedRows);
    }
  }, [onSelectionChanged]);

  // Row click handler
  const handleRowClicked = useCallback((event: { data: T | undefined }) => {
    if (onRowClicked && event.data) {
      onRowClicked(event.data);
    }
  }, [onRowClicked]);

  // Inject custom styles
  React.useEffect(() => {
    const styleId = 'virtualized-grid-styles';
    if (!document.getElementById(styleId)) {
      const style = document.createElement('style');
      style.id = styleId;
      style.textContent = darkThemeStyles;
      document.head.appendChild(style);
    }
  }, []);

  return (
    <div 
      className={`ag-theme-alpine-dark-custom ${className}`}
      style={{ height, width: '100%' }}
    >
      <AgGridReact<T>
        ref={gridRef}
        rowData={rowData}
        columnDefs={columnDefs}
        defaultColDef={defaultColDef}
        getRowId={getRowId}
        rowHeight={rowHeight}
        headerHeight={44}
        rowSelection={rowSelection || undefined}
        onGridReady={onGridReady}
        onSelectionChanged={handleSelectionChanged}
        onRowClicked={handleRowClicked}
        getRowClass={getRowClass}
        animateRows={true}
        suppressRowClickSelection={!rowSelection}
        suppressCellFocus={true}
        pagination={!suppressPagination}
        paginationPageSize={100}
        paginationPageSizeSelector={[50, 100, 200, 500]}
        loading={loading}
        loadingOverlayComponent={() => (
          <div style={{ 
            display: 'flex', 
            alignItems: 'center', 
            justifyContent: 'center',
            height: '100%'
          }}>
            Loading...
          </div>
        )}
        noRowsOverlayComponent={() => (
          <div style={{ 
            display: 'flex', 
            alignItems: 'center', 
            justifyContent: 'center',
            height: '100%',
            color: colors.text.secondary
          }}>
            No data available
          </div>
        )}
        // Performance optimizations
        suppressPropertyNamesCheck={true}
        debounceVerticalScrollbar={true}
        rowBuffer={10}
        // Enable cell virtualization for wide tables
        suppressColumnVirtualisation={false}
      />
    </div>
  );
}

// Common value formatters for reuse
export const gridFormatters = {
  currency: (params: ValueFormatterParams): string => {
    if (params.value == null) return '-';
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      minimumFractionDigits: 2,
    }).format(params.value);
  },
  
  percent: (params: ValueFormatterParams): string => {
    if (params.value == null) return '-';
    return `${(params.value * 100).toFixed(2)}%`;
  },
  
  number: (decimals = 2) => (params: ValueFormatterParams): string => {
    if (params.value == null) return '-';
    return Number(params.value).toLocaleString('en-US', {
      minimumFractionDigits: decimals,
      maximumFractionDigits: decimals,
    });
  },
  
  dateTime: (params: ValueFormatterParams): string => {
    if (!params.value) return '-';
    const date = new Date(params.value);
    return date.toLocaleString('en-US', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
      hour12: false,
    });
  },
  
  date: (params: ValueFormatterParams): string => {
    if (!params.value) return '-';
    const date = new Date(params.value);
    return date.toLocaleDateString('en-US', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
    });
  },
};

// Common cell renderers
export const gridRenderers = {
  statusTag: (colorMap: Record<string, string>) => (params: { value: string }) => {
    const color = colorMap[params.value] || '#888';
    return `<span style="
      display: inline-block;
      padding: 2px 8px;
      border-radius: 4px;
      font-size: 11px;
      font-weight: 600;
      text-transform: uppercase;
      background-color: ${color}22;
      color: ${color};
      border: 1px solid ${color}44;
    ">${params.value}</span>`;
  },
  
  sideIndicator: (params: { value: string }) => {
    const isBuy = params.value?.toLowerCase() === 'buy';
    const color = isBuy ? colors.semantic.success : colors.semantic.error;
    return `<span style="
      display: inline-flex;
      align-items: center;
      gap: 4px;
      color: ${color};
      font-weight: 600;
    ">
      <span style="
        display: inline-block;
        width: 6px;
        height: 6px;
        border-radius: 50%;
        background-color: ${color};
      "></span>
      ${params.value?.toUpperCase()}
    </span>`;
  },
};

export default VirtualizedGrid;

/**
 * Portfolio Performance Chart
 * Displays portfolio value over time with interactive chart
 * Note: Using placeholder until charting library is installed
 */

import { useMemo } from 'react';
import { Spin } from 'antd';
import { colors } from '@/styles/theme';
import { formatCurrency } from '@/utils/formatters';

interface PortfolioChartProps {
  data?: Array<{
    timestamp: string;
    totalEquity: number;
  }>;
  loading?: boolean;
}

export const PortfolioChart: React.FC<PortfolioChartProps> = ({ 
  data = [], 
  loading = false 
}) => {
  // Ensure data is always an array
  const safeData = Array.isArray(data) ? data : [];
  
  // Calculate min/max for scale
  const { minValue, range } = useMemo(() => {
    if (!safeData || safeData.length === 0) {
      return { minValue: 0, maxValue: 100000, range: 100000 };
    }
    
    // Filter out invalid values and ensure we have valid numbers
    const values = safeData
      .map(d => d.totalEquity)
      .filter(v => typeof v === 'number' && !isNaN(v) && isFinite(v));
    
    // If no valid values, return safe defaults
    if (values.length === 0) {
      return {
        minValue: 0,
        maxValue: 100000,
        range: 100000,
      };
    }
    
    const min = Math.min(...values);
    const max = Math.max(...values);
    const padding = (max - min) * 0.1 || 10000; // 10% padding or $10k minimum
    
    return {
      minValue: min - padding,
      maxValue: max + padding,
      range: max - min + 2 * padding,
    };
  }, [safeData]);

  // Loading state
  if (loading) {
    return (
      <div style={{
        height: '300px',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
      }}>
        <Spin size="large" />
      </div>
    );
  }

  // Empty state
  if (!safeData || safeData.length === 0) {
    return (
      <div style={{
        height: '300px',
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        color: colors.text.tertiary,
      }}>
        <p style={{ fontSize: '16px', marginBottom: '8px' }}>
          No performance data available
        </p>
        <p style={{ fontSize: '14px' }}>
          Chart will appear as trading activity occurs
        </p>
      </div>
    );
  }

  // Simple SVG line chart
  const width = 800;
  const height = 300;
  const padding = { top: 20, right: 20, bottom: 40, left: 60 };
  const chartWidth = width - padding.left - padding.right;
  const chartHeight = height - padding.top - padding.bottom;

  // Generate SVG path - with NaN safety checks
  // First filter out invalid data points
  const validData = safeData.filter(d => 
    d && 
    typeof d.totalEquity === 'number' && 
    !isNaN(d.totalEquity) && 
    isFinite(d.totalEquity) &&
    d.timestamp
  );
  
  const points = validData.map((d, i) => {
    const x = validData.length > 1
      ? (i / (validData.length - 1)) * chartWidth + padding.left
      : chartWidth / 2 + padding.left; // Center single point
    const y = height - padding.bottom - ((d.totalEquity - minValue) / range) * chartHeight;
    
    // Safety check for NaN (shouldn't happen with filtered data, but defensive)
    if (isNaN(x) || isNaN(y) || !isFinite(x) || !isFinite(y)) {
      return { x: padding.left, y: height - padding.bottom, data: d };
    }
    
    return { x, y, data: d };
  });

  const pathData = points
    .map((p, i) => `${i === 0 ? 'M' : 'L'} ${p.x},${p.y}`)
    .join(' ');

  // Generate grid lines (horizontal)
  const gridLines = [0, 0.25, 0.5, 0.75, 1].map(ratio => {
    const y = height - padding.bottom - ratio * chartHeight;
    const value = minValue + ratio * range;
    return { y, value };
  });

  return (
    <div style={{ height: '300px', width: '100%', position: 'relative' }}>
      <svg
        width="100%"
        height="100%"
        viewBox={`0 0 ${width} ${height}`}
        preserveAspectRatio="xMidYMid meet"
      >
        {/* Grid lines */}
        {gridLines.map((line, i) => (
          <g key={i}>
            <line
              x1={padding.left}
              y1={line.y}
              x2={width - padding.right}
              y2={line.y}
              stroke={colors.backgrounds.border}
              strokeWidth={1}
              strokeDasharray="2,2"
              opacity={0.3}
            />
            <text
              x={padding.left - 10}
              y={line.y + 4}
              fill={colors.text.tertiary}
              fontSize={12}
              textAnchor="end"
            >
              {formatCurrency(line.value)}
            </text>
          </g>
        ))}

        {/* Chart line */}
        <path
          d={pathData}
          fill="none"
          stroke={colors.brand.primary}
          strokeWidth={2}
          strokeLinecap="round"
          strokeLinejoin="round"
        />

        {/* Data points */}
        {points.map((p, i) => (
          <circle
            key={i}
            cx={p.x}
            cy={p.y}
            r={3}
            fill={colors.brand.primary}
            stroke={colors.backgrounds.primary}
            strokeWidth={2}
          >
            <title>
              {new Date(p.data.timestamp).toLocaleString()}: {formatCurrency(p.data.totalEquity)}
            </title>
          </circle>
        ))}

        {/* X-axis labels */}
        {points.filter((_, i) => i % Math.ceil(points.length / 6) === 0).map((p, i) => (
          <text
            key={i}
            x={p.x}
            y={height - padding.bottom + 20}
            fill={colors.text.tertiary}
            fontSize={12}
            textAnchor="middle"
          >
            {new Date(p.data.timestamp).toLocaleTimeString('en-US', {
              hour: '2-digit',
              minute: '2-digit',
            })}
          </text>
        ))}
      </svg>
    </div>
  );
};

/**
 * Chart Container Component
 * Main chart component using Lightweight Charts
 */

import React, { useRef, useEffect, useState, useMemo } from 'react';
import { Card, Space, Select, Button, Spin, DatePicker } from 'antd';
import { FullscreenOutlined, SettingOutlined } from '@ant-design/icons';
import { useChart } from '../../hooks/useChart';
import type { Timeframe, Bar } from '../../types/chart.types';
import dayjs, { Dayjs } from 'dayjs';

const { Option } = Select;
const { RangePicker } = DatePicker;

interface ChartContainerProps {
  symbol: string;
  onSymbolChange?: (symbol: string) => void;
  onChartReady?: (chart: unknown) => void;
}

/**
 * Timeframe display labels
 */
const TIMEFRAME_LABELS: Record<Timeframe, string> = {
  '1m': '1 Min',
  '5m': '5 Min',
  '15m': '15 Min',
  '30m': '30 Min',
  '1h': '1 Hour',
  '4h': '4 Hours',
  '1D': '1 Day',
  '1W': '1 Week',
  '1M': '1 Month',
};

/**
 * Chart Container Component
 */
export const ChartContainer: React.FC<ChartContainerProps> = ({ 
  symbol,
  onChartReady
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [timeframe, setTimeframe] = useState<Timeframe>('5m');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  
  // Date range state
  const [dateRange, setDateRange] = useState<[Dayjs, Dayjs]>([
    dayjs().subtract(1, 'month'), // Default: 1 month ago
    dayjs() // Today
  ]);
  const [selectedRangePreset, setSelectedRangePreset] = useState<string>('1M');

  const {
    chart,
    isReady,
    setBarsData,
    fitContent,
  } = useChart(containerRef);

  // Create stable date range key for dependency tracking
  const dateRangeKey = useMemo(
    () => `${dateRange[0].format('YYYY-MM-DD')}_${dateRange[1].format('YYYY-MM-DD')}`,
    [dateRange]
  );

  // Range presets
  const rangePresets = [
    { label: '1D', value: '1D', days: 1 },
    { label: '5D', value: '5D', days: 5 },
    { label: '1M', value: '1M', days: 30 },
    { label: '3M', value: '3M', days: 90 },
    { label: '6M', value: '6M', days: 180 },
    { label: '1Y', value: '1Y', days: 365 },
    { label: 'YTD', value: 'YTD', days: dayjs().diff(dayjs().startOf('year'), 'day') },
  ];

  // Notify parent when chart is ready
  useEffect(() => {
    if (chart && onChartReady) {
      onChartReady(chart);
    }
  }, [chart, onChartReady]);

  /**
   * Fetch historical data
   */
  useEffect(() => {
    if (!isReady || !symbol) return;

    // Request deduplication - prevent rapid successive identical calls
    const requestKey = `${symbol}_${timeframe}_${dateRangeKey}`;
    let isCancelled = false;

    const fetchData = async () => {
      // Prevent concurrent requests with same parameters
      if (isCancelled) {
        console.log('[ChartContainer] Request cancelled:', requestKey);
        return;
      }

      setLoading(true);
      setError(null);

      try {
        // Fetch real data from API with date range
        const { fetchHistoricalBars } = await import('../../services/marketDataApi');
        
        // Convert date range to API format
        const startDate = dateRange[0].format('YYYY-MM-DD');
        const endDate = dateRange[1].format('YYYY-MM-DD');
        
        console.log(`[ChartContainer] Fetching bars for ${symbol}:`, {
          timeframe,
          startDate,
          endDate,
          requestKey
        });
        
        const bars = await fetchHistoricalBars(symbol, timeframe, { 
          limit: 1000,
          start: startDate,
          end: endDate
        });
        
        // Check if request was cancelled while fetching
        if (isCancelled) {
          console.log('[ChartContainer] Request cancelled after fetch:', requestKey);
          return;
        }
        
        console.log(`[ChartContainer] Received ${bars?.length || 0} bars`);
        
        if (bars && bars.length > 0) {
          console.log(`[ChartContainer] Setting ${bars.length} bars on chart`);
          setBarsData(bars);
          fitContent();
        } else {
          // Fallback to mock data if API returns empty
          const mockBars: Bar[] = generateMockBars(100);
          setBarsData(mockBars);
          fitContent();
        }
      } catch (err: unknown) {
        // Don't process errors if request was cancelled
        if (isCancelled) return;
        
        // Silently fall back to mock data for auth errors (user not logged in)
        const axiosError = err as { response?: { status?: number } };
        if (axiosError?.response?.status === 401) {
          // Auth error - expected when not logged in, use mock data silently
        } else {
          console.error('Failed to fetch chart data:', err);
        }
        // Use mock data as fallback
        const mockBars: Bar[] = generateMockBars(100);
        setBarsData(mockBars);
        fitContent();
        setError(null); // Don't show error, just use mock data
      } finally {
        if (!isCancelled) {
          setLoading(false);
        }
      }
    };

    fetchData();

    // Cleanup function to cancel request if component unmounts or dependencies change
    return () => {
      isCancelled = true;
    };
  }, [symbol, timeframe, dateRangeKey, isReady]);

  /**
   * Handle timeframe change
   */
  const handleTimeframeChange = (newTimeframe: Timeframe) => {
    setTimeframe(newTimeframe);
  };

  /**
   * Handle range preset click
   */
  const handleRangePreset = (preset: typeof rangePresets[0]) => {
    setSelectedRangePreset(preset.value);
    if (preset.value === 'YTD') {
      setDateRange([dayjs().startOf('year'), dayjs()]);
    } else {
      setDateRange([dayjs().subtract(preset.days, 'day'), dayjs()]);
    }
  };

  /**
   * Handle custom date range change
   */
  const handleDateRangeChange = (dates: null | [Dayjs | null, Dayjs | null]) => {
    if (dates && dates[0] && dates[1]) {
      setDateRange([dates[0], dates[1]]);
      setSelectedRangePreset(''); // Clear preset selection
    }
  };

  /**
   * Handle fullscreen
   */
  const handleFullscreen = () => {
    if (containerRef.current) {
      if (document.fullscreenElement) {
        document.exitFullscreen();
      } else {
        containerRef.current.requestFullscreen();
      }
    }
  };

  return (
    <Card
      title={
        <Space wrap>
          <span style={{ fontSize: 16, fontWeight: 600 }}>{symbol}</span>
          <Select
            value={timeframe}
            onChange={handleTimeframeChange}
            style={{ width: 120 }}
            size="small"
          >
            {Object.entries(TIMEFRAME_LABELS).map(([value, label]) => (
              <Option key={value} value={value}>
                {label}
              </Option>
            ))}
          </Select>
          
          {/* Range Preset Buttons */}
          <Space size="small">
            {rangePresets.map((preset) => (
              <Button
                key={preset.value}
                size="small"
                type={selectedRangePreset === preset.value ? 'primary' : 'default'}
                onClick={() => handleRangePreset(preset)}
              >
                {preset.label}
              </Button>
            ))}
          </Space>
          
          {/* Custom Date Range Picker */}
          <RangePicker
            size="small"
            value={dateRange}
            onChange={handleDateRangeChange}
            format="MMM DD, YYYY"
            allowClear={false}
          />
        </Space>
      }
      extra={
        <Space>
          <Button 
            icon={<SettingOutlined />} 
            size="small"
            type="text"
          />
          <Button 
            icon={<FullscreenOutlined />} 
            size="small"
            type="text"
            onClick={handleFullscreen}
          />
        </Space>
      }
      style={{ height: '100%' }}
      styles={{ body: { padding: 0, height: 'calc(100% - 57px)' } }}
    >
      {loading && (
        <div style={{ 
          position: 'absolute', 
          top: '50%', 
          left: '50%', 
          transform: 'translate(-50%, -50%)',
          zIndex: 10
        }}>
          <Spin size="large" />
        </div>
      )}
      
      {error && (
        <div style={{ 
          position: 'absolute', 
          top: '50%', 
          left: '50%', 
          transform: 'translate(-50%, -50%)',
          color: '#ff4d4f',
          zIndex: 10
        }}>
          {error}
        </div>
      )}

      <div 
        ref={containerRef} 
        style={{ 
          width: '100%', 
          height: '100%',
          minHeight: '500px',
          position: 'relative'
        }} 
      />
    </Card>
  );
};

/**
 * Generate mock OHLCV bars for testing
 * TODO: Replace with real data from API
 */
function generateMockBars(count: number): Bar[] {
  const bars: Bar[] = [];
  const now = Math.floor(Date.now() / 1000);
  const interval = 300; // 5 minutes in seconds
  
  let price = 150;
  const volume = 1000000;

  for (let i = 0; i < count; i++) {
    const time = (now - (count - i) * interval) as unknown as import('lightweight-charts').Time;
    const change = (Math.random() - 0.5) * 2;
    const open = price;
    const close = price + change;
    const high = Math.max(open, close) + Math.random();
    const low = Math.min(open, close) - Math.random();
    
    bars.push({
      time,
      open,
      high,
      low,
      close,
      volume: volume + (Math.random() - 0.5) * 200000,
    });

    price = close;
  }

  return bars;
}

export default ChartContainer;

/**
 * Quote Panel Component
 * 
 * Displays real-time market data for a symbol
 * Shows bid, ask, last price, spread, and size
 */

import React from 'react';
import { Card, Typography, Row, Col, Badge, Statistic, Space, Tag } from 'antd';
import { ArrowUpOutlined, ArrowDownOutlined, SignalFilled } from '@ant-design/icons';
import { useSymbolQuote } from '../../hooks/useMarketDataWebSocket';

interface QuotePanelProps {
  symbol: string;
  compact?: boolean;
}

/**
 * Format price with 2 decimal places
 */
const formatPrice = (price: number | undefined): string => {
  return price !== undefined ? `$${price.toFixed(2)}` : '--';
};

/**
 * Format size
 */
const formatSize = (size: number | undefined): string => {
  return size !== undefined ? size.toLocaleString() : '--';
};

/**
 * Get price change color
 */
const getPriceColor = (current: number | undefined, previous: number | undefined): string => {
  if (!current || !previous) return 'text.primary';
  if (current > previous) return 'success.main';
  if (current < previous) return 'error.main';
  return 'text.primary';
};

/**
 * QuotePanel Component
 */
export const QuotePanel: React.FC<QuotePanelProps> = ({ symbol, compact = false }) => {
  const quote = useSymbolQuote(symbol);
  const previousPriceRef = React.useRef<number | undefined>(undefined);
  
  // Track previous price for color indication
  React.useEffect(() => {
    if (quote?.last) {
      previousPriceRef.current = displayQuote.last;
    }
  }, [quote?.last]);
  
  // Use mock data if no quote available (not connected)
  const displayQuote = React.useMemo(() => {
    if (quote) return quote;
    
    // Generate mock quote for display when disconnected
    const basePrice = 150 + Math.random() * 10;
    return {
      symbol: symbol.toUpperCase(),
      bid: basePrice - 0.05,
      ask: basePrice + 0.05,
      bid_size: Math.floor(100 + Math.random() * 500),
      ask_size: Math.floor(100 + Math.random() * 500),
      last: basePrice,
      mid: basePrice,
      spread: 0.10,
      timestamp: new Date().toISOString(),
      updateCount: 0
    };
  }, [quote, symbol]);
  
  const priceColor = getPriceColor(displayQuote.last, previousPriceRef.current);
  const lastPrice = displayQuote.last || displayQuote.mid;
  const prevPrice = previousPriceRef.current;
  const priceIncreased = lastPrice && prevPrice ? lastPrice > prevPrice : false;
  const priceDecreased = lastPrice && prevPrice ? lastPrice < prevPrice : false;
  
  if (compact) {
    return (
      <Card size="small" style={{ borderRadius: 8, background: '#141414', border: '1px solid #303030' }}>
        <Space direction="vertical" style={{ width: '100%' }} size="small">
          <Row justify="space-between" align="middle">
            <Col>
              <Typography.Text strong style={{ color: '#fff' }}>{symbol}</Typography.Text>
            </Col>
            <Col>
              <Badge status="success" text={<SignalFilled style={{ color: '#52c41a' }} />} />
            </Col>
          </Row>
          
          <Row justify="space-between" align="middle">
            <Col>
              <Typography.Title level={4} style={{ margin: 0, color: priceColor }}>
                {formatPrice(lastPrice)}
              </Typography.Title>
            </Col>
            {displayQuote.spread !== undefined && (
              <Col>
                <Typography.Text type="secondary" style={{ fontSize: 12 }}>
                  Spread: ${displayQuote.spread.toFixed(3)}
                </Typography.Text>
              </Col>
            )}
          </Row>
          
          <Row gutter={16} style={{ marginTop: 8 }}>
            <Col span={12} style={{ textAlign: 'center' }}>
              <Typography.Text type="danger" style={{ fontSize: 11, display: 'block' }}>
                Bid
              </Typography.Text>
              <Typography.Text strong style={{ color: '#ff4d4f' }}>
                {formatPrice(displayQuote.bid)}
              </Typography.Text>
              <Typography.Text type="secondary" style={{ fontSize: 11, display: 'block' }}>
                {formatSize(displayQuote.bid_size)}
              </Typography.Text>
            </Col>
            
            <Col span={12} style={{ textAlign: 'center' }}>
              <Typography.Text type="success" style={{ fontSize: 11, display: 'block' }}>
                Ask
              </Typography.Text>
              <Typography.Text strong style={{ color: '#52c41a' }}>
                {formatPrice(displayQuote.ask)}
              </Typography.Text>
              <Typography.Text type="secondary" style={{ fontSize: 11, display: 'block' }}>
                {formatSize(displayQuote.ask_size)}
              </Typography.Text>
            </Col>
          </Row>
        </Space>
      </Card>
    );
  }
  
  return (
    <Card title={null} style={{ borderRadius: 8, background: '#141414', border: '1px solid #303030' }}>
      {/* Header */}
      <Row justify="space-between" align="middle" style={{ marginBottom: 16 }}>
        <Col>
          <Typography.Title level={4} style={{ margin: 0, color: '#fff' }}>
            {symbol}
          </Typography.Title>
        </Col>
        <Col>
          <Space>
            {quote ? (
              <>
                <Tag icon={<SignalFilled />} color="success">Live</Tag>
                {displayQuote.updateCount && (
                  <Typography.Text type="secondary" style={{ fontSize: 12 }}>
                    {displayQuote.updateCount} updates
                  </Typography.Text>
                )}
              </>
            ) : (
              <Tag color="default">Mock Data</Tag>
            )}
          </Space>
        </Col>
      </Row>
      
      {/* Last Price */}
      <div style={{ marginBottom: 24 }}>
        <Typography.Text type="secondary" style={{ fontSize: 12, display: 'block' }}>
          Last Price
        </Typography.Text>
        <Space align="baseline">
          <Typography.Title level={1} style={{ margin: 0, color: priceColor }}>
            {formatPrice(lastPrice)}
          </Typography.Title>
          {lastPrice && prevPrice && lastPrice !== prevPrice && (
            priceIncreased ? (
              <ArrowUpOutlined style={{ fontSize: 24, color: '#52c41a' }} />
            ) : priceDecreased ? (
              <ArrowDownOutlined style={{ fontSize: 24, color: '#ff4d4f' }} />
            ) : null
          )}
        </Space>
        {displayQuote.timestamp && (
          <Typography.Text type="secondary" style={{ fontSize: 12 }}>
            Updated: {new Date(displayQuote.timestamp).toLocaleTimeString()}
          </Typography.Text>
        )}
      </div>
      
      {/* Bid/Ask Grid */}
      <Row gutter={16} style={{ marginBottom: 24 }}>
        {/* Bid */}
        <Col span={12}>
          <Card 
            size="small" 
            style={{ 
              borderColor: '#ff4d4f', 
              borderWidth: 2,
              borderRadius: 8
            }}
          >
            <Typography.Text type="danger" strong style={{ fontSize: 12, display: 'block' }}>
              BID
            </Typography.Text>
            <Statistic
              value={displayQuote.bid}
              precision={2}
              prefix="$"
              valueStyle={{ color: '#ff4d4f', fontSize: 28 }}
            />
            <Row justify="space-between" style={{ marginTop: 8 }}>
              <Col>
                <Typography.Text type="secondary" style={{ fontSize: 12 }}>Size:</Typography.Text>
              </Col>
              <Col>
                <Typography.Text strong>{formatSize(displayQuote.bid_size)}</Typography.Text>
              </Col>
            </Row>
          </Card>
        </Col>
        
        {/* Ask */}
        <Col span={12}>
          <Card 
            size="small" 
            style={{ 
              borderColor: '#52c41a', 
              borderWidth: 2,
              borderRadius: 8
            }}
          >
            <Typography.Text type="success" strong style={{ fontSize: 12, display: 'block' }}>
              ASK
            </Typography.Text>
            <Statistic
              value={displayQuote.ask}
              precision={2}
              prefix="$"
              valueStyle={{ color: '#52c41a', fontSize: 28 }}
            />
            <Row justify="space-between" style={{ marginTop: 8 }}>
              <Col>
                <Typography.Text type="secondary" style={{ fontSize: 12 }}>Size:</Typography.Text>
              </Col>
              <Col>
                <Typography.Text strong>{formatSize(displayQuote.ask_size)}</Typography.Text>
              </Col>
            </Row>
          </Card>
        </Col>
      </Row>
      
      {/* Additional Info */}
      <Row gutter={16}>
        <Col span={12}>
          <Typography.Text type="secondary" style={{ fontSize: 12, display: 'block' }}>
            Mid Price
          </Typography.Text>
          <Typography.Text strong style={{ fontSize: 16 }}>
            {formatPrice(displayQuote.mid)}
          </Typography.Text>
        </Col>
        
        <Col span={12}>
          <Typography.Text type="secondary" style={{ fontSize: 12, display: 'block' }}>
            Spread
          </Typography.Text>
          <Typography.Text strong style={{ fontSize: 16 }}>
            ${displayQuote.spread.toFixed(3)} ({((displayQuote.spread / displayQuote.mid) * 100).toFixed(2)}%)
          </Typography.Text>
        </Col>
      </Row>
    </Card>
  );
};

export default QuotePanel;

/**
 * Market Scanner Component
 * 
 * Scans and filters stocks based on technical criteria.
 * 
 * Features:
 * - Multiple filter types (price, volume, RSI, MACD, moving averages)
 * - Predefined scan presets
 * - Results table with sorting
 * - Click to load symbol on chart
 * - Real-time scanning via WebSocket
 * - Auto-refresh toggle
 * 
 * Phase 7 - Market Data & Charting
 * Enhanced: October 16, 2025
 */

import React, { useState, useEffect } from 'react';
import {
  Card,
  Form,
  InputNumber,
  Select,
  Button,
  Table,
  Space,
  Tag,
  Switch,
  Divider,
  Typography,
  Row,
  Col,
  Statistic,
  message,
  Tooltip,
  Badge,
} from 'antd';
import {
  SearchOutlined,
  RiseOutlined,
  FallOutlined,
  ThunderboltOutlined,
  ReloadOutlined,
  StarOutlined,
  PlayCircleOutlined,
  PauseCircleOutlined,
  WifiOutlined,
  DisconnectOutlined,
  DownloadOutlined,
  FileTextOutlined,
} from '@ant-design/icons';
import type { ColumnsType } from 'antd/es/table';
import { useScannerWebSocket } from '../../hooks/useScannerWebSocket';
import { apiClient } from '../../services/api';

const { Title, Text } = Typography;
const { Option } = Select;

// ============================================================================
// TYPES
// ============================================================================

interface ScanFilters {
  price_min?: number;
  price_max?: number;
  volume_min?: number;
  volume_spike?: number;
  rsi_min?: number;
  rsi_max?: number;
  macd_signal?: 'any' | 'bullish' | 'bearish';
  ma_crossover?: 'none' | 'golden_cross' | 'death_cross';
  above_sma_50?: boolean;
  above_sma_200?: boolean;
  gap_up?: boolean;
  gap_down?: boolean;
  gap_percentage?: number;
  atr_multiplier?: number;
  limit?: number;
}

interface ScanResult {
  symbol: string;
  price: number;
  change: number;
  change_percent: number;
  volume: number;
  avg_volume?: number;
  rsi?: number;
  macd?: number;
  macd_signal?: number;
  sma_50?: number;
  sma_200?: number;
  atr?: number;
  score: number;
  signals: string[];
}

interface ScanPreset {
  name: string;
  description: string;
  filters: ScanFilters;
}

// ============================================================================
// API CLIENT
// ============================================================================

class ScannerAPI {
  async scan(filters: ScanFilters): Promise<{ results: ScanResult[]; total: number; scan_time: number; filters_applied: number }> {
    const response = await apiClient.post('/scanner/scan', filters);
    return response.data;
  }

  async getPresets(): Promise<ScanPreset[]> {
    const response = await apiClient.get('/scanner/presets');
    return response.data;
  }
}

// ============================================================================
// COMPONENT
// ============================================================================

interface ScannerProps {
  onSymbolSelect?: (symbol: string) => void;
}

export const Scanner: React.FC<ScannerProps> = ({ onSymbolSelect }) => {
  const [form] = Form.useForm();
  const [loading, setLoading] = useState(false);
  const [results, setResults] = useState<ScanResult[]>([]);
  const [scanStats, setScanStats] = useState<{ total: number; scan_time: number; filters_applied: number } | null>(null);
  const [presets, setPresets] = useState<ScanPreset[]>([]);
  const [presetsLoaded, setPresetsLoaded] = useState(false);
  const [autoRefresh, setAutoRefresh] = useState(false);
  const [refreshInterval, setRefreshInterval] = useState(10); // seconds

  const api = new ScannerAPI();
  
  // WebSocket hook for real-time scanning
  const {
    connectionStatus,
    isScanning,
    lastResults,
    isConnected,
    connect,
    disconnect,
    startScanning,
    stopScanning,
    updateFilters,
  } = useScannerWebSocket(false); // Don't auto-connect

  // Load presets on mount
  useEffect(() => {
    loadPresets();
  }, []);
  
  // Update results from WebSocket
  useEffect(() => {
    if (lastResults) {
      setResults(lastResults.results);
      setScanStats({
        total: lastResults.total,
        scan_time: lastResults.scan_time,
        filters_applied: lastResults.filters_applied,
      });
    }
  }, [lastResults]);
  
  // Handle auto-refresh toggle
  useEffect(() => {
    if (autoRefresh) {
      // Connect and start scanning
      if (!isConnected) {
        connect();
      }
      
      // Wait for connection then start scanning
      if (isConnected) {
        const currentFilters = form.getFieldsValue();
        startScanning(currentFilters, refreshInterval);
      }
    } else {
      // Stop scanning and disconnect
      if (isScanning) {
        stopScanning();
      }
      if (isConnected) {
        disconnect();
      }
    }
  }, [autoRefresh, isConnected]);

  const loadPresets = async () => {
    try {
      const loadedPresets = await api.getPresets();
      setPresets(loadedPresets);
      setPresetsLoaded(true);
    } catch (error) {
      console.error('Failed to load presets:', error);
      message.error('Failed to load scan presets');
    }
  };

  // Handle scan
  const handleScan = async (values: ScanFilters) => {
    setLoading(true);

    try {
      const response = await api.scan(values);
      setResults(response.results);
      setScanStats({
        total: response.total,
        scan_time: response.scan_time,
        filters_applied: response.filters_applied,
      });
      message.success(`Found ${response.total} matching stocks in ${response.scan_time.toFixed(2)}s`);
    } catch (error) {
      console.error('Scan failed:', error);
      message.error(error instanceof Error ? error.message : 'Scan failed');
    } finally {
      setLoading(false);
    }
  };

  // Apply preset
  const applyPreset = (preset: ScanPreset) => {
    form.setFieldsValue(preset.filters);
    message.info(`Applied ${preset.name} preset`);
  };

  // Reset form
  const handleReset = () => {
    form.resetFields();
    setResults([]);
    setScanStats(null);
  };
  
  // Export functions
  const handleExportCSV = async () => {
    if (results.length === 0) {
      message.warning('No results to export');
      return;
    }
    
    try {
      const currentFilters = form.getFieldsValue();
      const response = await apiClient.post('/scanner/export/csv', currentFilters, {
        responseType: 'blob',
      });
      
      const blob = response.data;
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `scan_results_${new Date().toISOString().split('T')[0]}.csv`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
      
      message.success('Results exported to CSV');
    } catch (error) {
      console.error('CSV export failed:', error);
      message.error('Failed to export CSV');
    }
  };
  
  const handleExportJSON = async () => {
    if (results.length === 0) {
      message.warning('No results to export');
      return;
    }
    
    try {
      const currentFilters = form.getFieldsValue();
      const response = await apiClient.post('/scanner/export/json', currentFilters, {
        responseType: 'blob',
      });
      
      const blob = response.data;
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `scan_results_${new Date().toISOString().split('T')[0]}.json`;
      document.body.appendChild(a);
      a.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(a);
      
      message.success('Results exported to JSON');
    } catch (error) {
      console.error('JSON export failed:', error);
      message.error('Failed to export JSON');
    }
  };

  // Table columns
  const columns: ColumnsType<ScanResult> = [
    {
      title: 'Symbol',
      dataIndex: 'symbol',
      key: 'symbol',
      fixed: 'left',
      width: 100,
      render: (symbol: string) => (
        <Button
          type="link"
          onClick={() => onSymbolSelect?.(symbol)}
          style={{ fontWeight: 'bold' }}
        >
          {symbol}
        </Button>
      ),
    },
    {
      title: 'Price',
      dataIndex: 'price',
      key: 'price',
      width: 100,
      sorter: (a, b) => a.price - b.price,
      render: (price: number) => `$${price.toFixed(2)}`,
    },
    {
      title: 'Change',
      dataIndex: 'change_percent',
      key: 'change_percent',
      width: 100,
      sorter: (a, b) => a.change_percent - b.change_percent,
      render: (change_percent: number) => {
        const isPositive = change_percent >= 0;
        return (
          <Space>
            {isPositive ? <RiseOutlined style={{ color: '#52c41a' }} /> : <FallOutlined style={{ color: '#ff4d4f' }} />}
            <Text style={{ color: isPositive ? '#52c41a' : '#ff4d4f' }}>
              {isPositive ? '+' : ''}{change_percent.toFixed(2)}%
            </Text>
          </Space>
        );
      },
    },
    {
      title: 'Volume',
      dataIndex: 'volume',
      key: 'volume',
      width: 120,
      sorter: (a, b) => a.volume - b.volume,
      render: (volume: number) => volume.toLocaleString(),
    },
    {
      title: 'RSI',
      dataIndex: 'rsi',
      key: 'rsi',
      width: 80,
      sorter: (a, b) => (a.rsi || 0) - (b.rsi || 0),
      render: (rsi?: number) => {
        if (!rsi) return '-';
        const color = rsi > 70 ? '#ff4d4f' : rsi < 30 ? '#52c41a' : '#1890ff';
        return <Text style={{ color }}>{rsi.toFixed(1)}</Text>;
      },
    },
    {
      title: 'Score',
      dataIndex: 'score',
      key: 'score',
      width: 100,
      sorter: (a, b) => a.score - b.score,
      defaultSortOrder: 'descend',
      render: (score: number) => (
        <Tag color={score >= 80 ? 'green' : score >= 60 ? 'blue' : 'default'}>
          {score.toFixed(0)}%
        </Tag>
      ),
    },
    {
      title: 'Signals',
      dataIndex: 'signals',
      key: 'signals',
      render: (signals: string[]) => (
        <Space wrap size="small">
          {signals.slice(0, 3).map((signal, idx) => (
            <Tag key={idx} color="blue" style={{ fontSize: 11 }}>
              {signal}
            </Tag>
          ))}
          {signals.length > 3 && (
            <Tooltip title={signals.slice(3).join(', ')}>
              <Tag color="default" style={{ fontSize: 11 }}>
                +{signals.length - 3}
              </Tag>
            </Tooltip>
          )}
        </Space>
      ),
    },
  ];

  return (
    <Card
      title={
        <Space>
          <SearchOutlined />
          <span>Market Scanner</span>
          {isConnected && (
            <Badge status="success" text="Live" />
          )}
        </Space>
      }
      extra={
        <Space>
          {/* Auto-Refresh Toggle */}
          <Tooltip title={autoRefresh ? 'Stop auto-refresh' : 'Enable auto-refresh'}>
            <Space>
              {autoRefresh ? <PauseCircleOutlined /> : <PlayCircleOutlined />}
              <Switch
                checked={autoRefresh}
                onChange={(checked) => setAutoRefresh(checked)}
                checkedChildren="Live"
                unCheckedChildren="Manual"
              />
            </Space>
          </Tooltip>
          
          {/* Refresh Interval */}
          {autoRefresh && (
            <InputNumber
              min={5}
              max={60}
              value={refreshInterval}
              onChange={(value) => {
                if (value) {
                  setRefreshInterval(value);
                  if (isScanning) {
                    const currentFilters = form.getFieldsValue();
                    updateFilters(currentFilters, value);
                  }
                }
              }}
              addonAfter="sec"
              style={{ width: 100 }}
            />
          )}
          
          {/* Connection Status */}
          {autoRefresh && (
            <Tooltip title={`WebSocket: ${connectionStatus}`}>
              {isConnected ? (
                <WifiOutlined style={{ color: 'green', fontSize: 18 }} />
              ) : (
                <DisconnectOutlined style={{ color: 'red', fontSize: 18 }} />
              )}
            </Tooltip>
          )}
          
          {/* Manual Scan Button */}
          {!autoRefresh && (
            <Button
              icon={<ReloadOutlined />}
              onClick={() => form.submit()}
              loading={loading}
            >
              Scan
            </Button>
          )}
          
          <Button onClick={handleReset}>
            Reset
          </Button>
        </Space>
      }
    >
      <Space direction="vertical" style={{ width: '100%' }} size="large">
        {/* Presets */}
        {presetsLoaded && presets.length > 0 && (
          <div>
            <Text strong>Quick Presets:</Text>
            <div style={{ marginTop: 8 }}>
              <Space wrap>
                {presets.map((preset, idx) => (
                  <Tooltip key={idx} title={preset.description}>
                    <Button
                      size="small"
                      icon={<StarOutlined />}
                      onClick={() => applyPreset(preset)}
                    >
                      {preset.name}
                    </Button>
                  </Tooltip>
                ))}
              </Space>
            </div>
          </div>
        )}

        <Divider />

        {/* Filters Form */}
        <Form
          form={form}
          layout="vertical"
          onFinish={handleScan}
          initialValues={{
            limit: 50,
            macd_signal: 'any',
            ma_crossover: 'none',
          }}
        >
          <Row gutter={16}>
            {/* Price Filters */}
            <Col span={12}>
              <Form.Item label="Price Range" style={{ marginBottom: 8 }}>
                <Space.Compact style={{ width: '100%' }}>
                  <Form.Item name="price_min" noStyle>
                    <InputNumber placeholder="Min $" style={{ width: '50%' }} min={0} />
                  </Form.Item>
                  <Form.Item name="price_max" noStyle>
                    <InputNumber placeholder="Max $" style={{ width: '50%' }} min={0} />
                  </Form.Item>
                </Space.Compact>
              </Form.Item>
            </Col>

            {/* Volume */}
            <Col span={12}>
              <Form.Item label="Min Volume" name="volume_min">
                <InputNumber
                  placeholder="e.g., 1000000"
                  style={{ width: '100%' }}
                  min={0}
                  formatter={(value) => `${value}`.replace(/\B(?=(\d{3})+(?!\d))/g, ',')}
                />
              </Form.Item>
            </Col>

            {/* RSI Range */}
            <Col span={24}>
              <Form.Item label="RSI Range">
                <Row gutter={8}>
                  <Col span={12}>
                    <Form.Item name="rsi_min" noStyle>
                      <InputNumber placeholder="Min (e.g., 30)" style={{ width: '100%' }} min={0} max={100} />
                    </Form.Item>
                  </Col>
                  <Col span={12}>
                    <Form.Item name="rsi_max" noStyle>
                      <InputNumber placeholder="Max (e.g., 70)" style={{ width: '100%' }} min={0} max={100} />
                    </Form.Item>
                  </Col>
                </Row>
              </Form.Item>
            </Col>

            {/* MACD Signal */}
            <Col span={12}>
              <Form.Item label="MACD Signal" name="macd_signal">
                <Select>
                  <Option value="any">Any</Option>
                  <Option value="bullish">Bullish</Option>
                  <Option value="bearish">Bearish</Option>
                </Select>
              </Form.Item>
            </Col>

            {/* MA Crossover */}
            <Col span={12}>
              <Form.Item label="MA Crossover" name="ma_crossover">
                <Select>
                  <Option value="none">None</Option>
                  <Option value="golden_cross">Golden Cross</Option>
                  <Option value="death_cross">Death Cross</Option>
                </Select>
              </Form.Item>
            </Col>

            {/* Moving Average Filters */}
            <Col span={12}>
              <Form.Item label="Above SMA 50" name="above_sma_50" valuePropName="checked">
                <Switch />
              </Form.Item>
            </Col>

            <Col span={12}>
              <Form.Item label="Above SMA 200" name="above_sma_200" valuePropName="checked">
                <Switch />
              </Form.Item>
            </Col>

            {/* Gap Filters */}
            <Col span={12}>
              <Form.Item label="Gap Up" name="gap_up" valuePropName="checked">
                <Switch />
              </Form.Item>
            </Col>

            <Col span={12}>
              <Form.Item label="Gap Down" name="gap_down" valuePropName="checked">
                <Switch />
              </Form.Item>
            </Col>

            {/* Advanced Filters */}
            <Col span={12}>
              <Form.Item label="Volume Spike (x avg)" name="volume_spike">
                <InputNumber placeholder="e.g., 2.0" style={{ width: '100%' }} min={1} step={0.1} />
              </Form.Item>
            </Col>

            <Col span={12}>
              <Form.Item label="Max Results" name="limit">
                <InputNumber style={{ width: '100%' }} min={1} max={100} />
              </Form.Item>
            </Col>
          </Row>

          <Form.Item style={{ marginBottom: 0 }}>
            <Button
              type="primary"
              htmlType="submit"
              icon={<SearchOutlined />}
              loading={loading}
              block
              size="large"
            >
              Scan Market
            </Button>
          </Form.Item>
        </Form>

        {/* Scan Statistics */}
        {scanStats && (
          <>
            <Divider />
            <Row gutter={16}>
              <Col span={8}>
                <Statistic title="Results Found" value={scanStats.total} prefix={<ThunderboltOutlined />} />
              </Col>
              <Col span={8}>
                <Statistic title="Scan Time" value={scanStats.scan_time.toFixed(2)} suffix="s" />
              </Col>
              <Col span={8}>
                <Statistic title="Filters Applied" value={scanStats.filters_applied} />
              </Col>
            </Row>
          </>
        )}

        {/* Results Table */}
        {results.length > 0 && (
          <>
            <Divider />
            
            {/* Export Buttons */}
            <Row justify="space-between" align="middle">
              <Col>
                <Text strong>Scan Results ({results.length} stocks)</Text>
              </Col>
              <Col>
                <Space>
                  <Button
                    size="small"
                    onClick={handleExportCSV}
                    icon={<FileTextOutlined />}
                  >
                    Export CSV
                  </Button>
                  <Button
                    size="small"
                    onClick={handleExportJSON}
                    icon={<DownloadOutlined />}
                  >
                    Export JSON
                  </Button>
                </Space>
              </Col>
            </Row>
            
            <Table
              columns={columns}
              dataSource={results}
              rowKey="symbol"
              loading={loading}
              pagination={{
                pageSize: 20,
                showSizeChanger: true,
                showTotal: (total) => `Total ${total} stocks`,
              }}
              scroll={{ x: 800 }}
              size="small"
            />
          </>
        )}

        {/* Empty State */}
        {!loading && results.length === 0 && scanStats === null && (
          <div style={{ textAlign: 'center', padding: '40px 0' }}>
            <SearchOutlined style={{ fontSize: 48, color: '#d9d9d9' }} />
            <Title level={5} style={{ marginTop: 16, color: '#999' }}>
              Configure filters and click Scan to find stocks
            </Title>
          </div>
        )}
      </Space>
    </Card>
  );
};

export default Scanner;

/**
 * Positions Table Component
 * Displays current portfolio positions with sorting and real-time updates
 */

import { useState } from 'react';
import { Table, Tag, Button, App } from 'antd';
import type { ColumnsType } from 'antd/es/table';
import { ArrowUpOutlined, ArrowDownOutlined, CloseOutlined, ExclamationCircleOutlined } from '@ant-design/icons';
import { colors } from '@/styles/theme';
import { formatCurrency, formatPercent } from '@/utils/formatters';
import type { Position } from '@/store/portfolioStore';
import { useAuthStore } from '@/store/authStore';

interface PositionsTableProps {
  positions: Position[];
  loading?: boolean;
  onPositionClosed?: () => void;
}

export const PositionsTable: React.FC<PositionsTableProps> = ({ 
  positions, 
  loading = false,
  onPositionClosed
}) => {
  const { message, modal } = App.useApp();
  const [closingPositions, setClosingPositions] = useState<Set<string>>(new Set());

  // Handle close position
  const handleClosePosition = async (symbol: string, quantity: number) => {
    let quantityToClose: number | undefined = undefined;
    
    modal.confirm({
      title: 'Close Position',
      icon: <ExclamationCircleOutlined />,
      content: (
        <div>
          <p>Position: <strong>{symbol}</strong></p>
          <p>Current Quantity: <strong>{quantity}</strong> shares</p>
          <div style={{ marginTop: 16 }}>
            <label style={{ display: 'block', marginBottom: 8 }}>
              <strong>Quantity to close:</strong>
            </label>
            <input
              type="number"
              id="close-quantity-input"
              min="0.01"
              max={quantity}
              step="0.01"
              placeholder={`${quantity} (all shares)`}
              style={{
                width: '100%',
                padding: '8px 12px',
                border: '1px solid #d9d9d9',
                borderRadius: 4,
                fontSize: 14,
                backgroundColor: '#ffffff',
                color: '#000000',
              }}
              onChange={(e) => {
                const val = parseFloat(e.target.value);
                quantityToClose = isNaN(val) || val <= 0 ? undefined : val;
              }}
            />
            <small style={{ color: '#8c8c8c', display: 'block', marginTop: 4 }}>
              Leave empty to close entire position
            </small>
          </div>
        </div>
      ),
      okText: 'Close Position',
      okType: 'danger',
      cancelText: 'Cancel',
      onOk: async () => {
        try {
          setClosingPositions(prev => new Set(prev).add(symbol));
          
          // Get the input value at execution time
          const inputEl = document.getElementById('close-quantity-input') as HTMLInputElement;
          if (inputEl && inputEl.value) {
            const val = parseFloat(inputEl.value);
            if (!isNaN(val) && val > 0 && val <= quantity) {
              quantityToClose = val;
            }
          }
          
          const qtyText = quantityToClose ? `${quantityToClose}` : 'all';
          message.loading({ content: `Closing ${qtyText} shares of ${symbol}...`, key: symbol });
          
          // Get token from Zustand store
          const token = useAuthStore.getState().accessToken;
          
          if (!token) {
            throw new Error('Not authenticated. Please login again.');
          }
          
          // Build request body
          const body: { quantity?: number } = {};
          if (quantityToClose !== undefined) {
            body.quantity = quantityToClose;
          }
          
          const response = await fetch(`http://localhost:8000/api/v1/positions/${symbol}/close`, {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'Authorization': `Bearer ${token}`
            },
            body: JSON.stringify(body)
          });
          
          if (!response.ok) {
            const error = await response.json();
            throw new Error(error.detail || 'Failed to close position');
          }
          
          const data = await response.json();
          
          message.success({ 
            content: data.message || `Successfully closed ${qtyText} shares of ${symbol}`, 
            key: symbol,
            duration: 3
          });
          
          // Notify parent to refresh data
          if (onPositionClosed) {
            onPositionClosed();
          }
          
        } catch (error: any) {
          const errorMsg = error.message || 'Failed to close position';
          message.error({ content: errorMsg, key: symbol, duration: 4 });
        } finally {
          setClosingPositions(prev => {
            const newSet = new Set(prev);
            newSet.delete(symbol);
            return newSet;
          });
        }
      }
    });
  };

  const columns: ColumnsType<Position> = [
    {
      title: 'Symbol',
      dataIndex: 'symbol',
      key: 'symbol',
      fixed: 'left',
      width: 100,
      sorter: (a, b) => a.symbol.localeCompare(b.symbol),
      render: (symbol: string) => (
        <strong style={{ color: colors.brand.primary }}>{symbol}</strong>
      ),
    },
    {
      title: 'Side',
      dataIndex: 'side',
      key: 'side',
      width: 80,
      filters: [
        { text: 'Long', value: 'long' },
        { text: 'Short', value: 'short' },
      ],
      onFilter: (value, record) => record.side === value,
      render: (side: 'long' | 'short' | undefined) => (
        <Tag color={side === 'long' ? 'green' : side === 'short' ? 'red' : 'blue'}>
          {side ? side.toUpperCase() : 'LONG'}
        </Tag>
      ),
    },
    {
      title: 'Quantity',
      dataIndex: 'quantity',
      key: 'quantity',
      width: 100,
      align: 'right',
      sorter: (a, b) => a.quantity - b.quantity,
      render: (qty: number) => qty.toLocaleString(),
    },
    {
      title: 'Avg Price',
      dataIndex: 'averagePrice',
      key: 'averagePrice',
      width: 120,
      align: 'right',
      sorter: (a, b) => a.averagePrice - b.averagePrice,
      render: (price: number) => formatCurrency(price),
    },
    {
      title: 'Current Price',
      dataIndex: 'currentPrice',
      key: 'currentPrice',
      width: 130,
      align: 'right',
      sorter: (a, b) => a.currentPrice - b.currentPrice,
      render: (price: number) => formatCurrency(price),
    },
    {
      title: 'Market Value',
      dataIndex: 'marketValue',
      key: 'marketValue',
      width: 140,
      align: 'right',
      sorter: (a, b) => a.marketValue - b.marketValue,
      render: (value: number) => (
        <strong>{formatCurrency(value)}</strong>
      ),
    },
    {
      title: 'Unrealized P&L',
      dataIndex: 'unrealizedPnL',
      key: 'unrealizedPnL',
      width: 150,
      align: 'right',
      sorter: (a, b) => a.unrealizedPnL - b.unrealizedPnL,
      defaultSortOrder: 'descend',
      render: (pnl: number | undefined, record: Position) => {
        const actualPnl = pnl || 0;
        const isProfit = actualPnl >= 0;
        const icon = isProfit ? <ArrowUpOutlined /> : <ArrowDownOutlined />;
        const color = isProfit ? colors.semantic.profit : colors.semantic.loss;
        
        return (
          <div style={{ color, fontWeight: 'bold' }}>
            {icon} {formatCurrency(Math.abs(actualPnl))}
            <div style={{ fontSize: '12px', opacity: 0.8 }}>
              {formatPercent(record.unrealizedPnLPercent || 0)}
            </div>
          </div>
        );
      },
    },
    {
      title: 'Entry Date',
      dataIndex: 'entryDate',
      key: 'entryDate',
      width: 140,
      sorter: (a, b) => {
        if (!a.entryDate || !b.entryDate) return 0;
        return new Date(a.entryDate).getTime() - new Date(b.entryDate).getTime();
      },
      render: (date: string | undefined) => {
        if (!date) return <span style={{ color: colors.text.tertiary }}>-</span>;
        const d = new Date(date);
        
        // Detect user's timezone automatically
        const userTimezone = Intl.DateTimeFormat().resolvedOptions().timeZone;
        
        const dateStr = d.toLocaleDateString('en-US', { 
          month: '2-digit', 
          day: '2-digit', 
          year: '2-digit',
          timeZone: userTimezone
        });
        
        const timeStr = d.toLocaleTimeString('en-US', { 
          hour: '2-digit', 
          minute: '2-digit', 
          hour12: false,
          timeZone: userTimezone
        });
        
        return (
          <div style={{ fontSize: '13px' }}>
            <div>{dateStr}</div>
            <div style={{ color: colors.text.secondary, fontSize: '11px' }}>
              {timeStr}
            </div>
          </div>
        );
      },
    },
    {
      title: 'Exchange',
      dataIndex: 'exchange',
      key: 'exchange',
      width: 100,
      filters: [
        { text: 'NYSE', value: 'NYSE' },
        { text: 'NASDAQ', value: 'NASDAQ' },
        { text: 'AMEX', value: 'AMEX' },
      ],
      onFilter: (value, record) => record.exchange === value,
    },
    {
      title: 'Actions',
      key: 'actions',
      width: 100,
      align: 'center',
      fixed: 'right',
      render: (_: any, record: Position) => (
        <Button
          type="primary"
          danger
          size="small"
          icon={<CloseOutlined />}
          loading={closingPositions.has(record.symbol)}
          onClick={() => handleClosePosition(record.symbol, record.quantity)}
        >
          Close
        </Button>
      ),
    },
  ];

  // Empty state
  if (!loading && positions.length === 0) {
    return (
      <div
        style={{
          textAlign: 'center',
          padding: '48px 24px',
          color: colors.text.tertiary,
        }}
      >
        <p style={{ fontSize: '16px', marginBottom: '8px' }}>
          No open positions
        </p>
        <p style={{ fontSize: '14px' }}>
          Place an order to see your positions here
        </p>
      </div>
    );
  }

  return (
    <Table<Position>
      columns={columns}
      dataSource={positions}
      loading={loading}
      rowKey="symbol"
      pagination={false}
      scroll={{ x: 1000 }}
      size="middle"
      style={{
        background: colors.backgrounds.secondary,
      }}
      rowClassName={(record) => {
        // Highlight profitable positions
        return record.unrealizedPnL > 0 ? 'position-row-profit' : '';
      }}
    />
  );
};

/**
 * BacktestForm Component
 * 
 * Form for configuring and running a backtest on a trading strategy.
 * Allows users to set date ranges, initial capital, and optional parameter overrides.
 */

import React, { useState } from 'react';
import { 
  Form, 
  Select, 
  DatePicker, 
  InputNumber, 
  Button, 
  Card, 
  Space,
  Switch,
  Collapse,
  Alert
} from 'antd';
import { PlayCircleOutlined, SettingOutlined } from '@ant-design/icons';
import dayjs, { Dayjs } from 'dayjs';
import type { BacktestRequest } from '../../../types/backtest';

const { RangePicker } = DatePicker;

interface BacktestFormProps {
  strategies: Array<{ id: string; name: string; type: string }>;
  onSubmit: (strategyId: string, request: BacktestRequest) => void;
  loading?: boolean;
}

export const BacktestForm: React.FC<BacktestFormProps> = ({ 
  strategies, 
  onSubmit, 
  loading = false 
}) => {
  const [form] = Form.useForm();
  const [selectedStrategy, setSelectedStrategy] = useState<string | null>(null);
  const [useCustomParams, setUseCustomParams] = useState(false);

  const handleSubmit = (values: Record<string, unknown>) => {
    const dateRange = values.dateRange as [Dayjs, Dayjs];
    const [startDate, endDate] = dateRange;
    
    const request: BacktestRequest = {
      strategy_id: values.strategyId as string,
      start_date: startDate.format('YYYY-MM-DD'),
      end_date: endDate.format('YYYY-MM-DD'),
      initial_capital: values.initialCapital as number,
    };

    if (useCustomParams && values.customParameters) {
      request.parameters = values.customParameters as Record<string, unknown>;
    }

    onSubmit(values.strategyId as string, request);
  };

  // Default date range: last 6 months
  const defaultDateRange: [Dayjs, Dayjs] = [
    dayjs().subtract(6, 'months'),
    dayjs()
  ];

  // Disable future dates
  const disabledDate = (current: Dayjs) => {
    return current && current > dayjs().endOf('day');
  };

  return (
    <Card 
      title={
        <Space>
          <PlayCircleOutlined />
          Run Backtest
        </Space>
      }
    >
      <Form
        form={form}
        layout="vertical"
        onFinish={handleSubmit}
        initialValues={{
          dateRange: defaultDateRange,
          initialCapital: 100000,
        }}
      >
        {/* Strategy Selection */}
        <Form.Item
          label="Trading Strategy"
          name="strategyId"
          rules={[{ required: true, message: 'Please select a strategy' }]}
        >
          <Select
            placeholder="Select a strategy to backtest"
            onChange={setSelectedStrategy}
            showSearch
            optionFilterProp="children"
            size="large"
          >
            {strategies.map((strategy) => (
              <Select.Option key={strategy.id} value={strategy.id}>
                <Space>
                  <span style={{ fontWeight: 500 }}>{strategy.name}</span>
                  <span style={{ color: '#8c8c8c' }}>({strategy.type})</span>
                </Space>
              </Select.Option>
            ))}
          </Select>
        </Form.Item>

        {/* Date Range */}
        <Form.Item
          label="Backtest Period"
          name="dateRange"
          rules={[{ required: true, message: 'Please select date range' }]}
        >
          <RangePicker
            style={{ width: '100%' }}
            size="large"
            disabledDate={disabledDate}
            format="YYYY-MM-DD"
            allowClear={false}
          />
        </Form.Item>

        {/* Initial Capital */}
        <Form.Item
          label="Initial Capital"
          name="initialCapital"
          rules={[
            { required: true, message: 'Please enter initial capital' },
            { 
              type: 'number', 
              min: 1000, 
              message: 'Minimum capital is $1,000' 
            },
          ]}
        >
          <InputNumber
            style={{ width: '100%' }}
            size="large"
            formatter={(value) => `$ ${value}`.replace(/\B(?=(\ d{3})+(?!\d))/g, ',')}
            parser={(value) => value?.replace(/\$\s?|(,*)/g, '') as unknown as number}
            step={1000}
            min={1000}
          />
        </Form.Item>

        {/* Advanced Options */}
        <Collapse 
          ghost
          items={[
            {
              key: 'advanced',
              label: (
                <Space>
                  <SettingOutlined />
                  Advanced Options
                </Space>
              ),
              children: (
                <Space direction="vertical" style={{ width: '100%' }}>
                  {/* Custom Parameters Toggle */}
                  <Form.Item label="Use Custom Parameters" style={{ marginBottom: 8 }}>
                    <Switch 
                      checked={useCustomParams}
                      onChange={setUseCustomParams}
                    />
                  </Form.Item>

                  {useCustomParams && (
                    <Alert
                      message="Custom Parameters"
                      description="Custom parameter overrides will be added in the next iteration. The backtest will use the strategy's default parameters."
                      type="info"
                      showIcon
                      style={{ marginBottom: 16 }}
                    />
                  )}
                </Space>
              ),
            },
          ]}
        />

        {/* Submit Button */}
        <Form.Item style={{ marginTop: 24, marginBottom: 0 }}>
          <Button
            type="primary"
            htmlType="submit"
            loading={loading}
            disabled={!selectedStrategy || loading}
            size="large"
            block
            icon={<PlayCircleOutlined />}
          >
            {loading ? 'Running Backtest...' : 'Run Backtest'}
          </Button>
        </Form.Item>

        {/* Info Alert */}
        {selectedStrategy && (
          <Alert
            message="Backtest Information"
            description="The backtest will simulate your strategy's performance using historical data. This may take a few moments depending on the date range selected."
            type="info"
            showIcon
            style={{ marginTop: 16 }}
          />
        )}
      </Form>
    </Card>
  );
};

export default BacktestForm;

/**
 * EquityCurveChart Component
 * 
 * Displays the equity curve from a backtest result showing portfolio value over time.
 * Includes area chart visualization with tooltips and reference lines.
 */

import React from 'react';
import { Card, Empty, Spin } from 'antd';
import { LineChartOutlined } from '@ant-design/icons';
import {
  Line,
  Area,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  ReferenceLine,
  ComposedChart,
} from 'recharts';
import dayjs from 'dayjs';
import type { EquityPoint } from '../../../types/backtest';

interface EquityCurveChartProps {
  equityCurve: EquityPoint[];
  initialCapital: number;
  loading?: boolean;
  height?: number;
}

export const EquityCurveChart: React.FC<EquityCurveChartProps> = ({
  equityCurve,
  initialCapital,
  loading = false,
  height = 400,
}) => {
  // Transform data for Recharts
  const chartData = equityCurve.map((point) => ({
    date: dayjs(point.date).format('MMM DD, YYYY'),
    timestamp: new Date(point.date).getTime(),
    equity: point.value,
    cash: point.cash,
    positions: point.positions_value,
  }));

  // Custom tooltip
  const CustomTooltip = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const data = payload[0].payload;
      const returnPct = ((data.equity - initialCapital) / initialCapital) * 100;

      return (
        <div
          style={{
            backgroundColor: 'rgba(255, 255, 255, 0.96)',
            border: '1px solid #d9d9d9',
            borderRadius: '4px',
            padding: '12px',
            boxShadow: '0 2px 8px rgba(0,0,0,0.15)',
          }}
        >
          <p style={{ margin: 0, fontWeight: 600, marginBottom: 8 }}>
            {data.date}
          </p>
          <p style={{ margin: 0, color: '#1890ff' }}>
            Total Equity: ${data.equity.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
          </p>
          <p style={{ margin: 0, color: returnPct >= 0 ? '#52c41a' : '#ff4d4f' }}>
            Return: {returnPct >= 0 ? '+' : ''}{returnPct.toFixed(2)}%
          </p>
          <p style={{ margin: 0, color: '#8c8c8c', fontSize: '12px', marginTop: 4 }}>
            Cash: ${data.cash.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
          </p>
          <p style={{ margin: 0, color: '#8c8c8c', fontSize: '12px' }}>
            Positions: ${data.positions.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
          </p>
        </div>
      );
    }
    return null;
  };

  // Format Y-axis values
  const formatYAxis = (value: number) => {
    if (value >= 1000000) {
      return `$${(value / 1000000).toFixed(1)}M`;
    } else if (value >= 1000) {
      return `$${(value / 1000).toFixed(0)}K`;
    }
    return `$${value}`;
  };

  if (loading) {
    return (
      <Card>
        <div style={{ textAlign: 'center', padding: '60px 0' }}>
          <Spin size="large" />
        </div>
      </Card>
    );
  }

  if (!equityCurve || equityCurve.length === 0) {
    return (
      <Card>
        <Empty description="No equity curve data available" />
      </Card>
    );
  }

  return (
    <Card
      title={
        <span>
          <LineChartOutlined style={{ marginRight: 8 }} />
          Equity Curve
        </span>
      }
    >
      <ResponsiveContainer width="100%" height={height}>
        <ComposedChart
          data={chartData}
          margin={{ top: 10, right: 30, left: 20, bottom: 10 }}
        >
          <defs>
            <linearGradient id="equityGradient" x1="0" y1="0" x2="0" y2="1">
              <stop offset="5%" stopColor="#1890ff" stopOpacity={0.3} />
              <stop offset="95%" stopColor="#1890ff" stopOpacity={0} />
            </linearGradient>
          </defs>
          
          <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
          
          <XAxis
            dataKey="timestamp"
            type="number"
            domain={['dataMin', 'dataMax']}
            tickFormatter={(timestamp: number) => dayjs(timestamp).format('MMM DD')}
            stroke="#8c8c8c"
            style={{ fontSize: '12px' }}
          />
          
          <YAxis
            tickFormatter={formatYAxis}
            stroke="#8c8c8c"
            style={{ fontSize: '12px' }}
          />
          
          <Tooltip content={<CustomTooltip />} />
          
          <Legend
            wrapperStyle={{ paddingTop: '20px' }}
            iconType="line"
          />
          
          {/* Initial capital reference line */}
          <ReferenceLine
            y={initialCapital}
            stroke="#8c8c8c"
            strokeDasharray="5 5"
            label={{
              value: 'Initial Capital',
              position: 'insideTopRight',
              fill: '#8c8c8c',
              fontSize: 12,
            }}
          />
          
