/**
 * Performance Charts Component
 * Historical performance tracking and trend analysis
 * Phase 6 Day 5 Implementation
 */

import React from 'react';
import {
  Card,
  Select,
  Space,
  Typography,
  Row,
  Col,
  DatePicker,
  Button,
  Empty,
  Alert,
  Statistic,
  Tag,
  Spin,
} from 'antd';
import {
  LineChartOutlined,
  DownloadOutlined,
  RiseOutlined,
  FallOutlined,
} from '@ant-design/icons';
import { useQuery } from '@tanstack/react-query';
import { Line } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
  Filler,
} from 'chart.js';
import dayjs, { Dayjs } from 'dayjs';
import { mlApi, mlQueryKeys, mlQueryOptions } from '@/services/mlApi';
import { colors } from '@/styles/theme';
import type { ModelInfo } from '@/types/ml';

// Register Chart.js components
ChartJS.register(
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Title,
  Tooltip,
  Legend,
  Filler
);

const { RangePicker } = DatePicker;
const { Text } = Typography;
const { Option } = Select;

interface PerformanceChartsProps {
  preselectedModelIds?: string[];
}

export const PerformanceCharts: React.FC<PerformanceChartsProps> = ({
  preselectedModelIds = [],
}) => {
  const [selectedModelIds, setSelectedModelIds] = React.useState<string[]>(
    preselectedModelIds
  );
  const [selectedMetric, setSelectedMetric] = React.useState<string>('accuracy');
  const [dateRange, setDateRange] = React.useState<[Dayjs, Dayjs]>([
    dayjs().subtract(30, 'days'),
    dayjs(),
  ]);

  // Fetch all models for selection
  const { data: modelsData } = useQuery({
    queryKey: mlQueryKeys.lists(),
    queryFn: () => mlApi.listModels(),
    ...mlQueryOptions.models,
  });

  // Handle model selection (max 4 models)
  const handleModelSelect = (modelIds: string[]) => {
    if (modelIds.length <= 4) {
      setSelectedModelIds(modelIds);
    }
  };

  // Generate mock historical data (in production, this would come from API)
  const generateHistoricalData = (_modelId: string, model: ModelInfo) => {
    const days = Math.abs(dateRange[0].diff(dateRange[1], 'days'));
    const data: { date: string; value: number }[] = [];

    for (let i = 0; i <= days; i++) {
      const date = dateRange[0].add(i, 'days').format('YYYY-MM-DD');
      // Simulate gradual improvement with some noise
      const metrics = model.metrics as Record<string, number>;
      const baseValue = metrics[selectedMetric] || 0.5;
      const trend = i / days * 0.1; // 10% improvement over time
      const noise = (Math.random() - 0.5) * 0.05; // ┬▒2.5% random variation
      const value = Math.max(0, Math.min(1, baseValue - 0.1 + trend + noise));
      
      data.push({ date, value });
    }

    return data;
  };

  // Prepare chart data
  const chartData = React.useMemo(() => {
    if (!modelsData?.models || selectedModelIds.length === 0) return null;

    const selectedModels = modelsData.models.filter((m: ModelInfo) =>
      selectedModelIds.includes(m.id)
    );

    if (selectedModels.length === 0) return null;

    // Get all dates for x-axis
    const dates = generateHistoricalData(selectedModels[0].id, selectedModels[0]).map(
      (d) => d.date
    );

    const datasets = selectedModels.map((model: ModelInfo, index: number) => {
      const historicalData = generateHistoricalData(model.id, model);
      const color = getModelColor(index);

      return {
        label: `${model.name} (v${model.version})`,
        data: historicalData.map((d) => d.value),
        borderColor: color,
        backgroundColor: `${color}33`,
        borderWidth: 2,
        pointRadius: 3,
        pointHoverRadius: 5,
        fill: true,
        tension: 0.4,
      };
    });

    return { labels: dates, datasets };
  }, [modelsData, selectedModelIds, selectedMetric, dateRange]);

  // Get color for model by index
  const getModelColor = (index: number): string => {
    const colorPalette = [
      colors.brand.primary,
      colors.semantic.success,
      colors.semantic.warning,
      colors.semantic.info,
    ];
    return colorPalette[index % colorPalette.length];
  };

  // Chart options
  const chartOptions = {
    responsive: true,
    maintainAspectRatio: false,
    interaction: {
      mode: 'index' as const,
      intersect: false,
    },
    scales: {
      x: {
        ticks: {
          color: colors.text.secondary,
          maxRotation: 45,
          minRotation: 45,
        },
        grid: { color: colors.backgrounds.border },
        title: {
          display: true,
          text: 'Date',
          color: colors.text.primary,
        },
      },
      y: {
        beginAtZero: true,
        max: 1,
        ticks: {
          color: colors.text.secondary,
          callback: (value: string | number) => `${(Number(value) * 100).toFixed(0)}%`,
        },
        grid: { color: colors.backgrounds.border },
        title: {
          display: true,
          text: selectedMetric.charAt(0).toUpperCase() + selectedMetric.slice(1),
          color: colors.text.primary,
        },
      },
    },
    plugins: {
      legend: {
        position: 'bottom' as const,
        labels: {
          color: colors.text.primary,
          usePointStyle: true,
          padding: 15,
        },
      },
      tooltip: {
        callbacks: {
          label: (context: { dataset: { label?: string }; parsed: { y: number } }) => {
            const label = context.dataset.label || '';
            const value = (context.parsed.y * 100).toFixed(2);
            return `${label}: ${value}%`;
          },
        },
      },
    },
  };

  // Calculate trend
  const calculateTrend = (model: ModelInfo): {
    direction: 'up' | 'down' | 'flat';
    change: number;
  } => {
    const historicalData = generateHistoricalData(model.id, model);
    const firstValue = historicalData[0].value;
    const lastValue = historicalData[historicalData.length - 1].value;
    const change = ((lastValue - firstValue) / firstValue) * 100;

    return {
      direction: change > 1 ? 'up' : change < -1 ? 'down' : 'flat',
      change: Math.abs(change),
    };
  };

  // Available metrics
  const availableMetrics = [
    { value: 'accuracy', label: 'Accuracy' },
    { value: 'precision', label: 'Precision' },
    { value: 'recall', label: 'Recall' },
    { value: 'f1_score', label: 'F1 Score' },
    { value: 'mae', label: 'MAE' },
    { value: 'rmse', label: 'RMSE' },
    { value: 'r2_score', label: 'R┬▓ Score' },
  ];

  // Export data
  const handleExport = () => {
    if (!chartData) return;

    const csv = [
      ['Date', ...chartData.datasets.map((d) => d.label)].join(','),
      ...chartData.labels.map((date, i) =>
        [date, ...chartData.datasets.map((d) => d.data[i])].join(',')
      ),
    ].join('\n');

    const blob = new Blob([csv], { type: 'text/csv' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `performance-${selectedMetric}-${new Date().toISOString()}.csv`;
    a.click();
    window.URL.revokeObjectURL(url);
  };

  return (
    <Space direction="vertical" size="large" style={{ width: '100%' }}>
      {/* Controls */}
      <Card>
        <Space direction="vertical" size="middle" style={{ width: '100%' }}>
          <Row gutter={16}>
            <Col xs={24} md={12}>
              <Space direction="vertical" size="small" style={{ width: '100%' }}>
                <Text type="secondary">Select Models (up to 4)</Text>
                <Select
                  mode="multiple"
                  style={{ width: '100%' }}
                  placeholder="Select models to track performance"
                  value={selectedModelIds}
                  onChange={handleModelSelect}
                  maxTagCount="responsive"
                >
                  {modelsData?.models?.map((model: ModelInfo) => (
                    <Option key={model.id} value={model.id}>
                      {model.name} (v{model.version})
                    </Option>
                  ))}
                </Select>
              </Space>
            </Col>
            <Col xs={24} md={6}>
              <Space direction="vertical" size="small" style={{ width: '100%' }}>
                <Text type="secondary">Metric</Text>
                <Select
                  style={{ width: '100%' }}
                  value={selectedMetric}
                  onChange={setSelectedMetric}
                >
                  {availableMetrics.map((metric) => (
                    <Option key={metric.value} value={metric.value}>
                      {metric.label}
                    </Option>
                  ))}
                </Select>
              </Space>
            </Col>
            <Col xs={24} md={6}>
              <Space direction="vertical" size="small" style={{ width: '100%' }}>
                <Text type="secondary">Date Range</Text>
                <RangePicker
                  style={{ width: '100%' }}
                  value={dateRange}
                  onChange={(dates) => {
                    if (dates && dates[0] && dates[1]) {
                      setDateRange([dates[0], dates[1]]);
                    }
                  }}
                  presets={[
                    { label: 'Last 7 days', value: [dayjs().subtract(7, 'days'), dayjs()] },
                    { label: 'Last 30 days', value: [dayjs().subtract(30, 'days'), dayjs()] },
                    { label: 'Last 90 days', value: [dayjs().subtract(90, 'days'), dayjs()] },
                  ]}
                />
              </Space>
            </Col>
          </Row>

          {selectedModelIds.length > 4 && (
            <Alert
              message="Maximum 4 models can be displayed at once"
              type="warning"
              showIcon
              closable
            />
          )}
        </Space>
      </Card>

      {/* Summary Stats */}
      {selectedModelIds.length > 0 && modelsData && (
        <Card title="Performance Summary">
          <Row gutter={16}>
            {modelsData.models
              .filter((m: ModelInfo) => selectedModelIds.includes(m.id))
              .map((model: ModelInfo, index: number) => {
                const trend = calculateTrend(model);
                const metricsMap = model.metrics as Record<string, number>;
                const currentValue = metricsMap[selectedMetric] || 0;

                return (
                  <Col key={model.id} xs={24} sm={12} lg={6}>
                    <Card
                      variant="outlined"
                      style={{
                        borderColor: getModelColor(index),
                        borderWidth: 2,
                      }}
                    >
                      <Space direction="vertical" size="small" style={{ width: '100%' }}>
                        <Text strong>{model.name}</Text>
                        <Text type="secondary" style={{ fontSize: 12 }}>
                          v{model.version}
                        </Text>
                        <Statistic
                          title={
                            selectedMetric.charAt(0).toUpperCase() + selectedMetric.slice(1)
                          }
                          value={(currentValue * 100).toFixed(2)}
                          suffix="%"
                          valueStyle={{
                            fontSize: 20,
                            color:
                              currentValue > 0.8
                                ? colors.semantic.success
                                : currentValue > 0.6
                                ? colors.semantic.info
                                : colors.semantic.warning,
                          }}
                        />
                        <Tag
                          icon={
                            trend.direction === 'up' ? (
                              <RiseOutlined />
                            ) : trend.direction === 'down' ? (
                              <FallOutlined />
                            ) : null
                          }
                          color={
                            trend.direction === 'up'
                              ? 'success'
                              : trend.direction === 'down'
                              ? 'error'
                              : 'default'
                          }
                        >
                          {trend.direction === 'flat'
                            ? 'Stable'
                            : `${trend.change.toFixed(1)}%`}
                        </Tag>
                      </Space>
                    </Card>
                  </Col>
                );
              })}
          </Row>
        </Card>
      )}

      {/* Chart */}
      {selectedModelIds.length === 0 ? (
        <Card>
          <Empty
            description="Select models to view performance trends"
            image={Empty.PRESENTED_IMAGE_SIMPLE}
          />
        </Card>
      ) : (
        <Card
          title={
            <Space>
              <LineChartOutlined />
              <span>Performance Over Time</span>
            </Space>
          }
          extra={
            <Button icon={<DownloadOutlined />} onClick={handleExport}>
              Export CSV
            </Button>
          }
        >
          <div style={{ height: 400 }}>
            {chartData ? (
              <Line data={chartData} options={chartOptions} />
            ) : (
              <Spin tip="Loading performance data..." />
            )}
          </div>
        </Card>
      )}
    </Space>
  );
};

/**
 * Training Progress Monitor Component
 * Real-time display of model training progress
 * Phase 6 Day 4 Implementation
 */

import React, { useEffect } from 'react';
import {
  Card,
  Progress,
  Space,
  Typography,
  Row,
  Col,
  Statistic,
  Button,
  Tag,
  Divider,
  Empty,
  Spin,
  Alert,
  App,
} from 'antd';
import {
  ClockCircleOutlined,
  CheckCircleOutlined,
  CloseCircleOutlined,
  StopOutlined,
  ReloadOutlined,
  ThunderboltOutlined,
} from '@ant-design/icons';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import dayjs from 'dayjs';
import duration from 'dayjs/plugin/duration';
import relativeTime from 'dayjs/plugin/relativeTime';
import { mlApi, mlQueryKeys, mlQueryOptions } from '@/services/mlApi';
import { colors } from '@/styles/theme';

dayjs.extend(duration);
dayjs.extend(relativeTime);

const { Title, Text } = Typography;

export interface TrainingProgressMonitorProps {
  trainingId?: string;
}

/**
 * Training Progress Monitor Component
 * Displays real-time training status and metrics
 */
export const TrainingProgressMonitor: React.FC<TrainingProgressMonitorProps> = ({ trainingId }) => {
  const { message } = App.useApp();
  const queryClient = useQueryClient();

  // Fetch training status with auto-refresh
  const {
    data: progress,
    isLoading,
    error,
    refetch,
  } = useQuery({
    queryKey: mlQueryKeys.trainingJob(trainingId || ''),
    queryFn: () => mlApi.getTrainingStatus(trainingId!),
    enabled: !!trainingId,
    ...mlQueryOptions.training, // 2s polling
  });

  // Cancel training mutation
  const cancelMutation = useMutation({
    mutationFn: (id: string) => mlApi.cancelTraining(id),
    onSuccess: () => {
      message.success('Training cancelled successfully');
      queryClient.invalidateQueries({ queryKey: mlQueryKeys.trainingJob(trainingId || '') });
      queryClient.invalidateQueries({ queryKey: mlQueryKeys.lists() });
      queryClient.invalidateQueries({ queryKey: mlQueryKeys.stats() });
    },
    onError: (error: any) => {
      message.error(error.response?.data?.detail || 'Failed to cancel training');
    },
  });

  // Auto-stop polling when training completes
  useEffect(() => {
    if (progress && (progress.status === 'completed' || progress.status === 'failed' || progress.status === 'cancelled')) {
      queryClient.cancelQueries({ queryKey: mlQueryKeys.trainingJob(trainingId || '') });
    }
  }, [progress, trainingId, queryClient]);

  // Handle cancel
  const handleCancel = () => {
    if (trainingId) {
      cancelMutation.mutate(trainingId);
    }
  };

  // Get status color
  const getStatusColor = (status: string) => {
    switch (status) {
      case 'running':
        return colors.semantic.info;
      case 'completed':
        return colors.semantic.success;
      case 'failed':
        return colors.semantic.error;
      case 'cancelled':
        return colors.semantic.warning;
      default:
        return colors.text.tertiary;
    }
  };

  // Get status icon
  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'running':
      case 'pending':
        return <ClockCircleOutlined style={{ color: colors.semantic.info }} />;
      case 'completed':
        return <CheckCircleOutlined style={{ color: colors.semantic.success }} />;
      case 'failed':
        return <CloseCircleOutlined style={{ color: colors.semantic.error }} />;
      case 'cancelled':
        return <StopOutlined style={{ color: colors.semantic.warning }} />;
      default:
        return null;
    }
  };

  // Format ETA
  const formatETA = (seconds?: number) => {
    if (!seconds) return 'Calculating...';
    const dur = dayjs.duration(seconds, 'seconds');
    const hours = Math.floor(dur.asHours());
    const minutes = dur.minutes();
    const secs = dur.seconds();
    
    if (hours > 0) {
      return `${hours}h ${minutes}m`;
    } else if (minutes > 0) {
      return `${minutes}m ${secs}s`;
    } else {
      return `${secs}s`;
    }
  };

  // No training ID
  if (!trainingId) {
    return (
      <Card>
        <Empty
          description="No training in progress"
          image={Empty.PRESENTED_IMAGE_SIMPLE}
        >
          <Text type="secondary">
            Start a new training job to see progress here
          </Text>
        </Empty>
      </Card>
    );
  }

  // Loading
  if (isLoading) {
    return (
      <Card>
        <div style={{ textAlign: 'center', padding: 40 }}>
          <Spin size="large" />
          <div style={{ marginTop: 16 }}>
            <Text type="secondary">Loading training status...</Text>
          </div>
        </div>
      </Card>
    );
  }

  // Error
  if (error) {
    return (
      <Card>
        <Alert
          message="Failed to load training status"
          description={(error as any).response?.data?.detail || 'Unknown error'}
          type="error"
          showIcon
          action={
            <Button size="small" onClick={() => refetch()}>
              Retry
            </Button>
          }
        />
      </Card>
    );
  }

  // No data
  if (!progress) {
    return (
      <Card>
        <Empty
          description="Training data not found"
          image={Empty.PRESENTED_IMAGE_SIMPLE}
        />
      </Card>
    );
  }

  const isActive = progress.status === 'running' || progress.status === 'pending';
  const isCompleted = progress.status === 'completed';
  const isFailed = progress.status === 'failed';

  return (
    <Card>
      <Space direction="vertical" size="large" style={{ width: '100%' }}>
        {/* Header */}
        <div>
          <Row justify="space-between" align="middle">
            <Col>
              <Space>
                <Title level={4} style={{ margin: 0, color: colors.text.primary }}>
                  {getStatusIcon(progress.status)}
                  <span style={{ marginLeft: 8 }}>Training Progress</span>
                </Title>
                <Tag color={getStatusColor(progress.status)}>
                  {progress.status.toUpperCase()}
                </Tag>
              </Space>
            </Col>
            <Col>
              <Space>
                <Button
                  icon={<ReloadOutlined />}
                  onClick={() => refetch()}
                  loading={isLoading}
                >
                  Refresh
                </Button>
                {isActive && (
                  <Button
                    danger
                    icon={<StopOutlined />}
                    onClick={handleCancel}
                    loading={cancelMutation.isPending}
                  >
                    Cancel Training
                  </Button>
                )}
              </Space>
            </Col>
          </Row>
        </div>

        {/* Training ID */}
        <div>
          <Text type="secondary">Training ID: </Text>
          <Text code>{progress.training_id}</Text>
        </div>

        {/* Progress Bar */}
        <div>
          <Progress
            percent={progress.progress * 100}
            status={isFailed ? 'exception' : isCompleted ? 'success' : 'active'}
            strokeColor={
              isFailed
                ? colors.semantic.error
                : isCompleted
                ? colors.semantic.success
                : colors.semantic.info
            }
            size="default"
          />
        </div>

        {/* Epoch Progress */}
        {progress.total_epochs && (
          <div>
            <Row gutter={16} align="middle">
              <Col>
                <ThunderboltOutlined style={{ color: colors.semantic.info, fontSize: 20 }} />
              </Col>
              <Col flex="auto">
                <Text strong>
                  Epoch {progress.current_epoch || 0} of {progress.total_epochs}
                </Text>
                <br />
                <Progress
                  percent={
                    progress.total_epochs
                      ? ((progress.current_epoch || 0) / progress.total_epochs) * 100
                      : 0
                  }
                  showInfo={false}
                  size={['100%', 8]}
                  strokeColor={colors.brand.primary}
                />
              </Col>
            </Row>
          </div>
        )}

        <Divider />

        {/* Statistics */}
        <Row gutter={[16, 16]}>
          {/* Started At */}
          <Col xs={24} sm={12} md={8}>
            <Statistic
              title="Started"
              value={dayjs(progress.started_at).format('MMM DD, HH:mm')}
              valueStyle={{ fontSize: 14 }}
            />
          </Col>

          {/* ETA */}
          {isActive && progress.eta_seconds && (
            <Col xs={24} sm={12} md={8}>
              <Statistic
                title="Estimated Time Remaining"
                value={formatETA(progress.eta_seconds)}
                valueStyle={{ fontSize: 14, color: colors.semantic.info }}
                prefix={<ClockCircleOutlined />}
              />
            </Col>
          )}

          {/* Completed At */}
          {isCompleted && (
            <Col xs={24} sm={12} md={8}>
              <Statistic
                title="Completed"
                value={dayjs(progress.started_at).fromNow()}
                valueStyle={{ fontSize: 14, color: colors.semantic.success }}
                prefix={<CheckCircleOutlined />}
              />
            </Col>
          )}
        </Row>

        {/* Current Metrics */}
        {progress.current_metrics && Object.keys(progress.current_metrics).length > 0 && (
          <>
            <Divider />
            <div>
              <Title level={5}>Current Metrics</Title>
              <Row gutter={[16, 16]}>
                {Object.entries(progress.current_metrics).map(([key, value]) => (
                  <Col key={key} xs={12} sm={8} md={6}>
                    <Statistic
                      title={key.replace(/_/g, ' ').toUpperCase()}
                      value={typeof value === 'number' ? value.toFixed(4) : value}
                      valueStyle={{ fontSize: 14 }}
                    />
                  </Col>
                ))}
              </Row>
            </div>
          </>
        )}

        {/* Message */}
        {progress.message && (
          <>
            <Divider />
            <Alert
              message={progress.message}
              type={isFailed ? 'error' : isCompleted ? 'success' : 'info'}
              showIcon
            />
          </>
        )}

        {/* Completion Message */}
        {isCompleted && (
          <Alert
            message="Training completed successfully!"
            description="Your model is now ready for predictions. Check the Model Registry for details."
            type="success"
            showIcon
          />
        )}
      </Space>
    </Card>
  );
};

