/**
 * Active Orders Table
 * Displays pending/open orders with real-time updates via WebSocket
 */

import { Table, Tag, Button, Space, Typography, Tooltip, Popconfirm } from 'antd';
import { 
  DeleteOutlined, 
  ClockCircleOutlined,
  CheckCircleOutlined,
  CloseCircleOutlined,
  SyncOutlined
} from '@ant-design/icons';
import type { ColumnsType } from 'antd/es/table';
import { formatCurrency, formatDateTime } from '@/utils/formatters';
import { useCancelOrder } from '@/hooks/useData';
import { colors } from '@/styles/theme';
import type { Order, OrderStatus } from '@/store/ordersStore';

const { Text } = Typography;

interface ActiveOrdersTableProps {
  orders: Order[];
  loading?: boolean;
}

// Status color mapping
const getStatusColor = (status: OrderStatus): string => {
  switch (status) {
    case 'pending':
    case 'submitted':
      return 'processing';
    case 'partially_filled':
      return 'warning';
    case 'filled':
      return 'success';
    case 'cancelled':
      return 'default';
    case 'rejected':
      return 'error';
    default:
      return 'default';
  }
};

// Status icon mapping
const getStatusIcon = (status: OrderStatus) => {
  switch (status) {
    case 'pending':
    case 'submitted':
      return <SyncOutlined spin />;
    case 'partially_filled':
      return <ClockCircleOutlined />;
    case 'filled':
      return <CheckCircleOutlined />;
    case 'cancelled':
      return <CloseCircleOutlined />;
    case 'rejected':
      return <CloseCircleOutlined />;
    default:
      return null;
  }
};

export const ActiveOrdersTable: React.FC<ActiveOrdersTableProps> = ({ 
  orders, 
  loading = false 
}) => {
  const cancelOrderMutation = useCancelOrder();

  const handleCancelOrder = async (orderId: string) => {
    try {
      await cancelOrderMutation.mutateAsync(orderId);
    } catch (error) {
      console.error('Failed to cancel order:', error);
    }
  };

  const columns: ColumnsType<Order> = [
    {
      title: 'Date & Time',
      dataIndex: 'createdAt',
      key: 'createdAt',
      width: 180,
      render: (createdAt: string) => {
        const date = new Date(createdAt);
        const dateStr = date.toLocaleDateString('en-US', { 
          year: 'numeric', 
          month: '2-digit', 
          day: '2-digit' 
        });
        const timeStr = date.toLocaleTimeString('en-US', {
          hour: '2-digit',
          minute: '2-digit',
          second: '2-digit',
          hour12: false
        });
        return (
          <Tooltip title={formatDateTime(createdAt)}>
            <div style={{ fontFamily: 'monospace', fontSize: '12px' }}>
              <div style={{ fontWeight: 'bold' }}>{dateStr}</div>
              <div style={{ color: colors.text.secondary }}>{timeStr}</div>
            </div>
          </Tooltip>
        );
      },
      sorter: (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime(),
      defaultSortOrder: 'descend',
    },
    {
      title: 'Symbol',
      dataIndex: 'symbol',
      key: 'symbol',
      width: 100,
      render: (symbol: string) => (
        <Text strong style={{ fontFamily: 'monospace', fontSize: '14px' }}>
          {symbol}
        </Text>
      ),
      sorter: (a, b) => a.symbol.localeCompare(b.symbol),
    },
    {
      title: 'Side',
      dataIndex: 'side',
      key: 'side',
      width: 80,
      render: (side: 'buy' | 'sell') => (
        <Tag 
          color={side === 'buy' ? 'green' : 'red'}
          style={{ fontWeight: 'bold' }}
        >
          {side.toUpperCase()}
        </Tag>
      ),
      filters: [
        { text: 'Buy', value: 'buy' },
        { text: 'Sell', value: 'sell' },
      ],
      onFilter: (value, record) => record.side === value,
    },
    {
      title: 'Type',
      dataIndex: 'orderType',
      key: 'orderType',
      width: 100,
      render: (orderType: string) => (
        <Tag color="blue">{orderType.toUpperCase()}</Tag>
      ),
    },
    {
      title: 'Qty',
      dataIndex: 'quantity',
      key: 'quantity',
      width: 80,
      align: 'right',
      render: (quantity: number) => (
        <Text style={{ fontFamily: 'monospace' }}>{quantity}</Text>
      ),
    },
    {
      title: 'Filled',
      dataIndex: 'filledQuantity',
      key: 'filledQuantity',
      width: 80,
      align: 'right',
      render: (filledQuantity: number, record: Order) => (
        <Text 
          style={{ 
            fontFamily: 'monospace',
            color: filledQuantity > 0 ? colors.semantic.profit : colors.text.secondary
          }}
        >
          {filledQuantity} / {record.quantity}
        </Text>
      ),
    },
    {
      title: 'Limit Price',
      dataIndex: 'limitPrice',
      key: 'limitPrice',
      width: 120,
      align: 'right',
      render: (limitPrice?: number) => (
        <Text style={{ fontFamily: 'monospace' }}>
          {limitPrice ? formatCurrency(limitPrice) : '-'}
        </Text>
      ),
    },
    {
      title: 'Avg Fill',
      dataIndex: 'averageFillPrice',
      key: 'averageFillPrice',
      width: 120,
      align: 'right',
      render: (avgFillPrice?: number) => (
        <Text style={{ fontFamily: 'monospace' }}>
          {avgFillPrice ? formatCurrency(avgFillPrice) : '-'}
        </Text>
      ),
    },
    {
      title: 'Status',
      dataIndex: 'status',
      key: 'status',
      width: 140,
      render: (status: OrderStatus) => (
        <Tag 
          color={getStatusColor(status)}
          icon={getStatusIcon(status)}
        >
          {status.replace('_', ' ').toUpperCase()}
        </Tag>
      ),
      filters: [
        { text: 'Pending', value: 'pending' },
        { text: 'Submitted', value: 'submitted' },
        { text: 'Partially Filled', value: 'partially_filled' },
        { text: 'Filled', value: 'filled' },
      ],
      onFilter: (value, record) => record.status === value,
    },
    {
      title: 'TIF',
      dataIndex: 'timeInForce',
      key: 'timeInForce',
      width: 60,
      render: (tif: string) => (
        <Text type="secondary" style={{ fontSize: '11px' }}>
          {tif.toUpperCase()}
        </Text>
      ),
    },
    {
      title: 'Actions',
      key: 'actions',
      width: 100,
      align: 'center',
      fixed: 'right',
      render: (_: any, record: Order) => {
        const canCancel = ['pending', 'submitted', 'partially_filled'].includes(record.status);
        
        if (!canCancel) {
          return <Text type="secondary" style={{ fontSize: '12px' }}>-</Text>;
        }

        return (
          <Space size="small">
            <Popconfirm
              title="Cancel Order"
              description={`Cancel ${record.side} order for ${record.symbol}?`}
              onConfirm={() => handleCancelOrder(record.orderId)}
              okText="Yes"
              cancelText="No"
              okButtonProps={{ danger: true }}
            >
              <Tooltip title="Cancel Order">
                <Button
                  type="text"
                  danger
                  size="small"
                  icon={<DeleteOutlined />}
                  loading={cancelOrderMutation.isPending}
                />
              </Tooltip>
            </Popconfirm>
          </Space>
        );
      },
    },
  ];

  return (
    <Table<Order>
      columns={columns}
      dataSource={orders}
      rowKey="orderId"
      loading={loading}
      pagination={{
        pageSize: 20,
        showSizeChanger: true,
        showTotal: (total) => `Total ${total} orders`,
        pageSizeOptions: ['10', '20', '50', '100'],
      }}
      scroll={{ x: 1200 }}
      size="small"
      style={{
        background: colors.backgrounds.secondary,
      }}
      rowClassName={(record) => {
        // Highlight recently updated rows
        const updatedRecently = new Date().getTime() - new Date(record.updatedAt).getTime() < 3000;
        return updatedRecently ? 'highlight-row' : '';
      }}
    />
  );
};

/**
 * Kill Switch Button Component
 * Emergency stop functionality with confirmation modal
 */

import React, { useState } from 'react';
import { Button, Modal, Typography, Alert, Space, message } from 'antd';
import { FireOutlined, ExclamationCircleOutlined } from '@ant-design/icons';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { riskApi } from '../../services/riskApi';
import type { TriggerEmergencyStopRequest } from '../../types/risk';
import './KillSwitchButton.css';

const { Text } = Typography;

interface KillSwitchButtonProps {
  className?: string;
  size?: 'small' | 'middle' | 'large';
  disabled?: boolean;
  onConfirm?: () => void;
  onCancel?: () => void;
}

const KillSwitchButton: React.FC<KillSwitchButtonProps> = ({
  className = '',
  size = 'large',
  disabled = false,
  onConfirm,
  onCancel,
}) => {
  const [showConfirmModal, setShowConfirmModal] = useState(false);
  const [reason, setReason] = useState('');
  const [countdown, setCountdown] = useState(10);
  const queryClient = useQueryClient();

  const emergencyStopMutation = useMutation({
    mutationFn: (request: TriggerEmergencyStopRequest) => riskApi.triggerEmergencyStop(request),
    onSuccess: () => {
      message.success('Emergency stop activated successfully');
      queryClient.invalidateQueries({ queryKey: ['risk'] });
      setShowConfirmModal(false);
      onConfirm?.();
    },
    onError: (error: any) => {
      message.error(`Failed to activate emergency stop: ${error.message}`);
    },
  });

  const handleKillSwitchClick = () => {
    setShowConfirmModal(true);
    setCountdown(10);
    
    // Start countdown
    const timer = setInterval(() => {
      setCountdown((prev) => {
        if (prev <= 1) {
          clearInterval(timer);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);
  };

  const handleConfirmEmergencyStop = () => {
    const request: TriggerEmergencyStopRequest = {
      reason: reason || 'Manual emergency stop triggered',
      stop_all_strategies: true,
      cancel_all_orders: true,
      notify_admin: true,
    };

    emergencyStopMutation.mutate(request);
  };

  const handleCancel = () => {
    setShowConfirmModal(false);
    setReason('');
    setCountdown(10);
    onCancel?.();
  };

  return (
    <>
      <Button
        type="primary"
        danger
        size={size}
        icon={<FireOutlined />}
        className={`kill-switch-button ${className}`}
        onClick={handleKillSwitchClick}
        disabled={disabled || emergencyStopMutation.isPending}
        loading={emergencyStopMutation.isPending}
      >
        EMERGENCY STOP
      </Button>

      <Modal
        title={
          <Space>
            <ExclamationCircleOutlined style={{ color: '#ff4d4f' }} />
            <span style={{ color: '#ff4d4f' }}>EMERGENCY STOP CONFIRMATION</span>
          </Space>
        }
        open={showConfirmModal}
        onOk={handleConfirmEmergencyStop}
        onCancel={handleCancel}
        okText={`CONFIRM STOP ${countdown > 0 ? `(${countdown})` : ''}`}
        cancelText="Cancel"
        okButtonProps={{
          danger: true,
          disabled: countdown > 0,
          loading: emergencyStopMutation.isPending,
        }}
        closable={false}
        maskClosable={false}
        width={600}
        className="kill-switch-modal"
      >
        <Alert
          type="error"
          showIcon
          message="WARNING: This will immediately stop all trading activity"
          description={
            <div style={{ marginTop: 16 }}>
              <p><strong>This action will:</strong></p>
              <ul>
                <li>Stop all active trading strategies</li>
                <li>Cancel all pending orders</li>
                <li>Halt all automated trading</li>
                <li>Notify system administrators</li>
                <li>Create an audit trail record</li>
              </ul>
              <p style={{ marginTop: 16 }}>
                <strong>This action cannot be undone automatically.</strong> 
                Manual intervention will be required to resume trading.
              </p>
              
              <div style={{ marginTop: 16 }}>
                <Text strong>Reason for emergency stop:</Text>
                <textarea
                  value={reason}
                  onChange={(e) => setReason(e.target.value)}
                  placeholder="Optional: Describe the reason for the emergency stop..."
                  style={{
                    width: '100%',
                    marginTop: 8,
                    padding: 8,
                    border: '1px solid #d9d9d9',
                    borderRadius: 4,
                    minHeight: 80,
                  }}
                />
              </div>

              {countdown > 0 && (
                <div style={{ marginTop: 16, textAlign: 'center' }}>
                  <Text type="secondary">
                    Confirmation available in {countdown} seconds...
                  </Text>
                </div>
              )}
            </div>
          }
        />
      </Modal>
    </>
  );
};

export default KillSwitchButton;

/**
 * Strategies List
 * Main table/grid view for all strategies with filtering and actions
 */

import React, { useState, useMemo } from 'react';
import {
  Table,
  Space,
  Button,
  Input,
  Select,
  Row,
  Col,
  App,
  Popconfirm,
  Typography,
} from 'antd';
import type { ColumnsType } from 'antd/es/table';
import {
  PlusOutlined,
  SearchOutlined,
  PlayCircleOutlined,
  PauseCircleOutlined,
  StopOutlined,
  EditOutlined,
  DeleteOutlined,
  EyeOutlined,
  AppstoreOutlined,
  UnorderedListOutlined,
  CopyOutlined,
} from '@ant-design/icons';
import { useNavigate } from 'react-router-dom';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { useStrategiesStore } from '@/store/strategiesStore';
import { strategiesService } from '@/services/strategiesService';
import type { Strategy, StrategyStatus, StrategyType } from '@/types/strategy';
import type { StrategyUpdateMessage } from '@/types/websocket';
import { useWebSocket } from '@/hooks/useWebSocket';
import { StrategyStatusBadge } from '@/components/strategies/StrategyStatusBadge';
import { StrategyCard } from '@/components/strategies/StrategyCard';
import { colors, fontSizes } from '@/styles/theme';
import { formatCurrency, formatPercent } from '@/utils/formatters';
import { getStrategyTypeConfig } from '@/utils/strategyTypeConfig';

const { Search } = Input;
const { Text } = Typography;

type ViewMode = 'table' | 'grid';

export const StrategiesList: React.FC = () => {
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const { message } = App.useApp();
  const strategies = useStrategiesStore((state) => state.strategies);
  const updateStrategy = useStrategiesStore((state) => state.updateStrategy);
  const removeStrategy = useStrategiesStore((state) => state.removeStrategy);

  const [viewMode, setViewMode] = useState<ViewMode>('table');
  const [searchText, setSearchText] = useState('');
  const [statusFilter, setStatusFilter] = useState<StrategyStatus | 'all'>('all');
  const [typeFilter, setTypeFilter] = useState<StrategyType | 'all'>('all');
  const [loadingIds, setLoadingIds] = useState<Set<string>>(new Set());

  // WebSocket handler for real-time strategy updates
  const handleStrategyUpdate = React.useCallback((wsMessage: StrategyUpdateMessage) => {
    // Handle delete action
    if (wsMessage.data.action === 'deleted') {
      removeStrategy(wsMessage.data.strategyId);
      queryClient.invalidateQueries({ queryKey: ['strategies'] });
      message.info(`Strategy deleted`);
      return;
    }
    
    // Handle update action (status changes, etc.)
    if (wsMessage.data.action === 'updated' && wsMessage.data.strategy) {
      const strategy = wsMessage.data.strategy;
      updateStrategy(strategy.strategyId, strategy);
      queryClient.invalidateQueries({ queryKey: ['strategies'] });
      
      // Show notification for status changes
      if (strategy.status === 'active') {
        message.success(`Strategy "${strategy.name}" started`);
      } else if (strategy.status === 'paused') {
        message.info(`Strategy "${strategy.name}" paused`);
      } else if (strategy.status === 'stopped') {
        message.info(`Strategy "${strategy.name}" stopped`);
      } else if (strategy.status === 'error') {
        message.error(`Strategy "${strategy.name}" encountered an error`);
      }
      return;
    }
    
    // Direct strategy data format (current backend format)
    if (wsMessage.data.strategyId) {
      updateStrategy(wsMessage.data.strategyId, wsMessage.data);
      // Don't show duplicate notifications if they were already shown by the mutation
    }
  }, [updateStrategy, removeStrategy, queryClient]);

  // Subscribe to strategy updates via WebSocket
  useWebSocket('strategies', handleStrategyUpdate);

  // Start strategy mutation
  const startMutation = useMutation({
    mutationFn: (strategyId: string) => strategiesService.startStrategy(strategyId),
    onSuccess: (updatedStrategy) => {
      message.success(`Strategy "${updatedStrategy.name}" started successfully`);
      queryClient.invalidateQueries({ queryKey: ['strategies'] });
      setLoadingIds((prev) => {
        const next = new Set(prev);
        next.delete(updatedStrategy.strategyId);
        return next;
      });
    },
    onError: (error: unknown, strategyId: string) => {
      const axiosError = error as { response?: { data?: { detail?: string } } };
      message.error(axiosError?.response?.data?.detail || 'Failed to start strategy');
      setLoadingIds((prev) => {
        const next = new Set(prev);
        next.delete(strategyId);
        return next;
      });
    },
  });

  // Pause strategy mutation
  const pauseMutation = useMutation({
    mutationFn: (strategyId: string) => strategiesService.pauseStrategy(strategyId),
    onSuccess: (updatedStrategy) => {
      message.success(`Strategy "${updatedStrategy.name}" paused successfully`);
      queryClient.invalidateQueries({ queryKey: ['strategies'] });
      setLoadingIds((prev) => {
        const next = new Set(prev);
        next.delete(updatedStrategy.strategyId);
        return next;
      });
    },
    onError: (error: unknown, strategyId: string) => {
      const axiosError = error as { response?: { data?: { detail?: string } } };
      message.error(axiosError?.response?.data?.detail || 'Failed to pause strategy');
      setLoadingIds((prev) => {
        const next = new Set(prev);
        next.delete(strategyId);
        return next;
      });
    },
  });

  // Stop strategy mutation
  const stopMutation = useMutation({
    mutationFn: (strategyId: string) => strategiesService.stopStrategy(strategyId),
    onSuccess: (updatedStrategy) => {
      message.success(`Strategy "${updatedStrategy.name}" stopped successfully`);
      queryClient.invalidateQueries({ queryKey: ['strategies'] });
      setLoadingIds((prev) => {
        const next = new Set(prev);
        next.delete(updatedStrategy.strategyId);
        return next;
      });
    },
    onError: (error: unknown, strategyId: string) => {
      const axiosError = error as { response?: { data?: { detail?: string } } };
      message.error(axiosError?.response?.data?.detail || 'Failed to stop strategy');
      setLoadingIds((prev) => {
        const next = new Set(prev);
        next.delete(strategyId);
        return next;
      });
    },
  });

  // Delete strategy mutation
  const deleteMutation = useMutation({
    mutationFn: (strategyId: string) => strategiesService.deleteStrategy(strategyId),
    onSuccess: (_, strategyId) => {
      message.success('Strategy deleted successfully');
      queryClient.invalidateQueries({ queryKey: ['strategies'] });
      setLoadingIds((prev) => {
        const next = new Set(prev);
        next.delete(strategyId);
        return next;
      });
    },
    onError: (error: unknown, strategyId: string) => {
      const axiosError = error as { response?: { data?: { detail?: string } } };
      message.error(axiosError?.response?.data?.detail || 'Failed to delete strategy');
      setLoadingIds((prev) => {
        const next = new Set(prev);
        next.delete(strategyId);
        return next;
      });
    },
  });

  // Action handlers
  const handleStart = (strategyId: string) => {
    setLoadingIds((prev) => new Set(prev).add(strategyId));
    startMutation.mutate(strategyId);
  };

  const handlePause = (strategyId: string) => {
    setLoadingIds((prev) => new Set(prev).add(strategyId));
    pauseMutation.mutate(strategyId);
  };

  const handleStop = (strategyId: string) => {
    setLoadingIds((prev) => new Set(prev).add(strategyId));
    stopMutation.mutate(strategyId);
  };

  const handleEdit = (strategyId: string) => {
    navigate(`/strategies/${strategyId}/edit`);
  };

  const handleDelete = (strategyId: string) => {
    setLoadingIds((prev) => new Set(prev).add(strategyId));
    deleteMutation.mutate(strategyId);
  };

  const handleView = (strategyId: string) => {
    navigate(`/strategies/${strategyId}`);
  };

  // Filtered strategies
  const filteredStrategies = useMemo(() => {
    return strategies.filter((strategy) => {
      // Search filter
      if (searchText) {
        const searchLower = searchText.toLowerCase();
        const matchesName = strategy.name.toLowerCase().includes(searchLower);
        const matchesDescription = strategy.description
          .toLowerCase()
          .includes(searchLower);
        if (!matchesName && !matchesDescription) {
          return false;
        }
      }

      // Status filter
      if (statusFilter !== 'all' && strategy.status !== statusFilter) {
        return false;
      }

      // Type filter
      if (typeFilter !== 'all' && strategy.strategyType !== typeFilter) {
        return false;
      }

      return true;
    });
  }, [strategies, searchText, statusFilter, typeFilter]);

  // Table columns
  const columns: ColumnsType<Strategy> = [
    {
      title: 'Name',
      dataIndex: 'name',
      key: 'name',
      width: 200,
      fixed: 'left',
      render: (name: string, record: Strategy) => {
        const typeConfig = getStrategyTypeConfig(record.strategyType);
        return (
          <Space direction="vertical" size={0}>
            <Button
              type="link"
              onClick={() => handleView(record.strategyId)}
              style={{ padding: 0, height: 'auto', fontSize: fontSizes.base }}
            >
              <Space>
                <span style={{ fontSize: '16px' }}>{typeConfig.icon}</span>
                {name}
              </Space>
            </Button>
            <Text type="secondary" style={{ fontSize: fontSizes.xs, color: typeConfig.color }}>
              {typeConfig.label}
            </Text>
          </Space>
        );
      },
    },
    {
      title: 'Status',
      dataIndex: 'status',
      key: 'status',
      width: 120,
      filters: [
        { text: 'Active', value: 'active' },
        { text: 'Paused', value: 'paused' },
        { text: 'Stopped', value: 'stopped' },
        { text: 'Error', value: 'error' },
      ],
      onFilter: (value, record) => record.status === value,
      render: (status: StrategyStatus) => <StrategyStatusBadge status={status} />,
    },
    {
      title: 'Description',
      dataIndex: 'description',
      key: 'description',
      ellipsis: true,
      render: (description: string) => (
        <Text type="secondary" style={{ fontSize: fontSizes.sm }}>
          {description}
        </Text>
      ),
    },
    {
      title: 'Total P&L',
      key: 'totalPnL',
      width: 140,
      sorter: (a, b) =>
        (a.performance?.totalPnL ?? 0) - (b.performance?.totalPnL ?? 0),
      render: (_, record: Strategy) => {
        if (!record.performance) return <Text type="secondary">N/A</Text>;
        const pnl = record.performance.totalPnL;
        return (
          <Text
            strong
            style={{
              color: pnl >= 0 ? colors.semantic.profit : colors.semantic.loss,
            }}
          >
            {formatCurrency(pnl)}
          </Text>
        );
      },
    },
    {
      title: 'Win Rate',
      key: 'winRate',
      width: 120,
      sorter: (a, b) =>
        (a.performance?.winRate ?? 0) - (b.performance?.winRate ?? 0),
      render: (_, record: Strategy) => {
        if (!record.performance) return <Text type="secondary">N/A</Text>;
        return (
          <Text strong>{formatPercent(record.performance.winRate)}</Text>
        );
      },
    },
    {
      title: 'Total Trades',
      key: 'totalTrades',
      width: 120,
      sorter: (a, b) =>
        (a.performance?.totalTrades ?? 0) - (b.performance?.totalTrades ?? 0),
      render: (_, record: Strategy) => {
        if (!record.performance) return <Text type="secondary">N/A</Text>;
        return <Text>{record.performance.totalTrades}</Text>;
      },
    },
    {
      title: 'Sharpe Ratio',
      key: 'sharpeRatio',
      width: 130,
      sorter: (a, b) =>
        (a.performance?.sharpeRatio ?? 0) - (b.performance?.sharpeRatio ?? 0),
      render: (_, record: Strategy) => {
        if (!record.performance) return <Text type="secondary">N/A</Text>;
        const sharpe = record.performance.sharpeRatio;
        return (
          <Text
            style={{
              color: sharpe >= 1 ? colors.semantic.success : colors.text.secondary,
            }}
          >
            {sharpe.toFixed(2)}
          </Text>
        );
      },
    },
    {
      title: 'Actions',
      key: 'actions',
      width: 200,
      fixed: 'right',
      render: (_, record: Strategy) => {
        const isLoading = loadingIds.has(record.strategyId);
        const canStart = record.status === 'stopped' || record.status === 'paused';
        const canPause = record.status === 'active';
        const canStop = record.status === 'active' || record.status === 'paused';

        return (
          <Space size="small">
            <Button
              type="text"
              size="small"
              icon={<EyeOutlined />}
              onClick={() => handleView(record.strategyId)}
            />
            {canStart && (
              <Button
                type="text"
                size="small"
                icon={<PlayCircleOutlined />}
                onClick={() => handleStart(record.strategyId)}
                loading={isLoading}
                style={{ color: colors.semantic.success }}
              />
            )}
            {canPause && (
              <Button
                type="text"
                size="small"
                icon={<PauseCircleOutlined />}
                onClick={() => handlePause(record.strategyId)}
                loading={isLoading}
                style={{ color: colors.semantic.warning }}
              />
            )}
            {canStop && (
              <Button
                type="text"
                size="small"
                icon={<StopOutlined />}
                onClick={() => handleStop(record.strategyId)}
                loading={isLoading}
                style={{ color: colors.semantic.stopped }}
              />
            )}
            <Button
              type="text"
              size="small"
              icon={<EditOutlined />}
              onClick={() => handleEdit(record.strategyId)}
            />
            <Button
              type="text"
              size="small"
              icon={<CopyOutlined />}
              onClick={() => {
                const strategy = strategies.find(s => s.strategyId === record.strategyId);
                if (strategy) {
                  navigate('/strategies/builder', { state: { cloneFrom: strategy } });
                }
              }}
              title="Clone this strategy"
            />
            <Popconfirm
              title="Delete Strategy"
              description="Are you sure you want to delete this strategy? This action cannot be undone."
              onConfirm={() => handleDelete(record.strategyId)}
              okText="Delete"
              cancelText="Cancel"
              okButtonProps={{ danger: true }}
            >
              <Button
                type="text"
                size="small"
                danger
                icon={<DeleteOutlined />}
                loading={isLoading}
              />
            </Popconfirm>
          </Space>
        );
      },
    },
  ];

  return (
    <div>
      {/* Filters and Actions */}
      <Row gutter={[16, 16]} style={{ marginBottom: 24 }}>
        <Col xs={24} sm={12} md={8}>
          <Search
            placeholder="Search strategies..."
            allowClear
            prefix={<SearchOutlined />}
            value={searchText}
            onChange={(e) => setSearchText(e.target.value)}
            style={{ width: '100%' }}
          />
        </Col>
        <Col xs={12} sm={6} md={4}>
          <Select
            value={statusFilter}
            onChange={setStatusFilter}
            style={{ width: '100%' }}
            options={[
              { label: 'All Status', value: 'all' },
              { label: 'Active', value: 'active' },
              { label: 'Paused', value: 'paused' },
              { label: 'Stopped', value: 'stopped' },
              { label: 'Error', value: 'error' },
            ]}
          />
        </Col>
        <Col xs={12} sm={6} md={4}>
          <Select
            value={typeFilter}
            onChange={setTypeFilter}
            style={{ width: '100%' }}
            options={[
              { label: 'All Types', value: 'all' },
              // Implementation Types
              { label: 'Momentum', value: 'momentum' },
              { label: 'Mean Reversion', value: 'mean_reversion' },
              { label: 'Ensemble', value: 'ensemble' },
              { label: 'Statistical Arbitrage', value: 'stat_arb' },
              // Classification Types
              { label: 'Technical Analysis', value: 'technical' },
              { label: 'Fundamental Analysis', value: 'fundamental' },
              { label: 'Quantitative', value: 'quantitative' },
              { label: 'Hybrid Strategy', value: 'hybrid' },
            ]}
          />
        </Col>
        <Col xs={24} sm={12} md={8} style={{ textAlign: 'right' }}>
          <Space>
            <Button
              type={viewMode === 'table' ? 'primary' : 'default'}
              icon={<UnorderedListOutlined />}
              onClick={() => setViewMode('table')}
            >
              Table
            </Button>
            <Button
              type={viewMode === 'grid' ? 'primary' : 'default'}
              icon={<AppstoreOutlined />}
              onClick={() => setViewMode('grid')}
            >
              Grid
            </Button>
            <Button
              type="primary"
              icon={<PlusOutlined />}
              onClick={() => navigate('/strategies/builder')}
            >
              Create with Wizard
            </Button>
            <Button
              icon={<PlusOutlined />}
              onClick={() => navigate('/strategies/new')}
            >
              Quick Create
            </Button>
          </Space>
        </Col>
      </Row>

      {/* Table View */}
      {viewMode === 'table' && (
        <Table
          columns={columns}
          dataSource={filteredStrategies}
          rowKey="strategyId"
          scroll={{ x: 1200 }}
          pagination={{
            pageSize: 10,
            showSizeChanger: true,
            showTotal: (total) => `Total ${total} strategies`,
          }}
        />
      )}

      {/* Grid View */}
      {viewMode === 'grid' && (
        <Row gutter={[16, 16]}>
          {filteredStrategies.map((strategy) => (
            <Col key={strategy.strategyId} xs={24} sm={12} lg={8} xl={6}>
              <StrategyCard
                strategy={strategy}
                onStart={handleStart}
                onPause={handlePause}
                onStop={handleStop}
                onEdit={handleEdit}
                onDelete={handleDelete}
                loading={loadingIds.has(strategy.strategyId)}
              />
            </Col>
          ))}
        </Row>
      )}

      {/* Empty State */}
      {filteredStrategies.length === 0 && (
        <div
          style={{
            textAlign: 'center',
            padding: 48,
            background: colors.backgrounds.secondary,
            borderRadius: 8,
          }}
        >
          <Text type="secondary" style={{ fontSize: fontSizes.lg }}>
            {searchText || statusFilter !== 'all' || typeFilter !== 'all'
              ? 'No strategies match your filters'
              : 'No strategies yet. Create your first strategy to get started!'}
          </Text>
        </div>
      )}
    </div>
  );
};

/**
 * Strategy Builder - Multi-Step Wizard
 * 
 * Guided interface for creating trading strategies with pre-configured templates.
 * 
 * Architecture:
 * - 5-step wizard flow (Basic Info ΓåÆ Parameters ΓåÆ Risk ΓåÆ Execution ΓåÆ Review)
 * - Template-driven parameter forms (loads from backend)
 * - Validation at each step before progression
 * - Final submission creates strategy via POST /api/v1/strategies
 * 
 * @module features/strategies/StrategyBuilderPage
 */

import React, { useState } from 'react';
import { Steps, Card, Button, Space, App } from 'antd';
import { useNavigate } from 'react-router-dom';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import type { StrategyFormData, StepValidation } from '@/types/strategy';
import { apiClient } from '@/services/api';
import { BasicInfoStep } from './wizard/BasicInfoStep';
import { ParametersStep } from './wizard/ParametersStep';
import { RiskLimitsStep } from './wizard/RiskLimitsStep';
import { ExecutionSettingsStep } from './wizard/ExecutionSettingsStep';
import { ReviewStep } from './wizard/ReviewStep';

const { Step } = Steps;

/**
 * Initial form data with sensible defaults
 */
const getInitialFormData = (): StrategyFormData => ({
  // Step 1
  name: '',
  description: '',
  strategyType: null,
  symbols: [],
  
  // Step 2
  parameters: {},
  
  // Step 3
  riskLimits: {
    maxPositionSize: 10000,
    dailyLossLimit: 1000,
    maxDrawdown: 0.15,
    stopLoss: 0.05,
    takeProfit: 0.10,
  },
  
  // Step 4
  executionSettings: {
    tradingHoursStart: '09:30',
    tradingHoursEnd: '16:00',
    executionFrequency: '5min',
    maxTradesPerDay: 10,
  },
});

/**
 * Strategy Builder Page
 * Main wizard container with step navigation and submission logic
 */
export const StrategyBuilderPage: React.FC = () => {
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const { message } = App.useApp(); // Use App context for messages
  
  const [currentStep, setCurrentStep] = useState(0);
  const [formData, setFormData] = useState<StrategyFormData>(getInitialFormData());
  const [stepValidations, setStepValidations] = useState<StepValidation[]>([
    { valid: false, errors: {} },
    { valid: false, errors: {} },
    { valid: false, errors: {} },
    { valid: false, errors: {} },
    { valid: true, errors: {} }, // Review step always valid
  ]);

  /**
   * Mutation for creating strategy
   */
  const createStrategyMutation = useMutation({
    mutationFn: async (data: StrategyFormData) => {
      // Backend expects snake_case field names
      const payload = {
        name: data.name,
        description: data.description,
        strategy_type: data.strategyType, // Convert to snake_case
        symbols: data.symbols,
        parameters: {
          ...data.parameters,
          // Include risk limits and execution settings in parameters
          riskLimits: data.riskLimits,
          executionSettings: data.executionSettings,
        },
      };
      
      console.log('Submitting strategy:', payload); // Debug log
      
      const response = await apiClient.post('/strategies', payload);
      return response.data;
    },
    onSuccess: (data) => {
      message.success(`Strategy "${data.name}" created successfully!`);
      queryClient.invalidateQueries({ queryKey: ['strategies'] });
      navigate('/strategies');
    },
    onError: (error: any) => {
      const errorMsg = error.response?.data?.detail || 'Failed to create strategy';
      message.error(errorMsg);
      console.error('Strategy creation error:', error);
    },
  });

  /**
   * Update form data for a specific step
   */
  const updateFormData = (stepData: Partial<StrategyFormData>) => {
    setFormData(prev => ({ ...prev, ...stepData }));
  };

  /**
   * Update validation for a specific step
   */
  const updateStepValidation = (stepIndex: number, validation: StepValidation) => {
    setStepValidations(prev => {
      const updated = [...prev];
      updated[stepIndex] = validation;
      return updated;
    });
  };

  /**
   * Navigate to next step (with validation check)
   */
  const handleNext = () => {
    if (!stepValidations[currentStep].valid) {
      message.warning('Please fix validation errors before continuing');
      return;
    }
    
    setCurrentStep(prev => Math.min(prev + 1, 4));
  };

  /**
   * Navigate to previous step
   */
  const handlePrev = () => {
    setCurrentStep(prev => Math.max(prev - 1, 0));
  };

  /**
   * Submit final form data
   */
  const handleSubmit = () => {
    if (!stepValidations.every(v => v.valid)) {
      message.error('Please complete all steps before submitting');
      return;
    }
    
    createStrategyMutation.mutate(formData);
  };

  /**
   * Cancel and return to strategies list
   */
  const handleCancel = () => {
    navigate('/strategies');
  };

  /**
   * Render step content based on current step
   */
  const renderStepContent = () => {
    switch (currentStep) {
      case 0:
        return (
          <BasicInfoStep
            formData={formData}
            onChange={updateFormData}
            onValidationChange={(validation: StepValidation) => updateStepValidation(0, validation)}
          />
        );
      case 1:
        return (
          <ParametersStep
            formData={formData}
            onChange={updateFormData}
            onValidationChange={(validation: StepValidation) => updateStepValidation(1, validation)}
          />
        );
      case 2:
        return (
          <RiskLimitsStep
            formData={formData}
            onChange={updateFormData}
            onValidationChange={(validation: StepValidation) => updateStepValidation(2, validation)}
          />
        );
      case 3:
        return (
          <ExecutionSettingsStep
            formData={formData}
            onChange={updateFormData}
            onValidationChange={(validation: StepValidation) => updateStepValidation(3, validation)}
          />
        );
      case 4:
        return <ReviewStep formData={formData} />;
      default:
        return null;
    }
  };

  return (
    <div style={{ padding: '24px', maxWidth: '1200px', margin: '0 auto' }}>
      <Card>
        <h1 style={{ marginBottom: '24px' }}>Create New Strategy</h1>
        
        {/* Step Progress Indicator */}
        <Steps current={currentStep} style={{ marginBottom: '40px' }}>
          <Step title="Basic Info" description="Name and type" />
          <Step title="Parameters" description="Strategy settings" />
          <Step title="Risk Limits" description="Risk management" />
          <Step title="Execution" description="Trading hours" />
          <Step title="Review" description="Confirm details" />
        </Steps>

        {/* Step Content */}
        <div style={{ minHeight: '400px', marginBottom: '24px' }}>
          {renderStepContent()}
        </div>

        {/* Navigation Buttons */}
        <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '24px' }}>
          <Space>
            <Button onClick={handleCancel}>Cancel</Button>
            {currentStep > 0 && (
              <Button onClick={handlePrev}>Previous</Button>
            )}
          </Space>
          
          <Space>
            {currentStep < 4 && (
              <Button 
                type="primary" 
                onClick={handleNext}
                disabled={!stepValidations[currentStep].valid}
              >
                Next
              </Button>
            )}
            {currentStep === 4 && (
              <Button 
                type="primary" 
                onClick={handleSubmit}
                loading={createStrategyMutation.isPending}
              >
                Create Strategy
              </Button>
            )}
          </Space>
        </div>
      </Card>
    </div>
  );
};

/**
 * Strategy Detail
 * Detailed view of a single strategy with performance metrics and actions
 */

import React, { useEffect } from 'react';
import {
  Card,
  Row,
  Col,
  Button,
  Space,
  Typography,
  Descriptions,
  App,
  Popconfirm,
  Spin,
} from 'antd';
import {
  ArrowLeftOutlined,
  EditOutlined,
  DeleteOutlined,
  PlayCircleOutlined,
  PauseCircleOutlined,
  StopOutlined,
  CopyOutlined,
} from '@ant-design/icons';
import { useNavigate, useParams } from 'react-router-dom';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { strategiesService } from '@/services/strategiesService';
import { useStrategiesStore } from '@/store/strategiesStore';
import type { StrategyUpdateMessage } from '@/types/websocket';
import { useWebSocket } from '@/hooks/useWebSocket';
import { StrategyStatusBadge } from '@/components/strategies/StrategyStatusBadge';
import { StrategyPerformanceChart } from '@/components/strategies/StrategyPerformanceChart';
import { colors, fontSizes } from '@/styles/theme';

const { Title, Text } = Typography;

export const StrategyDetail: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const { message } = App.useApp();
  const updateStrategy = useStrategiesStore((state) => state.updateStrategy);

  // Fetch strategy details
  const {
    data: strategy,
    isLoading,
    error,
  } = useQuery({
    queryKey: ['strategy', id],
    queryFn: () => strategiesService.getStrategy(id!),
    enabled: !!id,
  });

  // Update store when strategy data changes
  useEffect(() => {
    if (strategy) {
      updateStrategy(strategy.strategyId, strategy);
    }
  }, [strategy, updateStrategy]);

  // WebSocket handler for real-time strategy updates
  const handleStrategyUpdate = React.useCallback((wsMessage: StrategyUpdateMessage) => {
    // Only process updates for this specific strategy
    if (wsMessage.data.strategyId === id) {
      // Update local query cache
      queryClient.setQueryData(['strategy', id], wsMessage.data);
      
      // Update store
      updateStrategy(wsMessage.data.strategyId, wsMessage.data);
      
      // Show notification for status changes
      if (wsMessage.data.status === 'active') {
        message.success(`Strategy started`);
      } else if (wsMessage.data.status === 'paused') {
        message.info(`Strategy paused`);
      } else if (wsMessage.data.status === 'stopped') {
        message.info(`Strategy stopped`);
      } else if (wsMessage.data.status === 'error') {
        message.error(`Strategy encountered an error`);
      }
    }
  }, [id, updateStrategy, queryClient]);

  // Subscribe to strategy updates via WebSocket
  useWebSocket('strategies', handleStrategyUpdate);

  // Start strategy mutation
  const startMutation = useMutation({
    mutationFn: () => strategiesService.startStrategy(id!),
    onSuccess: (updatedStrategy) => {
      message.success(`Strategy "${updatedStrategy.name}" started successfully`);
      queryClient.invalidateQueries({ queryKey: ['strategy', id] });
      queryClient.invalidateQueries({ queryKey: ['strategies'] });
    },
    onError: (error: unknown) => {
      const axiosError = error as { response?: { data?: { detail?: string } } };
      message.error(axiosError?.response?.data?.detail || 'Failed to start strategy');
    },
  });

  // Pause strategy mutation
  const pauseMutation = useMutation({
    mutationFn: () => strategiesService.pauseStrategy(id!),
    onSuccess: (updatedStrategy) => {
      message.success(`Strategy "${updatedStrategy.name}" paused successfully`);
      queryClient.invalidateQueries({ queryKey: ['strategy', id] });
      queryClient.invalidateQueries({ queryKey: ['strategies'] });
    },
    onError: (error: unknown) => {
      const axiosError = error as { response?: { data?: { detail?: string } } };
      message.error(axiosError?.response?.data?.detail || 'Failed to pause strategy');
    },
  });

  // Stop strategy mutation
  const stopMutation = useMutation({
    mutationFn: () => strategiesService.stopStrategy(id!),
    onSuccess: (updatedStrategy) => {
      message.success(`Strategy "${updatedStrategy.name}" stopped successfully`);
      queryClient.invalidateQueries({ queryKey: ['strategy', id] });
      queryClient.invalidateQueries({ queryKey: ['strategies'] });
    },
    onError: (error: unknown) => {
      const axiosError = error as { response?: { data?: { detail?: string } } };
      message.error(axiosError?.response?.data?.detail || 'Failed to stop strategy');
    },
  });

  // Delete strategy mutation
  const deleteMutation = useMutation({
    mutationFn: () => strategiesService.deleteStrategy(id!),
    onSuccess: () => {
      message.success('Strategy deleted successfully');
      navigate('/strategies');
    },
    onError: (error: unknown) => {
      const axiosError = error as { response?: { data?: { detail?: string } } };
      message.error(axiosError?.response?.data?.detail || 'Failed to delete strategy');
    },
  });

  if (isLoading) {
    return (
      <div style={{ textAlign: 'center', padding: 48 }}>
        <Spin size="large" spinning tip="Loading strategy...">
          <div style={{ minHeight: 200 }} />
        </Spin>
      </div>
    );
  }

  if (error || !strategy || !strategy.strategyId) {
    return (
      <Card>
        <div style={{ textAlign: 'center', padding: 48 }}>
          <Text type="danger" style={{ fontSize: fontSizes.lg }}>
            Failed to load strategy. Please try again.
          </Text>
          <div style={{ marginTop: 16 }}>
            <Button onClick={() => navigate('/strategies')}>Back to Strategies</Button>
          </div>
        </div>
      </Card>
    );
  }

  const canStart = strategy?.status === 'stopped' || strategy?.status === 'paused';
  const canPause = strategy?.status === 'active';
  const canStop = strategy?.status === 'active' || strategy?.status === 'paused';
  const isLoading_actions =
    startMutation.isPending || pauseMutation.isPending || stopMutation.isPending || deleteMutation.isPending;

  return (
    <div>
      {/* Header */}
      <Row justify="space-between" align="middle" style={{ marginBottom: 24 }}>
        <Col>
          <Space>
            <Button
              icon={<ArrowLeftOutlined />}
              onClick={() => navigate('/strategies')}
            >
              Back
            </Button>
            <Title level={3} style={{ margin: 0 }}>
              {strategy?.name || 'Loading...'}
            </Title>
            <StrategyStatusBadge status={strategy?.status || 'stopped'} />
          </Space>
        </Col>
        <Col>
          <Space>
            {canStart && (
              <Button
                type="primary"
                icon={<PlayCircleOutlined />}
                onClick={() => startMutation.mutate()}
                loading={isLoading_actions}
              >
                Start
              </Button>
            )}
            {canPause && (
              <Button
                icon={<PauseCircleOutlined />}
                onClick={() => pauseMutation.mutate()}
                loading={isLoading_actions}
              >
                Pause
              </Button>
            )}
            {canStop && (
              <Button
                danger
                icon={<StopOutlined />}
                onClick={() => stopMutation.mutate()}
                loading={isLoading_actions}
              >
                Stop
              </Button>
            )}
            <Button
              icon={<EditOutlined />}
              onClick={() => navigate(`/strategies/${id}/edit`)}
            >
              Edit
            </Button>
            <Button
              icon={<CopyOutlined />}
              onClick={() => {
                // Clone strategy by navigating to builder with strategy data pre-filled
                navigate('/strategies/builder', { 
                  state: { 
                    cloneFrom: strategy 
                  } 
                });
              }}
            >
              Clone
            </Button>
            <Popconfirm
              title="Delete Strategy"
              description="Are you sure you want to delete this strategy? This action cannot be undone."
              onConfirm={() => deleteMutation.mutate()}
              okText="Delete"
              cancelText="Cancel"
              okButtonProps={{ danger: true }}
            >
              <Button danger icon={<DeleteOutlined />} loading={isLoading_actions}>
                Delete
              </Button>
            </Popconfirm>
          </Space>
        </Col>
      </Row>

      {/* Strategy Details */}
      <Row gutter={[24, 24]}>
        <Col xs={24} lg={16}>
          <Card
            title="Strategy Information"
            style={{
              background: colors.backgrounds.secondary,
              borderColor: colors.backgrounds.border,
            }}
          >
            <Descriptions column={1} bordered>
              <Descriptions.Item label="Strategy ID">
                <Text copyable style={{ fontFamily: 'monospace' }}>
                  {strategy?.strategyId || 'N/A'}
                </Text>
              </Descriptions.Item>
              <Descriptions.Item label="Name">{strategy?.name || 'N/A'}</Descriptions.Item>
              <Descriptions.Item label="Type">
                <Text style={{ textTransform: 'capitalize' }}>
                  {strategy?.strategyType || 'N/A'}
                </Text>
              </Descriptions.Item>
              <Descriptions.Item label="Status">
                <StrategyStatusBadge status={strategy?.status || 'stopped'} />
              </Descriptions.Item>
              <Descriptions.Item label="Description">
                {strategy?.description || 'No description'}
              </Descriptions.Item>
              <Descriptions.Item label="Parameters">
                <pre
                  style={{
                    background: colors.backgrounds.tertiary,
                    padding: 12,
                    borderRadius: 4,
                    overflow: 'auto',
                    margin: 0,
                  }}
                >
                  {JSON.stringify(strategy.parameters, null, 2)}
                </pre>
              </Descriptions.Item>
              <Descriptions.Item label="Created">
                {new Date(strategy.createdAt).toLocaleString()}
              </Descriptions.Item>
              <Descriptions.Item label="Last Updated">
                {new Date(strategy.updatedAt).toLocaleString()}
              </Descriptions.Item>
            </Descriptions>
          </Card>
        </Col>

        <Col xs={24} lg={8}>
          <Card
            title="Quick Stats"
            style={{
              background: colors.backgrounds.secondary,
              borderColor: colors.backgrounds.border,
            }}
          >
            {strategy.performance ? (
              <Space direction="vertical" size={16} style={{ width: '100%' }}>
                <div>
                  <Text type="secondary" style={{ fontSize: fontSizes.sm }}>
                    Total P&L
                  </Text>
                  <div>
                    <Text
                      strong
                      style={{
                        fontSize: fontSizes['2xl'],
                        color:
                          (strategy.performance.totalPnL ?? 0) >= 0
                            ? colors.semantic.profit
                            : colors.semantic.loss,
                      }}
                    >
                      ${(strategy.performance.totalPnL ?? 0).toFixed(2)}
                    </Text>
                  </div>
                </div>
                <div>
                  <Text type="secondary" style={{ fontSize: fontSizes.sm }}>
                    Win Rate
                  </Text>
                  <div>
                    <Text strong style={{ fontSize: fontSizes.xl }}>
                      {((strategy.performance.winRate ?? 0) * 100).toFixed(1)}%
                    </Text>
                  </div>
                </div>
                <div>
                  <Text type="secondary" style={{ fontSize: fontSizes.sm }}>
                    Total Trades
                  </Text>
                  <div>
                    <Text strong style={{ fontSize: fontSizes.xl }}>
                      {strategy.performance.totalTrades ?? 0}
                    </Text>
                  </div>
                </div>
                <div>
                  <Text type="secondary" style={{ fontSize: fontSizes.sm }}>
                    Sharpe Ratio
                  </Text>
                  <div>
                    <Text
                      strong
                      style={{
                        fontSize: fontSizes.xl,
                        color:
                          (strategy.performance.sharpeRatio ?? 0) >= 1
                            ? colors.semantic.success
                            : colors.text.secondary,
                      }}
                    >
                      {(strategy.performance.sharpeRatio ?? 0).toFixed(2)}
                    </Text>
                  </div>
                </div>
                <div>
                  <Text type="secondary" style={{ fontSize: fontSizes.sm }}>
                    Max Drawdown
                  </Text>
                  <div>
                    <Text
                      strong
                      style={{
                        fontSize: fontSizes.xl,
                        color: colors.semantic.loss,
                      }}
                    >
                      ${(strategy.performance.maxDrawdown ?? 0).toFixed(2)}
                    </Text>
                  </div>
                </div>
              </Space>
            ) : (
              <Text type="secondary">No performance data available yet.</Text>
            )}
          </Card>
        </Col>
      </Row>

      {/* Performance Chart */}
      {strategy.performance && (
        <div style={{ marginTop: 24 }}>
          <StrategyPerformanceChart
            performance={strategy.performance}
            strategyName={strategy.name}
          />
        </div>
      )}
    </div>
  );
};

/**
 * Basic Info Step - Step 1 of Strategy Builder
 * 
 * Collects:
 * - Strategy name (unique, required)
 * - Description (optional but recommended)
 * - Strategy type (template selector)
 * - Symbols to trade (multi-select with search)
 * 
 * @module features/strategies/wizard/BasicInfoStep
 */

import React, { useEffect, useState } from 'react';
import { Form, Input, Select, Card, Typography, Alert, Spin } from 'antd';
import type { StrategyFormData, StepValidation } from '@/types/strategy';
import { useStrategyTemplates } from '@/hooks/useStrategyTemplates';

const { TextArea } = Input;
const { Option } = Select;
const { Title, Paragraph } = Typography;

interface BasicInfoStepProps {
  formData: StrategyFormData;
  onChange: (data: Partial<StrategyFormData>) => void;
  onValidationChange: (validation: StepValidation) => void;
}

/**
 * Common stock symbols for quick selection
 */
const COMMON_SYMBOLS = [
  'AAPL', 'GOOGL', 'MSFT', 'AMZN', 'TSLA', 'NVDA', 'META',
  'JPM', 'V', 'WMT', 'JNJ', 'PG', 'UNH', 'HD', 'BAC', 'DIS'
];

export const BasicInfoStep: React.FC<BasicInfoStepProps> = ({
  formData,
  onChange,
  onValidationChange,
}) => {
  const [form] = Form.useForm();
  const { data: templates, isLoading, error } = useStrategyTemplates();
  const [localErrors, setLocalErrors] = useState<Record<string, string>>({});

  /**
   * Validate form fields
   */
  const validateForm = (): StepValidation => {
    const errors: Record<string, string> = {};
    
    if (!formData.name || formData.name.trim().length === 0) {
      errors.name = 'Strategy name is required';
    } else if (formData.name.length < 3) {
      errors.name = 'Strategy name must be at least 3 characters';
    } else if (formData.name.length > 100) {
      errors.name = 'Strategy name must be less than 100 characters';
    }
    
    if (!formData.strategyType) {
      errors.strategyType = 'Strategy type is required';
    }
    
    if (!formData.symbols || formData.symbols.length === 0) {
      errors.symbols = 'At least one symbol is required';
    } else if (formData.symbols.length > 50) {
      errors.symbols = 'Maximum 50 symbols allowed';
    }
    
    setLocalErrors(errors);
    return {
      valid: Object.keys(errors).length === 0,
      errors,
    };
  };

  /**
   * Notify parent of validation changes
   */
  useEffect(() => {
    const validation = validateForm();
    onValidationChange(validation);
  }, [formData.name, formData.strategyType, formData.symbols]);

  /**
   * Handle field changes
   */
  const handleFieldChange = (field: keyof StrategyFormData, value: any) => {
    onChange({ [field]: value });
  };

  if (isLoading) {
    return (
      <div style={{ textAlign: 'center', padding: '60px 0' }}>
        <Spin size="large" />
        <Paragraph style={{ marginTop: 16 }}>Loading strategy templates...</Paragraph>
      </div>
    );
  }

  if (error) {
    return (
      <Alert
        type="error"
        message="Failed to load strategy templates"
        description={error.message}
        showIcon
      />
    );
  }

  return (
    <div>
      <Title level={3}>Basic Information</Title>
      <Paragraph type="secondary">
        Start by naming your strategy, selecting a type, and choosing which symbols to trade.
      </Paragraph>

      <Form
        form={form}
        layout="vertical"
        initialValues={{
          name: formData.name,
          description: formData.description,
          strategyType: formData.strategyType,
          symbols: formData.symbols,
        }}
      >
        {/* Strategy Name */}
        <Form.Item
          label="Strategy Name"
          required
          validateStatus={localErrors.name ? 'error' : ''}
          help={localErrors.name}
        >
          <Input
            placeholder="e.g., AAPL Momentum Strategy"
            value={formData.name}
            onChange={e => handleFieldChange('name', e.target.value)}
            maxLength={100}
            showCount
          />
        </Form.Item>

        {/* Description */}
        <Form.Item
          label="Description"
          tooltip="Describe the strategy's logic, goals, and expected behavior"
        >
          <TextArea
            placeholder="e.g., Momentum strategy targeting AAPL with 20-day moving average crossovers"
            value={formData.description}
            onChange={e => handleFieldChange('description', e.target.value)}
            rows={3}
            maxLength={500}
            showCount
          />
        </Form.Item>

        {/* Strategy Type (Template Selector) */}
        <Form.Item
          label="Strategy Type"
          required
          validateStatus={localErrors.strategyType ? 'error' : ''}
          help={localErrors.strategyType}
          tooltip="Select a pre-configured template with appropriate parameters"
        >
          <Select
            placeholder="Select a strategy template"
            value={formData.strategyType}
            onChange={value => handleFieldChange('strategyType', value)}
            showSearch
            optionFilterProp="children"
          >
            {templates?.map(template => (
              <Option key={template.type} value={template.type}>
                <div>
                  <strong>{template.name}</strong>
                  <div style={{ fontSize: '12px', color: '#888' }}>
                    {template.description}
                  </div>
                </div>
              </Option>
            ))}
          </Select>
        </Form.Item>

        {/* Template Info Card */}
        {formData.strategyType && templates && (
          <Card size="small" style={{ marginBottom: 16, backgroundColor: '#f9f9f9' }}>
            {(() => {
              const selectedTemplate = templates.find(t => t.type === formData.strategyType);
              return selectedTemplate ? (
                <div>
                  <strong>{selectedTemplate.name}</strong>
                  <Paragraph type="secondary" style={{ marginBottom: 0, fontSize: '13px' }}>
                    {selectedTemplate.description}
                  </Paragraph>
                  <Paragraph type="secondary" style={{ marginBottom: 0, fontSize: '12px', marginTop: 8 }}>
                    <strong>Category:</strong> {selectedTemplate.category} | 
                    <strong> Parameters:</strong> {selectedTemplate.parameters.length}
                  </Paragraph>
                </div>
              ) : null;
            })()}
          </Card>
        )}

        {/* Symbols */}
        <Form.Item
          label="Symbols to Trade"
          required
          validateStatus={localErrors.symbols ? 'error' : ''}
          help={localErrors.symbols || `${formData.symbols.length} selected`}
          tooltip="Select one or more stock symbols to trade with this strategy"
        >
          <Select
            mode="tags"
            placeholder="Type or select symbols (e.g., AAPL, GOOGL)"
            value={formData.symbols}
            onChange={value => handleFieldChange('symbols', value)}
            tokenSeparators={[',', ' ']}
            style={{ width: '100%' }}
          >
            {COMMON_SYMBOLS.map(symbol => (
              <Option key={symbol} value={symbol}>
                {symbol}
              </Option>
            ))}
          </Select>
        </Form.Item>
      </Form>
    </div>
  );
};

/**
 * Execution Settings Step - Step 4 of Strategy Builder
 * 
 * Configures when and how often the strategy executes:
 * - Trading hours (market hours)
 * - Execution frequency (realtime, 1min, 5min, etc.)
 * - Max trades per day
 * 
 * @module features/strategies/wizard/ExecutionSettingsStep
 */

import React, { useEffect, useState } from 'react';
import { Form, Select, InputNumber, Typography, Card, TimePicker } from 'antd';
import dayjs from 'dayjs';
import type { StrategyFormData, StepValidation } from '@/types/strategy';

const { Title, Paragraph } = Typography;
const { Option } = Select;

interface ExecutionSettingsStepProps {
  formData: StrategyFormData;
  onChange: (data: Partial<StrategyFormData>) => void;
  onValidationChange: (validation: StepValidation) => void;
}

export const ExecutionSettingsStep: React.FC<ExecutionSettingsStepProps> = ({
  formData,
  onChange,
  onValidationChange,
}) => {
  const [form] = Form.useForm();
  const [localErrors, setLocalErrors] = useState<Record<string, string>>({});

  /**
   * Validate execution settings
   */
  const validateForm = (): StepValidation => {
    const errors: Record<string, string> = {};
    const { executionSettings } = formData;
    
    if (!executionSettings.tradingHoursStart) {
      errors.tradingHoursStart = 'Start time is required';
    }
    
    if (!executionSettings.tradingHoursEnd) {
      errors.tradingHoursEnd = 'End time is required';
    }
    
    if (!executionSettings.executionFrequency) {
      errors.executionFrequency = 'Frequency is required';
    }
    
    if (!executionSettings.maxTradesPerDay || executionSettings.maxTradesPerDay <= 0) {
      errors.maxTradesPerDay = 'Must be at least 1';
    }
    
    setLocalErrors(errors);
    return {
      valid: Object.keys(errors).length === 0,
      errors,
    };
  };

  /**
   * Notify parent of validation changes
   */
  useEffect(() => {
    const validation = validateForm();
    onValidationChange(validation);
  }, [formData.executionSettings]);

  /**
   * Handle field changes
   */
  const handleFieldChange = (field: keyof typeof formData.executionSettings, value: any) => {
    onChange({
      executionSettings: {
        ...formData.executionSettings,
        [field]: value,
      },
    });
  };

  return (
    <div>
      <Title level={3}>Execution Settings</Title>
      <Paragraph type="secondary">
        Configure when and how often your strategy executes trades.
      </Paragraph>

      <Form form={form} layout="vertical" style={{ maxWidth: 600 }}>
        {/* Trading Hours */}
        <Card size="small" style={{ marginBottom: 16 }}>
          <Form.Item label="Trading Hours">
            <Paragraph type="secondary" style={{ fontSize: 13, marginBottom: 12 }}>
              Strategy will only execute during these hours (Eastern Time)
            </Paragraph>
            <div style={{ display: 'flex', gap: 12, alignItems: 'center' }}>
              <Form.Item
                label="Start"
                style={{ flex: 1, marginBottom: 0 }}
                validateStatus={localErrors.tradingHoursStart ? 'error' : ''}
                help={localErrors.tradingHoursStart}
              >
                <TimePicker
                  value={dayjs(formData.executionSettings.tradingHoursStart, 'HH:mm')}
                  onChange={(time) => handleFieldChange('tradingHoursStart', time?.format('HH:mm') || '09:30')}
                  format="HH:mm"
                  style={{ width: '100%' }}
                />
              </Form.Item>
              <span style={{ paddingTop: 8 }}>to</span>
              <Form.Item
                label="End"
                style={{ flex: 1, marginBottom: 0 }}
                validateStatus={localErrors.tradingHoursEnd ? 'error' : ''}
                help={localErrors.tradingHoursEnd}
              >
                <TimePicker
                  value={dayjs(formData.executionSettings.tradingHoursEnd, 'HH:mm')}
                  onChange={(time) => handleFieldChange('tradingHoursEnd', time?.format('HH:mm') || '16:00')}
                  format="HH:mm"
                  style={{ width: '100%' }}
                />
              </Form.Item>
            </div>
          </Form.Item>
        </Card>

        {/* Execution Frequency */}
        <Form.Item
          label="Execution Frequency"
          required
          validateStatus={localErrors.executionFrequency ? 'error' : ''}
          help={localErrors.executionFrequency || 'How often the strategy evaluates and executes trades'}
        >
          <Select
            value={formData.executionSettings.executionFrequency}
            onChange={val => handleFieldChange('executionFrequency', val)}
          >
            <Option value="realtime">Realtime (Tick-by-tick)</Option>
            <Option value="1min">Every 1 minute</Option>
            <Option value="5min">Every 5 minutes</Option>
            <Option value="15min">Every 15 minutes</Option>
            <Option value="1hour">Every hour</Option>
          </Select>
        </Form.Item>

        {/* Max Trades Per Day */}
        <Form.Item
          label="Max Trades Per Day"
          required
          validateStatus={localErrors.maxTradesPerDay ? 'error' : ''}
          help={localErrors.maxTradesPerDay || 'Maximum number of trades to execute in a single day'}
        >
          <InputNumber
            value={formData.executionSettings.maxTradesPerDay}
            onChange={val => handleFieldChange('maxTradesPerDay', val ?? 10)}
            min={1}
            max={1000}
            style={{ width: '100%' }}
          />
        </Form.Item>
      </Form>
    </div>
  );
};

/**
 * Parameters Step - Step 2 of Strategy Builder
 * 
 * Dynamically renders parameter form based on selected strategy type.
 * Loads template definition and creates appropriate input controls for each parameter.
 * 
 * @module features/strategies/wizard/ParametersStep
 */

import React, { useEffect, useState } from 'react';
import { Form, InputNumber, Select, Switch, Typography, Alert, Spin, Slider } from 'antd';
import type { StrategyFormData, StepValidation, ParameterDefinition } from '@/types/strategy';
import { useStrategyTemplate, getDefaultParameters } from '@/hooks/useStrategyTemplates';

const { Title, Paragraph } = Typography;
const { Option } = Select;

interface ParametersStepProps {
  formData: StrategyFormData;
  onChange: (data: Partial<StrategyFormData>) => void;
  onValidationChange: (validation: StepValidation) => void;
}

export const ParametersStep: React.FC<ParametersStepProps> = ({
  formData,
  onChange,
  onValidationChange,
}) => {
  const [form] = Form.useForm();
  const { data: template, isLoading } = useStrategyTemplate(formData.strategyType);
  const [localErrors, setLocalErrors] = useState<Record<string, string>>({});

  /**
   * Initialize parameters with template defaults when template loads
   */
  useEffect(() => {
    if (template && Object.keys(formData.parameters).length === 0) {
      const defaults = getDefaultParameters(template);
      onChange({ parameters: defaults });
    }
  }, [template]);

  /**
   * Validate parameter values
   */
  const validateParameters = (): StepValidation => {
    const errors: Record<string, string> = {};
    
    if (!template) {
      errors.template = 'Strategy type not selected';
      return { valid: false, errors };
    }

    // Validate each parameter
    template.parameters.forEach((param: ParameterDefinition) => {
      const value = formData.parameters[param.name];
      
      // Check required
      if (param.required && (value === undefined || value === null || value === '')) {
        errors[param.name] = `${param.label || param.name} is required`;
        return;
      }
      
      // Validate number constraints
      if (param.type === 'number' && value !== undefined && value !== null) {
        if (param.min !== undefined && value < param.min) {
          errors[param.name] = `Must be at least ${param.min}`;
        }
        if (param.max !== undefined && value > param.max) {
          errors[param.name] = `Must be at most ${param.max}`;
        }
      }
    });
    
    setLocalErrors(errors);
    return {
      valid: Object.keys(errors).length === 0,
      errors,
    };
  };

  /**
   * Notify parent of validation changes
   */
  useEffect(() => {
    if (template) {
      const validation = validateParameters();
      onValidationChange(validation);
    }
  }, [formData.parameters, template]);

  /**
   * Handle parameter value changes
   */
  const handleParameterChange = (paramName: string, value: any) => {
    onChange({
      parameters: {
        ...formData.parameters,
        [paramName]: value,
      },
    });
  };

  /**
   * Render input control based on parameter type
   */
  const renderParameterInput = (param: ParameterDefinition) => {
    const value = formData.parameters[param.name] ?? param.default;

    switch (param.type) {
      case 'number':
        // If min/max are defined and range is reasonable, use slider + input
        if (param.min !== undefined && param.max !== undefined && (param.max - param.min) <= 1000) {
          return (
            <div>
              <div style={{ display: 'flex', gap: 12, alignItems: 'center' }}>
                <Slider
                  min={param.min}
                  max={param.max}
                  value={typeof value === 'number' ? value : param.default}
                  onChange={val => handleParameterChange(param.name, val)}
                  style={{ flex: 1 }}
                  step={param.max - param.min > 100 ? 1 : 0.01}
                />
                <InputNumber
                  min={param.min}
                  max={param.max}
                  value={typeof value === 'number' ? value : param.default}
                  onChange={val => handleParameterChange(param.name, val ?? param.default)}
                  style={{ width: 120 }}
                  step={param.max - param.min > 100 ? 1 : 0.01}
                />
              </div>
              <div style={{ fontSize: '12px', color: '#888', marginTop: 4 }}>
                Range: {param.min} - {param.max}
              </div>
            </div>
          );
        } else {
          // Otherwise just input
          return (
            <div>
              <InputNumber
                min={param.min}
                max={param.max}
                value={typeof value === 'number' ? value : param.default}
                onChange={val => handleParameterChange(param.name, val ?? param.default)}
                style={{ width: '100%' }}
              />
              {(param.min !== undefined || param.max !== undefined) && (
                <div style={{ fontSize: '12px', color: '#888', marginTop: 4 }}>
                  {param.min !== undefined && `Min: ${param.min}`}
                  {param.min !== undefined && param.max !== undefined && ' | '}
                  {param.max !== undefined && `Max: ${param.max}`}
                </div>
              )}
            </div>
          );
        }

      case 'select':
        return (
          <Select
            value={value}
            onChange={val => handleParameterChange(param.name, val)}
            style={{ width: '100%' }}
            placeholder={`Select ${param.label || param.name}`}
          >
            {param.options?.map(opt => (
              <Option key={opt.value} value={opt.value}>
                {opt.label}
              </Option>
            ))}
          </Select>
        );

      case 'multiselect':
        return (
          <Select
            mode="multiple"
            value={value}
            onChange={val => handleParameterChange(param.name, val)}
            style={{ width: '100%' }}
            placeholder={`Select ${param.label || param.name}`}
          >
            {param.options?.map(opt => (
              <Option key={opt.value} value={opt.value}>
                {opt.label}
              </Option>
            ))}
          </Select>
        );

      case 'boolean':
        return (
          <Switch
            checked={value}
            onChange={val => handleParameterChange(param.name, val)}
          />
        );

      case 'string':
      default:
        return (
          <input
            type="text"
            value={value}
            onChange={e => handleParameterChange(param.name, e.target.value)}
            style={{ width: '100%' }}
          />
        );
    }
  };

  if (!formData.strategyType) {
    return (
      <Alert
        type="warning"
        message="Strategy Type Required"
        description="Please go back and select a strategy type first."
        showIcon
      />
    );
  }

  if (isLoading) {
    return (
      <div style={{ textAlign: 'center', padding: '60px 0' }}>
        <Spin size="large" />
        <Paragraph style={{ marginTop: 16 }}>Loading parameters for {formData.strategyType}...</Paragraph>
      </div>
    );
  }

  if (!template) {
    return (
      <Alert
        type="error"
        message="Template Not Found"
        description={`Could not load parameters for strategy type: ${formData.strategyType}`}
        showIcon
      />
    );
  }

  return (
    <div>
      <Title level={3}>{template.name} Parameters</Title>
      <Paragraph type="secondary">
        {template.description}
      </Paragraph>

      <Form form={form} layout="vertical" style={{ maxWidth: 800 }}>
        {template.parameters.map((param: ParameterDefinition) => (
          <Form.Item
            key={param.name}
            label={param.label || param.name}
            required={param.required}
            validateStatus={localErrors[param.name] ? 'error' : ''}
            help={localErrors[param.name] || param.description}
            tooltip={param.description}
          >
            {renderParameterInput(param)}
          </Form.Item>
        ))}
      </Form>
    </div>
  );
};

/**
 * Risk Limits Step - Step 3 of Strategy Builder
 * 
 * Configures risk management parameters:
 * - Position size limits
 * - Loss limits (daily/max drawdown)
 * - Stop loss / Take profit percentages
 * 
 * @module features/strategies/wizard/RiskLimitsStep
 */

import React, { useEffect, useState } from 'react';
import { Form, InputNumber, Typography, Card, Row, Col, Slider } from 'antd';
import type { StrategyFormData, StepValidation } from '@/types/strategy';

const { Title, Paragraph, Text } = Typography;

interface RiskLimitsStepProps {
  formData: StrategyFormData;
  onChange: (data: Partial<StrategyFormData>) => void;
  onValidationChange: (validation: StepValidation) => void;
}

export const RiskLimitsStep: React.FC<RiskLimitsStepProps> = ({
  formData,
  onChange,
  onValidationChange,
}) => {
  const [form] = Form.useForm();
  const [localErrors, setLocalErrors] = useState<Record<string, string>>({});

  /**
   * Validate risk limits
   */
  const validateForm = (): StepValidation => {
    const errors: Record<string, string> = {};
    const { riskLimits } = formData;
    
    if (!riskLimits.maxPositionSize || riskLimits.maxPositionSize <= 0) {
      errors.maxPositionSize = 'Must be greater than 0';
    }
    
    if (!riskLimits.dailyLossLimit || riskLimits.dailyLossLimit <= 0) {
      errors.dailyLossLimit = 'Must be greater than 0';
    }
    
    if (riskLimits.maxDrawdown <= 0 || riskLimits.maxDrawdown >= 1) {
      errors.maxDrawdown = 'Must be between 0% and 100%';
    }
    
    if (riskLimits.stopLoss <= 0 || riskLimits.stopLoss >= 1) {
      errors.stopLoss = 'Must be between 0% and 100%';
    }
    
    if (riskLimits.takeProfit <= 0 || riskLimits.takeProfit >= 2) {
      errors.takeProfit = 'Must be between 0% and 200%';
    }
    
    setLocalErrors(errors);
    return {
      valid: Object.keys(errors).length === 0,
      errors,
    };
  };

  /**
   * Notify parent of validation changes
   */
  useEffect(() => {
    const validation = validateForm();
    onValidationChange(validation);
  }, [formData.riskLimits]);

  /**
   * Handle field changes
   */
  const handleFieldChange = (field: keyof typeof formData.riskLimits, value: number | null) => {
    onChange({
      riskLimits: {
        ...formData.riskLimits,
        [field]: value ?? 0,
      },
    });
  };

  return (
    <div>
      <Title level={3}>Risk Management</Title>
      <Paragraph type="secondary">
        Configure risk limits to protect your capital. These limits will automatically stop or limit trading
        when thresholds are reached.
      </Paragraph>

      <Form form={form} layout="vertical" style={{ maxWidth: 800 }}>
        <Row gutter={24}>
          {/* Position Size Limit */}
          <Col span={12}>
            <Card size="small" style={{ marginBottom: 16 }}>
              <Form.Item
                label="Max Position Size"
                required
                validateStatus={localErrors.maxPositionSize ? 'error' : ''}
                help={localErrors.maxPositionSize || 'Maximum dollar value for a single position'}
              >
                <InputNumber
                  value={formData.riskLimits.maxPositionSize}
                  onChange={val => handleFieldChange('maxPositionSize', val)}
                  formatter={value => `$ ${value}`.replace(/\B(?=(\d{3})+(?!\d))/g, ',')}
                  parser={(value) => value?.replace(/\$\s?|(,*)/g, '') as unknown as number}
                  min={100}
                  max={1000000}
                  step={1000}
                  style={{ width: '100%' }}
                />
              </Form.Item>
            </Card>
          </Col>

          {/* Daily Loss Limit */}
          <Col span={12}>
            <Card size="small" style={{ marginBottom: 16 }}>
              <Form.Item
                label="Daily Loss Limit"
                required
                validateStatus={localErrors.dailyLossLimit ? 'error' : ''}
                help={localErrors.dailyLossLimit || 'Max loss per day (trading pauses if reached)'}
              >
                <InputNumber
                  value={formData.riskLimits.dailyLossLimit}
                  onChange={val => handleFieldChange('dailyLossLimit', val)}
                  formatter={value => `$ ${value}`.replace(/\B(?=(\d{3})+(?!\d))/g, ',')}
                  parser={(value) => value?.replace(/\$\s?|(,*)/g, '') as unknown as number}
                  min={10}
                  max={100000}
                  step={100}
                  style={{ width: '100%' }}
                />
              </Form.Item>
            </Card>
          </Col>
        </Row>

        {/* Max Drawdown */}
        <Card size="small" style={{ marginBottom: 16 }}>
          <Form.Item
            label="Maximum Drawdown"
            required
            validateStatus={localErrors.maxDrawdown ? 'error' : ''}
            help={localErrors.maxDrawdown || 'Maximum portfolio decline from peak (strategy stops if exceeded)'}
          >
            <Row gutter={12}>
              <Col span={18}>
                <Slider
                  min={1}
                  max={50}
                  value={formData.riskLimits.maxDrawdown * 100}
                  onChange={val => handleFieldChange('maxDrawdown', val / 100)}
                  marks={{
                    5: '5%',
                    10: '10%',
                    15: '15%',
                    20: '20%',
                    30: '30%',
                    50: '50%',
                  }}
                />
              </Col>
              <Col span={6}>
                <InputNumber
                  min={1}
                  max={50}
                  value={formData.riskLimits.maxDrawdown * 100}
                  onChange={val => handleFieldChange('maxDrawdown', (val ?? 15) / 100)}
                  formatter={value => `${value}%`}
                  parser={(value) => value?.replace('%', '') as unknown as number}
                  style={{ width: '100%' }}
                />
              </Col>
            </Row>
          </Form.Item>
        </Card>

        <Row gutter={24}>
          {/* Stop Loss */}
          <Col span={12}>
            <Card size="small" style={{ marginBottom: 16 }}>
              <Form.Item
                label="Stop Loss"
                required
                validateStatus={localErrors.stopLoss ? 'error' : ''}
                help={localErrors.stopLoss || 'Exit position if price drops by this percentage'}
              >
                <Row gutter={12}>
                  <Col span={16}>
                    <Slider
                      min={1}
                      max={20}
                      value={formData.riskLimits.stopLoss * 100}
                      onChange={val => handleFieldChange('stopLoss', val / 100)}
                    />
                  </Col>
                  <Col span={8}>
                    <InputNumber
                      min={1}
                      max={20}
                      value={formData.riskLimits.stopLoss * 100}
                      onChange={val => handleFieldChange('stopLoss', (val ?? 5) / 100)}
                      formatter={value => `${value}%`}
                      parser={(value) => value?.replace('%', '') as unknown as number}
                      style={{ width: '100%' }}
                    />
                  </Col>
                </Row>
              </Form.Item>
            </Card>
          </Col>

          {/* Take Profit */}
          <Col span={12}>
            <Card size="small" style={{ marginBottom: 16 }}>
              <Form.Item
                label="Take Profit"
                required
                validateStatus={localErrors.takeProfit ? 'error' : ''}
                help={localErrors.takeProfit || 'Exit position if price rises by this percentage'}
              >
                <Row gutter={12}>
                  <Col span={16}>
                    <Slider
                      min={1}
                      max={50}
                      value={formData.riskLimits.takeProfit * 100}
                      onChange={val => handleFieldChange('takeProfit', val / 100)}
                    />
                  </Col>
                  <Col span={8}>
                    <InputNumber
                      min={1}
                      max={50}
                      value={formData.riskLimits.takeProfit * 100}
                      onChange={val => handleFieldChange('takeProfit', (val ?? 10) / 100)}
                      formatter={value => `${value}%`}
                      parser={(value) => value?.replace('%', '') as unknown as number}
                      style={{ width: '100%' }}
                    />
                  </Col>
                </Row>
              </Form.Item>
            </Card>
          </Col>
        </Row>

        {/* Summary Card */}
        <Card 
          size="small" 
          style={{ 
            backgroundColor: '#e6f4ff', 
            marginTop: 16,
            border: '2px solid #1890ff'
          }}
        >
          <Title level={5} style={{ marginTop: 0, marginBottom: 16, color: '#000' }}>
            Risk Summary
          </Title>
          <Row gutter={16}>
            <Col span={12}>
              <Text style={{ color: '#000', fontSize: '14px' }}>Max Position Size:</Text>
              <br />
              <Text strong style={{ fontSize: '18px', color: '#000' }}>
                ${formData.riskLimits.maxPositionSize.toLocaleString()}
              </Text>
            </Col>
            <Col span={12}>
              <Text style={{ color: '#000', fontSize: '14px' }}>Daily Loss Limit:</Text>
              <br />
              <Text strong style={{ fontSize: '18px', color: '#000' }}>
                ${formData.riskLimits.dailyLossLimit.toLocaleString()}
              </Text>
            </Col>
          </Row>
          <Row gutter={16} style={{ marginTop: 16 }}>
            <Col span={8}>
              <Text style={{ color: '#000', fontSize: '14px' }}>Max Drawdown:</Text>
              <br />
              <Text strong style={{ fontSize: '18px', color: '#d32029' }}>
                {(formData.riskLimits.maxDrawdown * 100).toFixed(1)}%
              </Text>
            </Col>
            <Col span={8}>
              <Text style={{ color: '#000', fontSize: '14px' }}>Stop Loss:</Text>
              <br />
              <Text strong style={{ fontSize: '18px', color: '#d32029' }}>
                {(formData.riskLimits.stopLoss * 100).toFixed(1)}%
              </Text>
            </Col>
            <Col span={8}>
              <Text style={{ color: '#000', fontSize: '14px' }}>Take Profit:</Text>
              <br />
              <Text strong style={{ fontSize: '18px', color: '#52c41a' }}>
                {(formData.riskLimits.takeProfit * 100).toFixed(1)}%
              </Text>
            </Col>
          </Row>
        </Card>
      </Form>
    </div>
  );
};

/**
 * Trade History & Analytics Page
 * Main container for trade history with filters, table, and analytics
 */

import React, { useState } from 'react';
import { Card, Tabs, Space, DatePicker, Input, Radio, Button, Table, Statistic, Row, Col, App, Tag } from 'antd';
import { DownloadOutlined, ReloadOutlined, FilterOutlined } from '@ant-design/icons';
import type { ColumnsType } from 'antd/es/table';
import { useTradeHistory, useTradeAnalytics } from './hooks/useTradeHistory';
import { tradesService } from '@/services/tradesService';
import { TradeDetailModal } from './components/TradeDetailModal';
import { InstitutionalMetricsDisplay } from './components/InstitutionalMetricsDisplay';
import { useAuthStore } from '@/store/authStore';
import type { Trade, TradeFilters } from '@/types/trades';
import dayjs from 'dayjs';

const { RangePicker } = DatePicker;

export const TradesPage: React.FC = () => {
  const { message } = App.useApp();
  const [filters, setFilters] = useState<TradeFilters>({
    limit: 100,
    offset: 0,
  });
  
  const [tempFilters, setTempFilters] = useState({
    dateRange: null as [dayjs.Dayjs, dayjs.Dayjs] | null,
    symbol: '',
    side: 'all' as 'all' | 'buy' | 'sell',
  });

  // Modal state
  const [selectedTrade, setSelectedTrade] = useState<Trade | null>(null);
  const [detailModalVisible, setDetailModalVisible] = useState(false);
  const [closingOrderId, setClosingOrderId] = useState<string | null>(null);

  // Fetch data
  const { data: historyData, isLoading, refetch } = useTradeHistory(filters);
  const { data: analyticsData } = useTradeAnalytics(filters);

  // Handle filter changes
  const handleApplyFilters = () => {
    const newFilters: TradeFilters = {
      limit: 100,
      offset: 0,
    };

    if (tempFilters.dateRange) {
      newFilters.startDate = tempFilters.dateRange[0].format('YYYY-MM-DD');
      newFilters.endDate = tempFilters.dateRange[1].format('YYYY-MM-DD');
    }

    if (tempFilters.symbol) {
      newFilters.symbol = tempFilters.symbol.toUpperCase();
    }

    if (tempFilters.side !== 'all') {
      newFilters.side = tempFilters.side;
    }

    setFilters(newFilters);
  };

  const handleResetFilters = () => {
    setTempFilters({
      dateRange: null,
      symbol: '',
      side: 'all',
    });
    setFilters({ limit: 100, offset: 0 });
  };

  // Handle CSV export
  const handleExport = async () => {
    try {
      message.loading({ content: 'Generating CSV...', key: 'export' });
      await tradesService.downloadCSV(filters);
      message.success({ content: 'CSV downloaded successfully!', key: 'export', duration: 2 });
    } catch (_error) {
      message.error({ content: 'Failed to export CSV', key: 'export', duration: 2 });
    }
  };

  // Handle row click to open detail modal
  const handleRowClick = (record: Trade) => {
    setSelectedTrade(record);
    setDetailModalVisible(true);
  };

  // Handle close position from modal
  const handleClosePosition = async (symbol: string, quantity: number, orderId: string) => {
    setClosingOrderId(orderId);
    try {
      message.loading({ content: `Submitting sell order for ${quantity} ${symbol}...`, key: 'close' });
      
      // Get token from Zustand store (same way as api.ts does it)
      const token = useAuthStore.getState().accessToken;
      
      if (!token) {
        throw new Error('Not authenticated. Please login again.');
      }
      
      const response = await fetch(`http://localhost:8000/api/v1/orders/${orderId}/close-position`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        }
      });
      
      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.detail || 'Failed to close position');
      }
      
      const data = await response.json();
      
      if (data.success) {
        message.success({ 
          content: `Position closed! Sold ${quantity} shares of ${symbol}`, 
          key: 'close',
          duration: 3
        });
        
        // Close modal first
        setDetailModalVisible(false);
        setSelectedTrade(null);
        
        // Then refresh data
        refetch();
      }
    } catch (error: any) {
      const errorMsg = error.message || 'Failed to close position';
      message.error({ content: errorMsg, key: 'close', duration: 4 });
    } finally {
      setClosingOrderId(null);
    }
  };

  // Table columns
  const columns: ColumnsType<Trade> = [
    {
      title: 'Date',
      dataIndex: 'submittedAt',
      key: 'date',
      width: 110,
      render: (date: string) => dayjs(date).format('MM/DD/YY'),
      sorter: (a, b) => dayjs(a.submittedAt).unix() - dayjs(b.submittedAt).unix(),
    },
    {
      title: 'Time',
      dataIndex: 'submittedAt',
      key: 'time',
      width: 90,
      render: (date: string) => dayjs(date).format('HH:mm:ss'),
    },
    {
      title: 'Symbol',
      dataIndex: 'symbol',
      key: 'symbol',
      width: 100,
    },
    {
      title: 'Side',
      dataIndex: 'side',
      key: 'side',
      width: 80,
      render: (side: string) => (
        <Tag color={side === 'buy' ? 'green' : 'red'}>
          {side.toUpperCase()}
        </Tag>
      ),
    },
    {
      title: 'Source',
      key: 'source',
      width: 100,
      render: (_, record) => {
        const isImported = record.attributes?.imported === true;
        return (
          <Tag color={isImported ? 'blue' : 'green'} icon={isImported ? '≡ƒôÑ' : '≡ƒö╕'}>
            {isImported ? 'Imported' : 'Local'}
          </Tag>
        );
      },
    },
    {
      title: 'Position',
      key: 'positionStatus',
      width: 120,
      render: (_, record) => {
        const status = record.positionStatus;
        const note = record.positionNote;
        
        // Only show position status for filled buy orders
        if (record.side !== 'buy' || record.status !== 'filled') {
          return <span style={{ color: '#999' }}>N/A</span>;
        }
        
        let color = 'default';
        let icon = '';
        let text = 'Unknown';
        
        switch (status) {
          case 'open':
            color = 'success';
            icon = 'Γ£à';
            text = 'Open';
            break;
          case 'partially_closed':
            color = 'warning';
            icon = 'ΓÜá∩╕Å';
            text = 'Partial';
            break;
          case 'closed':
            color = 'warning';
            icon = 'ΓÜá∩╕Å';
            text = 'Closed';
            break;
          case 'closed_by_sell':
            color = 'default';
            icon = 'Γ£ô';
            text = 'Sold';
            break;
          default:
            color = 'default';
            icon = 'Γ¥ô';
            text = 'Unknown';
        }
        
        return (
          <Tag color={color} title={note}>
            <span style={{ marginRight: '4px' }}>{icon}</span>
            {text}
          </Tag>
        );
      },
    },
    {
      title: 'Quantity',
      dataIndex: 'filledQty',
      key: 'quantity',
      width: 100,
      align: 'right',
      render: (qty: number) => (qty !== null && qty !== undefined) ? qty.toFixed(2) : '0.00',
    },
    {
      title: 'Price',
      dataIndex: 'avgFillPrice',
      key: 'price',
      width: 100,
      align: 'right',
      render: (price: number | null) => price ? `$${price.toFixed(2)}` : 'N/A',
    },
    {
      title: 'Total Value',
      key: 'value',
      width: 120,
      align: 'right',
      render: (_, record) => {
        const qty = record.filledQty || 0;
        const price = record.avgFillPrice || 0;
        const value = qty * price;
        return value > 0 ? `$${value.toFixed(2)}` : 'N/A';
      },
    },
    {
      title: 'Status',
      dataIndex: 'status',
      key: 'status',
      width: 100,
      render: (status: string) => {
        const statusColors: Record<string, string> = {
          filled: 'success',
          partially_filled: 'processing',
          cancelled: 'default',
          rejected: 'error',
          failed: 'error',
          expired: 'warning',
        };
        return (
          <Tag color={statusColors[status] || 'default'}>
            {status.replace('_', ' ').toUpperCase()}
          </Tag>
        );
      },
    },
  ];

  return (
    <div style={{ padding: '24px' }}>
      <Space direction="vertical" size="large" style={{ width: '100%' }}>
        {/* Header */}
        <div>
          <h1 style={{ margin: 0 }}>Trade History & Analytics</h1>
          <p style={{ color: '#666', marginTop: '8px' }}>
            View your trading history, analyze performance, and export data
          </p>
        </div>

        {/* Filters */}
        <Card>
          <Space direction="vertical" size="middle" style={{ width: '100%' }}>
            <Space wrap>
              <RangePicker
                value={tempFilters.dateRange}
                onChange={(dates) => setTempFilters({ ...tempFilters, dateRange: dates as [dayjs.Dayjs, dayjs.Dayjs] | null })}
                format="YYYY-MM-DD"
                placeholder={['Start Date', 'End Date']}
              />
              <Input
                placeholder="Symbol (e.g., AAPL)"
                value={tempFilters.symbol}
                onChange={(e) => setTempFilters({ ...tempFilters, symbol: e.target.value })}
                style={{ width: 200 }}
              />
              <Radio.Group
                value={tempFilters.side}
                onChange={(e) => setTempFilters({ ...tempFilters, side: e.target.value })}
              >
                <Radio.Button value="all">All</Radio.Button>
                <Radio.Button value="buy">Buy</Radio.Button>
                <Radio.Button value="sell">Sell</Radio.Button>
              </Radio.Group>
              <Button type="primary" icon={<FilterOutlined />} onClick={handleApplyFilters}>
                Apply Filters
              </Button>
              <Button onClick={handleResetFilters}>Reset</Button>
              <Button icon={<ReloadOutlined />} onClick={() => refetch()}>
                Refresh
              </Button>
              <Button icon={<DownloadOutlined />} onClick={handleExport}>
                Export CSV
              </Button>
            </Space>
          </Space>
        </Card>

        {/* Tabs with new items API */}
        <Tabs
          defaultActiveKey="history"
          items={[
            {
              key: 'history',
              label: 'Trade History',
              children: (
                <Card>
                  <Table
                    columns={columns}
                    dataSource={historyData?.trades || []}
                    loading={isLoading}
                    rowKey="orderId"
                    onRow={(record) => ({
                      onClick: () => handleRowClick(record),
                      style: { cursor: 'pointer' }
                    })}
                    pagination={{
                      total: historyData?.total || 0,
                      current: (filters.offset || 0) / (filters.limit || 100) + 1,
                      pageSize: filters.limit || 100,
                      showSizeChanger: true,
                      showTotal: (total) => `Total ${total} trades`,
                      onChange: (page, pageSize) => {
                        setFilters({
                          ...filters,
                          offset: (page - 1) * pageSize,
                          limit: pageSize,
                        });
                      },
                    }}
                  />
                </Card>
              ),
            },
            {
              key: 'analytics',
              label: 'Analytics',
              children: (
                <Space direction="vertical" size="large" style={{ width: '100%' }}>
                  {/* Statistics Cards */}
                  <Row gutter={16}>
                    <Col xs={24} sm={12} lg={6}>
                      <Card>
                        <Statistic
                          title="Total Trades"
                          value={analyticsData?.totalTrades || 0}
                        />
                      </Card>
                    </Col>
                    <Col xs={24} sm={12} lg={6}>
                      <Card>
                        <Statistic
                          title="Win Rate"
                          value={analyticsData?.winRate || 0}
                          precision={1}
                          suffix="%"
                          valueStyle={{ color: (analyticsData?.winRate || 0) >= 50 ? '#3f8600' : '#cf1322' }}
                        />
                      </Card>
                    </Col>
                    <Col xs={24} sm={12} lg={6}>
                      <Card>
                        <Statistic
                          title="Total P&L"
                          value={analyticsData?.totalRealizedPnL || 0}
                          precision={2}
                          prefix="$"
                          valueStyle={{ color: (analyticsData?.totalRealizedPnL || 0) >= 0 ? '#3f8600' : '#cf1322' }}
                        />
                      </Card>
                    </Col>
                    <Col xs={24} sm={12} lg={6}>
                      <Card>
                        <Statistic
                          title="Total Volume"
                          value={analyticsData?.totalVolume || 0}
                          precision={2}
                          prefix="$"
                        />
                      </Card>
                    </Col>
                  </Row>

                  {/* Additional Stats */}
                  <Row gutter={16}>
                    <Col xs={24} sm={12}>
                      <Card title="Best Trade" variant="outlined">
                        {analyticsData?.bestTrade ? (
                          <>
                            <p><strong>Symbol:</strong> {analyticsData.bestTrade.symbol}</p>
                            <p><strong>P&L:</strong> <span style={{ color: '#3f8600', fontSize: '18px', fontWeight: 'bold' }}>${analyticsData.bestTrade.pnl.toFixed(2)}</span></p>
                            <p><strong>Date:</strong> {dayjs(analyticsData.bestTrade.date).format('MMM DD, YYYY')}</p>
                          </>
                        ) : (
                          <p>No data available</p>
                        )}
                      </Card>
                    </Col>
                    <Col xs={24} sm={12}>
                      <Card title="Worst Trade" variant="outlined">
                        {analyticsData?.worstTrade ? (
                          <>
                            <p><strong>Symbol:</strong> {analyticsData.worstTrade.symbol}</p>
                            <p><strong>P&L:</strong> <span style={{ color: '#cf1322', fontSize: '18px', fontWeight: 'bold' }}>${analyticsData.worstTrade.pnl.toFixed(2)}</span></p>
                            <p><strong>Date:</strong> {dayjs(analyticsData.worstTrade.date).format('MMM DD, YYYY')}</p>
                          </>
                        ) : (
                          <p>No data available</p>
                        )}
                      </Card>
                    </Col>
                  </Row>

                  {/* Institutional Metrics */}
                  {analyticsData?.institutionalMetrics && (
                    <InstitutionalMetricsDisplay metrics={analyticsData.institutionalMetrics} />
                  )}
                </Space>
              ),
            },
          ]}
        />

        {/* Trade Detail Modal */}
        <TradeDetailModal
          trade={selectedTrade}
          visible={detailModalVisible}
          onClose={() => {
            setDetailModalVisible(false);
            setSelectedTrade(null);
          }}
          onClosePosition={handleClosePosition}
          isClosing={closingOrderId === selectedTrade?.orderId}
        />
      </Space>
    </div>
  );
};

export default TradesPage;

/**
 * Trade Detail Modal
 * Comprehensive view of individual trade/order with execution details and actions
 */

import React, { useState } from 'react';
import {
  Modal,
  Descriptions,
  Table,
  Tag,
  Button,
  Space,
  Statistic,
  Row,
  Col,
  Card,
  Alert,
  App,
  Divider
} from 'antd';
import {
  DollarOutlined,
  CloseCircleOutlined,
  CheckCircleOutlined,
  ClockCircleOutlined,
  ExportOutlined,
  LinkOutlined,
  TrophyOutlined
} from '@ant-design/icons';
import type { Trade } from '@/types/trades';
import { useCancelOrder } from '@/hooks/useData';
import { useTradeAnalytics } from '../hooks/useTradeHistory';
import { InstitutionalMetricsDisplay } from './InstitutionalMetricsDisplay';
import dayjs from 'dayjs';

interface TradeDetailModalProps {
  trade: Trade | null;
  visible: boolean;
  onClose: () => void;
  onClosePosition?: (symbol: string, quantity: number, orderId: string) => void;
  isClosing?: boolean;
}

export const TradeDetailModal: React.FC<TradeDetailModalProps> = ({
  trade,
  visible,
  onClose,
  onClosePosition,
  isClosing: isClosingProp = false
}) => {
  const { modal, message } = App.useApp();
  const { mutate: cancelOrder, isPending: isCancelling } = useCancelOrder();
  const [isClosing, setIsClosing] = useState(false);

  // Fetch analytics for institutional metrics (optional, shows if available)
  const { data: analyticsData } = useTradeAnalytics({
    symbol: trade?.symbol
  }, !!trade && visible);

  if (!trade) return null;

  const handleClosePosition = async () => {
    if (!trade.currentQty || !onClosePosition) return;

    modal.confirm({
      title: 'Close Position?',
      content: (
        <>
          <p>This will submit a market order to sell <strong>{trade.currentQty}</strong> shares of <strong>{trade.symbol}</strong>.</p>
          <p>Current market price: <strong>${trade.currentPrice?.toFixed(2) || 'N/A'}</strong></p>
          <p>Estimated value: <strong>${((trade.currentQty || 0) * (trade.currentPrice || 0)).toFixed(2)}</strong></p>
        </>
      ),
      okText: 'Close Position',
      okButtonProps: { danger: true, loading: isClosing || isClosingProp },
      onOk: async () => {
        setIsClosing(true);
        try {
          await onClosePosition(trade.symbol, trade.currentQty!, trade.orderId);
          // Don't close modal or reset state here - parent will handle refresh
        } catch (_error) {
          message.error('Failed to close position');
          setIsClosing(false);
        }
      }
    });
  };

  const handleCancelOrder = () => {
    modal.confirm({
      title: 'Cancel Order?',
      content: `Are you sure you want to cancel this ${trade.side} order for ${trade.qty} shares of ${trade.symbol}?`,
      okText: 'Cancel Order',
      okButtonProps: { danger: true },
      onOk: () => {
        cancelOrder(trade.orderId);
        onClose();
      }
    });
  };

  const handleExportDetails = () => {
    const detailsJSON = JSON.stringify(trade, null, 2);
    const blob = new Blob([detailsJSON], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `trade-${trade.orderId}.json`;
    a.click();
    URL.revokeObjectURL(url);
    message.success('Trade details exported');
  };

  // Calculate metrics
  const totalValue = (trade.filledQty || 0) * (trade.avgFillPrice || 0);
  const isImported = trade.attributes?.imported === true;
  const isPendingOrder = ['new', 'pending_new', 'accepted'].includes(trade.status);
  const isOpenPosition = trade.positionStatus === 'open' && trade.side === 'buy' && trade.status === 'filled';
  const canClosePosition = isOpenPosition && trade.currentQty && trade.currentQty > 0 && onClosePosition;

  // Status color mapping
  const getStatusColor = (status: string) => {
    const colors: Record<string, string> = {
      filled: 'success',
      partial: 'warning',
      cancelled: 'default',
      rejected: 'error',
      new: 'processing',
      accepted: 'processing'
    };
    return colors[status] || 'default';
  };

  // Execution table columns
  const executionColumns = [
    {
      title: 'Time',
      dataIndex: 'timestamp',
      key: 'timestamp',
      render: (ts: string) => dayjs(ts).format('MM/DD/YY HH:mm:ss')
    },
    {
      title: 'Quantity',
      dataIndex: 'fillQty',
      key: 'quantity',
      align: 'right' as const,
      render: (qty: number) => qty.toFixed(4)
    },
    {
      title: 'Price',
      dataIndex: 'fillPrice',
      key: 'price',
      align: 'right' as const,
      render: (price: number) => `$${price.toFixed(2)}`
    },
    {
      title: 'Value',
      key: 'value',
      align: 'right' as const,
      render: (_: any, record: any) => `$${(record.fillQty * record.fillPrice).toFixed(2)}`
    },
    {
      title: 'Venue',
      dataIndex: 'venue',
      key: 'venue'
    }
  ];

  return (
    <Modal
      open={visible}
      onCancel={onClose}
      width={900}
      title={
        <Space>
          <span>Order Details</span>
          <Tag color={trade.side === 'buy' ? 'green' : 'red'}>
            {trade.side.toUpperCase()}
          </Tag>
          <Tag>{trade.symbol}</Tag>
          <Tag color={getStatusColor(trade.status)}>{trade.status.toUpperCase()}</Tag>
        </Space>
      }
      footer={[
        <Button key="export" icon={<ExportOutlined />} onClick={handleExportDetails}>
          Export
        </Button>,
        <Button
          key="alpaca"
          icon={<LinkOutlined />}
          onClick={() => window.open(`https://app.alpaca.markets/paper/dashboard/overview`, '_blank')}
        >
          View in Alpaca
        </Button>,
        isPendingOrder && (
          <Button
            key="cancel"
            danger
            icon={<CloseCircleOutlined />}
            onClick={handleCancelOrder}
            loading={isCancelling}
          >
            Cancel Order
          </Button>
        ),
        canClosePosition && (
          <Button
            key="closePosition"
            type="primary"
            danger
            icon={<DollarOutlined />}
            onClick={handleClosePosition}
            loading={isClosing || isClosingProp}
            disabled={isClosing || isClosingProp}
          >
            Close Position
          </Button>
        ),
        <Button key="close" type="primary" onClick={onClose}>
          Close
        </Button>
      ].filter(Boolean)}
    >
      <Space direction="vertical" style={{ width: '100%' }} size="large">
        
        {/* Source Alert */}
        {isImported && (
          <Alert
            message="Imported Order"
            description="This order was imported from Alpaca and may not have complete execution details."
            type="info"
            showIcon
            icon={<LinkOutlined />}
          />
        )}

        {/* Key Metrics */}
        <Row gutter={16}>
          <Col span={6}>
            <Card size="small">
              <Statistic
                title="Quantity"
                value={trade.qty}
                precision={2}
                suffix="shares"
              />
            </Card>
          </Col>
          <Col span={6}>
            <Card size="small">
              <Statistic
                title="Filled"
                value={trade.filledQty || 0}
                precision={2}
                valueStyle={{ color: trade.filledQty === trade.qty ? '#3f8600' : '#cf1322' }}
              />
            </Card>
          </Col>
          <Col span={6}>
            <Card size="small">
              <Statistic
                title="Avg Price"
                value={trade.avgFillPrice || 0}
                precision={2}
                prefix="$"
              />
            </Card>
          </Col>
          <Col span={6}>
            <Card size="small">
              <Statistic
                title="Total Value"
                value={totalValue}
                precision={2}
                prefix="$"
              />
            </Card>
          </Col>
        </Row>

        {/* Position Status (for buy orders) */}
        {trade.side === 'buy' && trade.status === 'filled' && (
          <Card title="Position Status" size="small">
            <Row gutter={16}>
              <Col span={8}>
                <Statistic
                  title="Status"
                  value={trade.positionStatus || 'unknown'}
                  valueStyle={{
                    color: trade.positionStatus === 'open' ? '#3f8600' : '#999'
                  }}
                />
              </Col>
              {trade.currentQty !== null && (
                <Col span={8}>
                  <Statistic
                    title="Current Quantity"
                    value={trade.currentQty}
                    precision={2}
                  />
                </Col>
              )}
              {trade.unrealizedPnL !== null && (
                <Col span={8}>
                  <Statistic
                    title="Unrealized P&L"
                    value={trade.unrealizedPnL}
                    precision={2}
                    prefix="$"
                    valueStyle={{
                      color: (trade.unrealizedPnL || 0) >= 0 ? '#3f8600' : '#cf1322'
                    }}
                  />
                </Col>
              )}
            </Row>
            {trade.positionNote && (
              <Alert
                message={trade.positionNote}
                type="info"
                showIcon
                style={{ marginTop: 12 }}
              />
            )}
          </Card>
        )}

        {/* Order Information */}
        <Descriptions title="Order Information" bordered size="small" column={2}>
          <Descriptions.Item label="Order ID">{trade.orderId}</Descriptions.Item>
          <Descriptions.Item label="Symbol">{trade.symbol}</Descriptions.Item>
          <Descriptions.Item label="Side">
            <Tag color={trade.side === 'buy' ? 'green' : 'red'}>
              {trade.side.toUpperCase()}
            </Tag>
          </Descriptions.Item>
          <Descriptions.Item label="Type">{trade.orderType.toUpperCase()}</Descriptions.Item>
          <Descriptions.Item label="Status">
            <Tag color={getStatusColor(trade.status)} icon={
              trade.status === 'filled' ? <CheckCircleOutlined /> :
              isPendingOrder ? <ClockCircleOutlined /> :
              <CloseCircleOutlined />
            }>
              {trade.status.toUpperCase()}
            </Tag>
          </Descriptions.Item>
          <Descriptions.Item label="Source">
            <Tag color={isImported ? 'blue' : 'green'}>
              {isImported ? 'Imported' : 'Local'}
            </Tag>
          </Descriptions.Item>
          <Descriptions.Item label="Submitted">
            {dayjs(trade.submittedAt).format('MM/DD/YY HH:mm:ss')}
          </Descriptions.Item>
          <Descriptions.Item label="Updated">
            {dayjs(trade.updatedAt).format('MM/DD/YY HH:mm:ss')}
          </Descriptions.Item>
          {trade.strategyId && (
            <Descriptions.Item label="Strategy" span={2}>
              {trade.strategyId}
            </Descriptions.Item>
          )}
        </Descriptions>

        {/* Execution Details */}
        {trade.executions && trade.executions.length > 0 && (
          <>
            <Divider orientation="left">Execution Details</Divider>
            <Table
              dataSource={trade.executions}
              columns={executionColumns}
              size="small"
              pagination={false}
              rowKey="executionId"
              summary={() => (
                <Table.Summary>
                  <Table.Summary.Row>
                    <Table.Summary.Cell index={0}><strong>Total</strong></Table.Summary.Cell>
                    <Table.Summary.Cell index={1} align="right">
                      <strong>{trade.filledQty?.toFixed(4)}</strong>
                    </Table.Summary.Cell>
                    <Table.Summary.Cell index={2} align="right">
                      <strong>${trade.avgFillPrice?.toFixed(2)}</strong>
                    </Table.Summary.Cell>
                    <Table.Summary.Cell index={3} align="right">
                      <strong>${totalValue.toFixed(2)}</strong>
                    </Table.Summary.Cell>
                    <Table.Summary.Cell index={4} />
                  </Table.Summary.Row>
                </Table.Summary>
              )}
            />
          </>
        )}

        {/* Institutional Metrics (if available for this symbol) */}
        {analyticsData?.institutionalMetrics && (
          <>
            <Divider orientation="left">
              <TrophyOutlined style={{ marginRight: 8 }} />
              Performance Metrics for {trade.symbol}
            </Divider>
            <InstitutionalMetricsDisplay metrics={analyticsData.institutionalMetrics} />
          </>
        )}

      </Space>
    </Modal>
  );
};

/**
 * Active Orders Table
 * Displays open/pending orders with real-time updates
 */

import React, { useMemo } from 'react';
import { Table, Tag, Button, Space, Popconfirm, message, Typography, Tooltip } from 'antd';
import type { ColumnsType } from 'antd/es/table';
import {
  CloseOutlined,
  CheckCircleOutlined,
  ClockCircleOutlined,
  SyncOutlined,
} from '@ant-design/icons';
import { useOrdersStore } from '@/store/ordersStore';
import type { Order, OrderStatus, OrderSide } from '@/store/ordersStore';
import { formatCurrency, formatNumber } from '@/utils/formatters';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { ordersService } from '@/services/ordersService';

const { Text } = Typography;

const getStatusColor = (status: OrderStatus): string => {
  const colors: Record<OrderStatus, string> = {
    pending: 'blue',
    submitted: 'cyan',
    accepted: 'cyan',
    partially_filled: 'orange',
    filled: 'green',
    cancelled: 'default',
    rejected: 'red',
  };
  return colors[status] || 'default';
};

const getStatusIcon = (status: OrderStatus): React.ReactNode => {
  const icons: Record<OrderStatus, React.ReactNode> = {
    pending: <ClockCircleOutlined />,
    submitted: <ClockCircleOutlined />,
    accepted: <CheckCircleOutlined />,
    partially_filled: <SyncOutlined spin />,
    filled: <CheckCircleOutlined />,
    cancelled: <CloseOutlined />,
    rejected: <CloseOutlined />,
  };
  return icons[status] || null;
};

const getSideColor = (side: OrderSide): string => {
  return side === 'buy' ? '#52c41a' : '#ff4d4f';
};

export const ActiveOrdersTable: React.FC = () => {
  const orders = useOrdersStore((state) => state.orders);
  const updateOrder = useOrdersStore((state) => state.updateOrder);
  const _removeOrder = useOrdersStore((state) => state.removeOrder);
  const queryClient = useQueryClient();

  // Only show active orders (pending, submitted, partially_filled)
  const activeOrders = useMemo(() => {
    return orders.filter((order) =>
      ['pending', 'submitted', 'partially_filled'].includes(order.status)
    );
  }, [orders]);

  const { mutate: cancelOrder, isPending: isCancelling } = useMutation({
    mutationFn: (orderId: string) => ordersService.cancelOrder(orderId),
    onSuccess: (cancelledOrder) => {
      message.success(`Order ${cancelledOrder.orderId} cancelled successfully`);
      updateOrder(cancelledOrder.orderId, cancelledOrder);
      queryClient.invalidateQueries({ queryKey: ['orders'] });
    },
    onError: (error: any) => {
      message.error(error?.response?.data?.detail || 'Failed to cancel order');
    },
  });

  const handleCancel = (orderId: string) => {
    cancelOrder(orderId);
  };

  const columns: ColumnsType<Order> = [
    {
      title: 'Time',
      dataIndex: 'createdAt',
      key: 'createdAt',
      width: 100,
      render: (date: string) => {
        const d = new Date(date);
        return (
          <Tooltip title={d.toLocaleString()}>
            <Text>{d.toLocaleTimeString()}</Text>
          </Tooltip>
        );
      },
    },
    {
      title: 'Symbol',
      dataIndex: 'symbol',
      key: 'symbol',
      width: 100,
      render: (symbol: string) => (
        <Text strong style={{ fontSize: 14 }}>
          {symbol}
        </Text>
      ),
    },
    {
      title: 'Side',
      dataIndex: 'side',
      key: 'side',
      width: 80,
      render: (side: OrderSide) => (
        <Tag color={getSideColor(side)} style={{ fontWeight: 'bold' }}>
          {side.toUpperCase()}
        </Tag>
      ),
    },
    {
      title: 'Type',
      dataIndex: 'orderType',
      key: 'orderType',
      width: 100,
      render: (type: string) => <Text>{type.toUpperCase()}</Text>,
    },
    {
      title: 'Quantity',
      dataIndex: 'quantity',
      key: 'quantity',
      width: 100,
      align: 'right',
      render: (qty: number, record: Order) => (
        <Space direction="vertical" size={0}>
          <Text>{formatNumber(qty)}</Text>
          {record.filledQuantity > 0 && (
            <Text type="secondary" style={{ fontSize: 12 }}>
              Filled: {formatNumber(record.filledQuantity)}
            </Text>
          )}
        </Space>
      ),
    },
    {
      title: 'Limit Price',
      dataIndex: 'limitPrice',
      key: 'limitPrice',
      width: 120,
      align: 'right',
      render: (price?: number) =>
        price ? <Text>{formatCurrency(price)}</Text> : <Text type="secondary">ΓÇö</Text>,
    },
    {
      title: 'Stop Price',
      dataIndex: 'stopPrice',
      key: 'stopPrice',
      width: 120,
      align: 'right',
      render: (price?: number) =>
        price ? <Text>{formatCurrency(price)}</Text> : <Text type="secondary">ΓÇö</Text>,
    },
    {
      title: 'Status',
      dataIndex: 'status',
      key: 'status',
      width: 150,
      render: (status: OrderStatus) => (
        <Tag icon={getStatusIcon(status)} color={getStatusColor(status)}>
          {status.toUpperCase().replace('_', ' ')}
        </Tag>
      ),
    },
    {
      title: 'TIF',
      dataIndex: 'timeInForce',
      key: 'timeInForce',
      width: 80,
      render: (tif: string) => (
        <Tooltip title={tif === 'gtc' ? 'Good Til Cancelled' : tif.toUpperCase()}>
          <Text>{tif.toUpperCase()}</Text>
        </Tooltip>
      ),
    },
    {
      title: 'Actions',
      key: 'actions',
      width: 120,
      fixed: 'right',
      render: (_, record: Order) => {
        const canCancel = ['pending', 'submitted', 'partially_filled'].includes(
          record.status
        );

        return (
          <Space size="small">
            {canCancel && (
              <Popconfirm
                title="Cancel Order"
                description="Are you sure you want to cancel this order?"
                onConfirm={() => handleCancel(record.orderId)}
                okText="Yes"
                cancelText="No"
                okButtonProps={{ danger: true }}
              >
                <Button
                  size="small"
                  danger
                  icon={<CloseOutlined />}
                  loading={isCancelling}
                  disabled={isCancelling}
                >
                  Cancel
                </Button>
              </Popconfirm>
            )}
            {!canCancel && <Text type="secondary">ΓÇö</Text>}
          </Space>
        );
      },
    },
  ];

  return (
    <Table
      columns={columns}
      dataSource={activeOrders}
      rowKey="orderId"
      pagination={{
        pageSize: 10,
        showSizeChanger: true,
        showTotal: (total) => `Total ${total} active orders`,
      }}
      size="small"
      loading={false}
      locale={{
        emptyText: 'No active orders',
      }}
      scroll={{ x: 1200 }}
    />
  );
};

/**
 * Order Entry Panel
 * Professional trade ticket for submitting orders
 */

import React, { useState } from 'react';
import {
  Card,
  Form,
  Input,
  InputNumber,
  Button,
  Select,
  Space,
  Radio,
  Divider,
  App,
  Tooltip,
  Row,
  Col,
  Typography,
  Alert,
} from 'antd';
import {
  DollarOutlined,
  SwapOutlined,
  InfoCircleOutlined,
  ThunderboltOutlined,
} from '@ant-design/icons';
import { useSubmitOrder } from '@/hooks/useData';
import type { OrderSide, OrderType, TimeInForce } from '@/store/ordersStore';

const { Title } = Typography;
const { Option } = Select;

interface OrderFormValues {
  symbol: string;
  side: OrderSide;
  orderType: OrderType;
  quantity: number;
  limitPrice?: number;
  stopPrice?: number;
  timeInForce: TimeInForce;
}

export const OrderEntryPanel: React.FC = () => {
  const { message } = App.useApp();
  const [form] = Form.useForm<OrderFormValues>();
  const [side, setSide] = useState<OrderSide>('buy');
  const [orderType, setOrderType] = useState<OrderType>('market');
  const { mutate: submitOrder, isPending } = useSubmitOrder();
  
  // Watch form values to avoid calling form.getFieldValue during render
  const symbolValue = Form.useWatch('symbol', form);

  const handleSubmit = async (values: OrderFormValues) => {
    try {
      await submitOrder(
        {
          symbol: values.symbol.toUpperCase(),
          side: values.side,
          orderType: values.orderType,
          quantity: values.quantity,
          limitPrice: values.limitPrice,
          stopPrice: values.stopPrice,
          timeInForce: values.timeInForce,
        },
        {
          onSuccess: () => {
            message.success(
              `${values.side.toUpperCase()} order for ${values.quantity} ${values.symbol} submitted successfully`
            );
            form.resetFields(['symbol', 'quantity', 'limitPrice', 'stopPrice']);
          },
          onError: (error: any) => {
            message.error(
              error?.response?.data?.detail || 'Failed to submit order'
            );
          },
        }
      );
    } catch (error) {
      console.error('Order submission error:', error);
    }
  };

  const handleSideChange = (newSide: OrderSide) => {
    setSide(newSide);
    // Form automatically updates via name prop - no need for setFieldValue
  };

  const handleOrderTypeChange = (newType: OrderType) => {
    setOrderType(newType);
    // Form automatically updates via name prop - no need for setFieldValue
  };

  const requiresLimitPrice = orderType === 'limit' || orderType === 'stop_limit';
  const requiresStopPrice = orderType === 'stop' || orderType === 'stop_limit';

  return (
    <Card
      title={
        <Space>
          <ThunderboltOutlined />
          <Title level={5} style={{ margin: 0 }}>
            Quick Trade
          </Title>
        </Space>
      }
      style={{ height: '100%' }}
    >
      <Form
        form={form}
        layout="vertical"
        onFinish={handleSubmit}
        preserve={false}
        initialValues={{
          side: 'buy',
          orderType: 'market',
          timeInForce: 'gtc',
          quantity: 1,
        }}
      >
        {/* Buy/Sell Toggle */}
        <Form.Item label="Side" name="side" required>
          <Radio.Group
            onChange={(e) => handleSideChange(e.target.value)}
            buttonStyle="solid"
            size="large"
            style={{ width: '100%' }}
          >
            <Radio.Button
              value="buy"
              style={{
                width: '50%',
                textAlign: 'center',
                backgroundColor: side === 'buy' ? '#52c41a' : undefined,
                borderColor: side === 'buy' ? '#52c41a' : undefined,
                color: side === 'buy' ? '#fff' : undefined,
              }}
            >
              <strong>BUY</strong>
            </Radio.Button>
            <Radio.Button
              value="sell"
              style={{
                width: '50%',
                textAlign: 'center',
                backgroundColor: side === 'sell' ? '#ff4d4f' : undefined,
                borderColor: side === 'sell' ? '#ff4d4f' : undefined,
                color: side === 'sell' ? '#fff' : undefined,
              }}
            >
              <strong>SELL</strong>
            </Radio.Button>
          </Radio.Group>
        </Form.Item>

        {/* Symbol Input */}
        <Form.Item
          label="Symbol"
          name="symbol"
          rules={[
            { required: true, message: 'Please enter a symbol' },
            {
              pattern: /^[A-Z]{1,5}$/i,
              message: 'Symbol must be 1-5 letters',
            },
          ]}
        >
          <Input
            placeholder="AAPL"
            size="large"
            style={{ textTransform: 'uppercase' }}
            prefix={<DollarOutlined />}
          />
        </Form.Item>

        {/* Order Type */}
        <Form.Item
          label={
            <Space>
              <span>Order Type</span>
              <Tooltip title="Market orders execute immediately at current price. Limit orders only execute at your specified price or better.">
                <InfoCircleOutlined style={{ color: '#8c8c8c' }} />
              </Tooltip>
            </Space>
          }
          name="orderType"
        >
          <Select
            size="large"
            onChange={handleOrderTypeChange}
          >
            <Option value="market">Market</Option>
            <Option value="limit">Limit</Option>
            <Option value="stop">Stop</Option>
            <Option value="stop_limit">Stop Limit</Option>
          </Select>
        </Form.Item>

        <Row gutter={16}>
          {/* Quantity */}
          <Col span={12}>
            <Form.Item
              label="Quantity"
              name="quantity"
              rules={[
                { required: true, message: 'Required' },
                { type: 'number', min: 1, message: 'Min 1' },
              ]}
            >
              <InputNumber
                min={1}
                precision={0}
                size="large"
                style={{ width: '100%' }}
                placeholder="1"
              />
            </Form.Item>
          </Col>

          {/* Limit Price (if needed) */}
          {requiresLimitPrice && (
            <Col span={12}>
              <Form.Item
                label="Limit Price"
                name="limitPrice"
                rules={[
                  {
                    required: true,
                    message: 'Required for limit orders',
                  },
                  { type: 'number', min: 0.01, message: 'Min $0.01' },
                ]}
              >
                <InputNumber
                  min={0.01}
                  precision={2}
                  size="large"
                  style={{ width: '100%' }}
                  placeholder="0.00"
                  prefix="$"
                />
              </Form.Item>
            </Col>
          )}
        </Row>

        {/* Stop Price (if needed) */}
        {requiresStopPrice && (
          <Form.Item
            label="Stop Price"
            name="stopPrice"
            rules={[
              { required: true, message: 'Required for stop orders' },
              { type: 'number', min: 0.01, message: 'Min $0.01' },
            ]}
          >
            <InputNumber
              min={0.01}
              precision={2}
              size="large"
              style={{ width: '100%' }}
              placeholder="0.00"
              prefix="$"
            />
          </Form.Item>
        )}

        {/* Time in Force */}
        <Form.Item
          label={
            <Space>
              <span>Time in Force</span>
              <Tooltip title="GTC = Good 'til Cancelled, DAY = Day order, IOC = Immediate or Cancel, FOK = Fill or Kill">
                <InfoCircleOutlined style={{ color: '#8c8c8c' }} />
              </Tooltip>
            </Space>
          }
          name="timeInForce"
        >
          <Select size="large">
            <Option value="gtc">GTC (Good 'Til Cancelled)</Option>
            <Option value="day">Day</Option>
            <Option value="ioc">IOC (Immediate or Cancel)</Option>
            <Option value="fok">FOK (Fill or Kill)</Option>
          </Select>
        </Form.Item>

        <Divider />

        {/* Market Warning for Market Orders */}
        {orderType === 'market' && (
          <Alert
            message="Market Order"
            description="This order will execute immediately at the current market price, which may differ from the displayed price."
            type="info"
            showIcon
            style={{ marginBottom: 16 }}
          />
        )}

        {/* Submit Button */}
        <Form.Item style={{ marginBottom: 0 }}>
          <Button
            type="primary"
            htmlType="submit"
            size="large"
            block
            loading={isPending}
            icon={<SwapOutlined />}
            style={{
              backgroundColor: side === 'buy' ? '#52c41a' : '#ff4d4f',
              borderColor: side === 'buy' ? '#52c41a' : '#ff4d4f',
              height: 50,
              fontSize: 16,
              fontWeight: 'bold',
            }}
          >
            {side === 'buy' ? 'BUY' : 'SELL'} {symbolValue || 'STOCK'}
          </Button>
        </Form.Item>
      </Form>
    </Card>
  );
};

/**
 * React Query hook for pre-trade order validation
 * 
 * Calls POST /api/v1/orders/validate to validate an order before submission
 * Provides loading, error, and success states for UI feedback
 * 
 * Usage:
 * ```tsx
 * const validation = usePreTradeValidation();
 * 
 * const handlePreview = () => {
 *   validation.mutate({
 *     symbol: 'AAPL',
 *     side: 'buy',
 *     quantity: 10,
 *     orderType: 'market'
 *   });
 * };
 * 
 * if (validation.isSuccess) {
 *   // Show validation results
 *   console.log(validation.data.valid);
 * }
 * ```
 */

import { useMutation } from '@tanstack/react-query';
import { apiClient } from '@/services/api';
import type { 
  OrderValidationRequest, 
  OrderValidationResponse 
} from '@/types/trading';

/**
 * Hook for pre-trade order validation
 * 
 * @returns React Query mutation object with validation state
 */
export const usePreTradeValidation = () => {
  return useMutation({
    mutationKey: ['validateOrder'],
    
    mutationFn: async (data: OrderValidationRequest): Promise<OrderValidationResponse> => {
      try {
        // POST to validation endpoint
        const response = await apiClient.post<OrderValidationResponse>(
          '/orders/validate',
          data
        );
        
        return response.data;
      } catch (error: any) {
        // Handle API errors gracefully
        console.error('Order validation failed:', error);
        
        // If we have a response with validation data, return it
        if (error.response?.data) {
          return error.response.data;
        }
        
        // Otherwise, create a system error response
        throw new Error(
          error.response?.data?.detail || 
          error.message || 
          'Failed to validate order. Please try again.'
        );
      }
    },
    
    // Don't retry validation requests (they're fast and deterministic)
    retry: false,
    
    // Cache validation results briefly (30 seconds)
    // This prevents redundant calls if user clicks preview multiple times quickly
    gcTime: 30000,
  });
};

/**
 * Hook for pre-trade validation with callbacks
 * Convenience wrapper that adds onSuccess and onError handlers
 * 
 * @param options - Success and error callbacks
 * @returns React Query mutation object
 */
export const usePreTradeValidationWithCallbacks = (options?: {
  onSuccess?: (data: OrderValidationResponse) => void;
  onError?: (error: Error) => void;
}) => {
  return useMutation({
    mutationKey: ['validateOrder'],
    
    mutationFn: async (data: OrderValidationRequest): Promise<OrderValidationResponse> => {
      const response = await apiClient.post<OrderValidationResponse>(
        '/orders/validate',
        data
      );
      return response.data;
    },
    
    retry: false,
    gcTime: 30000,
    
    onSuccess: options?.onSuccess,
    onError: options?.onError,
  });
};

/**
 * Chart Hook
 * React hook for managing Lightweight Charts instance
 */

import { useRef, useEffect, useState, useCallback } from 'react';
import { 
  createChart, 
  ColorType,
  CrosshairMode,
  LineStyle,
  CandlestickSeries,
  HistogramSeries,
  LineSeries,
  type Time,
  type IChartApi,
  type MouseEventParams
} from 'lightweight-charts';
import type { 
  ChartOptions, 
  ChartSeries, 
  CandlestickData, 
  VolumeData,
  Bar 
} from '../types/chart.types';

/**
 * Default chart theme (dark mode)
 */
const DEFAULT_THEME = {
  background: '#1a1a1a',
  textColor: '#d1d5db',
  gridColor: '#2d2d2d',
  upColor: '#22c55e',
  downColor: '#ef4444',
  borderUpColor: '#22c55e',
  borderDownColor: '#ef4444',
  wickUpColor: '#22c55e',
  wickDownColor: '#ef4444',
  volumeUpColor: 'rgba(34, 197, 94, 0.5)',
  volumeDownColor: 'rgba(239, 68, 68, 0.5)',
};

/**
 * Hook for managing chart instance
 */
export function useChart(containerRef: React.RefObject<HTMLDivElement | null>, options?: ChartOptions) {
  const chartRef = useRef<IChartApi | null>(null);
  const seriesRef = useRef<ChartSeries>({
    indicators: new Map(),
  });
  const [isReady, setIsReady] = useState(false);

  /**
   * Initialize chart
   */
  useEffect(() => {
    if (!containerRef.current) {
      // Container not ready yet - this is normal during initial render
      return;
    }

    // Check if container has dimensions
    const container = containerRef.current;
    if (container.clientWidth === 0 || container.clientHeight === 0) {
      // Container has no dimensions yet, waiting for layout
      return;
    }
    
    // Don't initialize if chart already exists and is valid
    if (chartRef.current) {
      console.log('Chart already initialized, skipping');
      return;
    }

    console.log('Initializing chart with container dimensions:', container.clientWidth, container.clientHeight);

    const theme = options?.theme || DEFAULT_THEME;

    try {
      // Create chart with autoSize (don't specify width/height when autoSize is true)
      const chart = createChart(container, {
        autoSize: true,  // Enable auto-resize - will use container dimensions
        layout: {
          background: { type: ColorType.Solid, color: theme.background },
          textColor: theme.textColor,
        },
      grid: {
        vertLines: { 
          color: theme.gridColor,
          visible: options?.showGrid !== false,
        },
        horzLines: { 
          color: theme.gridColor,
          visible: options?.showGrid !== false,
        },
      },
      crosshair: {
        mode: options?.showCrosshair !== false ? CrosshairMode.Normal : CrosshairMode.Hidden,
        vertLine: {
          width: 1,
          color: theme.gridColor,
          style: LineStyle.Dashed,
        },
        horzLine: {
          width: 1,
          color: theme.gridColor,
          style: LineStyle.Dashed,
        },
      },
      rightPriceScale: {
        visible: options?.showPriceScale !== false,
        borderColor: theme.gridColor,
      },
      timeScale: {
        visible: options?.showTimeScale !== false,
        borderColor: theme.gridColor,
        timeVisible: true,
        secondsVisible: false,
      },
      handleScroll: {
        mouseWheel: true,
        pressedMouseMove: true,
        horzTouchDrag: true,
        vertTouchDrag: true,
      },
      handleScale: {
        axisPressedMouseMove: true,
        mouseWheel: true,
        pinch: true,
      },
    });

    // Create candlestick series - v5 API uses SeriesDefinition constants
    const candlestickSeries = chart.addSeries(CandlestickSeries, {
      upColor: theme.upColor,
      downColor: theme.downColor,
      borderUpColor: theme.borderUpColor,
      borderDownColor: theme.borderDownColor,
      wickUpColor: theme.wickUpColor,
      wickDownColor: theme.wickDownColor,
    });

    // Create volume series - v5 API uses SeriesDefinition constants
    const volumeSeries = chart.addSeries(HistogramSeries, {
      color: theme.volumeUpColor,
      priceFormat: {
        type: 'volume',
      },
      priceScaleId: 'volume',
    });

    chart.priceScale('volume').applyOptions({
      scaleMargins: {
        top: 0.8,
        bottom: 0,
      },
    });

    chartRef.current = chart;
    seriesRef.current.candlestick = candlestickSeries;
    seriesRef.current.volume = volumeSeries;
    setIsReady(true);

    console.log('Chart initialized successfully');

    // Resize handled automatically by autoSize: true, no need for manual resize handler

    // Cleanup
    return () => {
      console.log('Cleaning up chart');
      
      // Clear series refs BEFORE removing chart
      seriesRef.current.candlestick = null;
      seriesRef.current.volume = null;
      
      if (chartRef.current) {
        try {
          chartRef.current.remove();
        } catch (err) {
          console.error('Error removing chart:', err);
        }
        chartRef.current = null;
      }
      setIsReady(false);
    };
    } catch (error) {
      console.error('Failed to initialize chart:', error);
      setIsReady(false);
      return;
    }
  }, [options]); // Only options, not containerRef (refs are stable)

  /**
  /**
   * Set candlestick data
   */
  const setCandlestickData = useCallback((data: CandlestickData[]) => {
    if (seriesRef.current.candlestick) {
      seriesRef.current.candlestick.setData(data);
    }
  }, []);

  /**
   * Update candlestick (add or update last bar)
   */
  const updateCandlestick = useCallback((data: CandlestickData) => {
    if (seriesRef.current.candlestick) {
      seriesRef.current.candlestick.update(data);
    }
  }, []);

  /**
   * Set volume data
   */
  const setVolumeData = useCallback((data: VolumeData[]) => {
    if (seriesRef.current.volume) {
      seriesRef.current.volume.setData(data);
    }
  }, []);

  /**
   * Update volume (add or update last bar)
   */
  const updateVolume = useCallback((data: VolumeData) => {
    if (seriesRef.current.volume) {
      seriesRef.current.volume.update(data);
    }
  }, []);

  /**
   * Set bars data (converts Bar[] to candlestick and volume)
   */
  const setBarsData = useCallback((bars: Bar[]) => {
    const theme = options?.theme || DEFAULT_THEME;
    
    const candlestickData: CandlestickData[] = bars.map(bar => ({
      time: bar.time,
      open: bar.open,
      high: bar.high,
      low: bar.low,
      close: bar.close,
    }));

    const volumeData: VolumeData[] = bars.map(bar => ({
      time: bar.time,
      value: bar.volume,
      color: bar.close >= bar.open ? theme.volumeUpColor : theme.volumeDownColor,
    }));

    setCandlestickData(candlestickData);
    setVolumeData(volumeData);
  }, [setCandlestickData, setVolumeData, options?.theme]);

  /**
   * Update with new bar (real-time)
   */
  const updateBar = useCallback((bar: Bar) => {
    const theme = options?.theme || DEFAULT_THEME;
    
    updateCandlestick({
      time: bar.time,
      open: bar.open,
      high: bar.high,
      low: bar.low,
      close: bar.close,
    });

    updateVolume({
      time: bar.time,
      value: bar.volume,
      color: bar.close >= bar.open ? theme.volumeUpColor : theme.volumeDownColor,
    });
  }, [updateCandlestick, updateVolume, options?.theme]);

  /**
   * Add indicator line series
   */
  const addIndicator = useCallback((id: string, color: string, name: string) => {
    if (!chartRef.current) return;

    const series = chartRef.current.addSeries(LineSeries, {
      color,
      lineWidth: 2,
      title: name,
    });

    seriesRef.current.indicators.set(id, series);
    return series;
  }, []);

  /**
   * Remove indicator
   */
  const removeIndicator = useCallback((id: string) => {
    const series = seriesRef.current.indicators.get(id);
    if (series && chartRef.current) {
      chartRef.current.removeSeries(series);
      seriesRef.current.indicators.delete(id);
    }
  }, []);

  /**
   * Update indicator data
   */
  const updateIndicator = useCallback((id: string, data: Array<{ time: Time; value: number }>) => {
    const series = seriesRef.current.indicators.get(id);
    if (series) {
      series.setData(data);
    }
  }, []);

  /**
   * Fit content
   */
  const fitContent = useCallback(() => {
    if (chartRef.current) {
      chartRef.current.timeScale().fitContent();
    }
  }, []);

  /**
   * Subscribe to crosshair move
   */
  const subscribeCrosshairMove = useCallback((
    handler: (param: MouseEventParams) => void
  ) => {
    if (chartRef.current) {
      chartRef.current.subscribeCrosshairMove(handler);
    }
  }, []);

  /**
   * Unsubscribe from crosshair move
   */
  const unsubscribeCrosshairMove = useCallback((
    handler: (param: MouseEventParams) => void
  ) => {
    if (chartRef.current) {
      chartRef.current.unsubscribeCrosshairMove(handler);
    }
  }, []);

  return {
    chart: chartRef.current,
    series: seriesRef.current,
    isReady,
    
    // Data methods
    setCandlestickData,
    updateCandlestick,
    setVolumeData,
    updateVolume,
    setBarsData,
    updateBar,
    
    // Indicator methods
    addIndicator,
    removeIndicator,
    updateIndicator,
    
    // Utility methods
    fitContent,
    subscribeCrosshairMove,
    unsubscribeCrosshairMove,
  };
}

/**
 * useDrawingTools Hook
 * 
 * Manages chart drawing tools: creation, editing, persistence, and rendering.
 * 
 * Features:
 * - Handle chart click events for drawing creation
 * - Manage drawing state (active drawings, drawing mode)
 * - API integration (save/load/delete drawings)
 * - Undo/redo functionality
 * - Chart rendering of drawings
 * 
 * Phase 7 - Market Data & Charting
 * Created: October 16, 2025
 */

import { useState, useCallback, useRef, useEffect } from 'react';
import { message } from 'antd';
import { LineSeries, type IChartApi, type ISeriesApi, type MouseEventParams, type Time } from 'lightweight-charts';
import type { Drawing, DrawingType, DrawingStyle, Point } from '../components/market/DrawingTools';
import { apiClient } from '../services/api';

// Extended chart interface for methods not in type definitions
interface ExtendedChartApi extends IChartApi {
  subscribeClick: (handler: (params: MouseEventParams) => void) => void;
  unsubscribeClick: (handler: (params: MouseEventParams) => void) => void;
}

// ============================================================================
// TYPES
// ============================================================================

interface UseDrawingToolsProps {
  chart: IChartApi | null;
  symbol: string;
  timeframe: string;
}

interface UseDrawingToolsReturn {
  drawings: Drawing[];
  selectedTool: DrawingType | null;
  style: DrawingStyle;
  loading: boolean;
  error: string | null;
  selectTool: (tool: DrawingType | null) => void;
  updateStyle: (style: Partial<DrawingStyle>) => void;
  saveDrawings: () => Promise<void>;
  loadDrawings: () => Promise<void>;
  clearDrawings: () => void;
  undoLastDrawing: () => void;
  deleteDrawing: (id: string) => void;
}

// ============================================================================
// API CLIENT
// ============================================================================

class DrawingsAPI {
  async getDrawings(symbol: string, timeframe: string): Promise<Drawing[]> {
    try {
      const response = await apiClient.get(`/drawings/${symbol}?timeframe=${timeframe}`);
      return response.data;
    } catch (error: unknown) {
      // Silently handle 401 errors (user not logged in)
      const axiosError = error as { response?: { status?: number } };
      if (axiosError?.response?.status === 401) {
        return [];
      }
      throw error;
    }
  }

  async createDrawing(drawing: Omit<Drawing, 'id'>): Promise<Drawing> {
    const response = await apiClient.post('/drawings/', drawing);
    return response.data;
  }

  async deleteDrawing(id: string): Promise<void> {
    await apiClient.delete(`/drawings/${id}`);
  }

  async deleteAllDrawings(symbol: string, timeframe: string): Promise<void> {
    await apiClient.delete(`/drawings/symbol/${symbol}?timeframe=${timeframe}`);
  }
}

// ============================================================================
// HOOK
// ============================================================================

export const useDrawingTools = ({
  chart,
  symbol,
  timeframe,
}: UseDrawingToolsProps): UseDrawingToolsReturn => {
  // State
  const [drawings, setDrawings] = useState<Drawing[]>([]);
  const [selectedTool, setSelectedTool] = useState<DrawingType | null>(null);
  const [style, setStyle] = useState<DrawingStyle>({
    color: '#2962FF',
    lineWidth: 2,
    lineStyle: 'solid',
    fillColor: '#2962FF',
    fillOpacity: 0.2,
    textSize: 12,
  });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Refs
  const apiRef = useRef(new DrawingsAPI());
  const drawingPointsRef = useRef<Point[]>([]);
  const chartSeriesRef = useRef<Map<string, unknown>>(new Map());
  const drawingHistoryRef = useRef<Drawing[]>([]);

  // Convert chart coordinates to point
  const chartPointToPoint = useCallback((params: MouseEventParams): Point | null => {
    if (!params.time || params.point === undefined) return null;

    const price = params.seriesData?.get(params.time as Time);
    if (!price) return null;

    const priceData = price as { close?: number; value?: number };
    return {
      time: params.time as number,
      price: priceData.close || priceData.value || 0,
    };
  }, []);

  // Render drawing on chart
  const renderDrawing = useCallback(
    (drawing: Drawing) => {
      if (!chart) return;

      try {
        const { type, points, style: drawingStyle } = drawing;

        switch (type) {
          case 'trendline': {
            if (points.length !== 2) return;
            
            // Create line series for trendline
            const series = chart.addSeries(LineSeries, {
              color: drawingStyle.color,
              lineWidth: drawingStyle.lineWidth,
              lineStyle: drawingStyle.lineStyle === 'dashed' ? 1 : 
                        drawingStyle.lineStyle === 'dotted' ? 2 : 0,
              priceScaleId: 'right',
            });

            // Calculate line points
            const data = [
              { time: points[0].time as Time, value: points[0].price },
              { time: points[1].time as Time, value: points[1].price },
            ];
            series.setData(data);

            chartSeriesRef.current.set(drawing.id, series);
            break;
          }

          case 'horizontal': {
            if (points.length !== 1) return;

            // Create horizontal price line
            const priceLine = {
              price: points[0].price,
              color: drawingStyle.color,
              lineWidth: drawingStyle.lineWidth,
              lineStyle: drawingStyle.lineStyle === 'dashed' ? 1 : 
                        drawingStyle.lineStyle === 'dotted' ? 2 : 0,
              axisLabelVisible: true,
              title: 'H',
            };

            // Store price line reference
            chartSeriesRef.current.set(drawing.id, priceLine);
            break;
          }

          case 'vertical': {
            // Vertical lines require custom rendering (not natively supported)
            // TODO: Implement custom vertical line rendering
            console.warn('Vertical lines not yet implemented');
            break;
          }

          case 'fibonacci': {
            if (points.length !== 2) return;

            // Calculate Fibonacci levels
            const diff = points[1].price - points[0].price;
            const levels = [0, 0.236, 0.382, 0.5, 0.618, 0.786, 1.0];
            const fibSeries: ISeriesApi<'Line'>[] = [];

            levels.forEach((level) => {
              const price = points[0].price + diff * level;
              const series = chart.addSeries(LineSeries, {
                color: drawingStyle.color,
                lineWidth: 1,
                lineStyle: 1, // dashed
                priceScaleId: 'right',
              });

              const data = [
                { time: points[0].time as Time, value: price },
                { time: points[1].time as Time, value: price },
              ];
              series.setData(data);

              fibSeries.push(series);
            });

            chartSeriesRef.current.set(drawing.id, fibSeries);
            break;
          }

          case 'rectangle':
          case 'ellipse': {
            // Shapes require custom rendering
            // TODO: Implement custom shape rendering
            console.warn(`${type} not yet fully implemented`);
            break;
          }

          case 'text': {
            // Text annotations require custom markers
            // TODO: Implement text markers
            console.warn('Text annotations not yet implemented');
            break;
          }

          default:
            console.warn(`Unknown drawing type: ${type}`);
        }
      } catch (err) {
        console.error('Failed to render drawing:', err);
      }
    },
    [chart]
  );

  // Remove drawing from chart
  const removeDrawingFromChart = useCallback(
    (drawingId: string) => {
      if (!chart) return;

      try {
        const series = chartSeriesRef.current.get(drawingId);
        if (series) {
          if (Array.isArray(series)) {
            // Multiple series (e.g., Fibonacci)
            series.forEach((s) => {
              try {
                chart.removeSeries(s as ISeriesApi<'Line'>);
              } catch (err) {
                console.error('Failed to remove series:', err);
              }
            });
          } else {
            // Single series
            try {
              chart.removeSeries(series as ISeriesApi<'Line'>);
            } catch (err) {
              console.error('Failed to remove series:', err);
            }
          }
          chartSeriesRef.current.delete(drawingId);
        }
      } catch (err) {
        console.error('Failed to remove drawing from chart:', err);
      }
    },
    [chart]
  );

  // Handle chart click for drawing
  const handleChartClick = useCallback(
    (params: MouseEventParams) => {
      if (!selectedTool || !chart) return;

      const point = chartPointToPoint(params);
      if (!point) return;

      drawingPointsRef.current.push(point);

      // Determine if drawing is complete
      const requiredPoints: Record<DrawingType, number> = {
        trendline: 2,
        horizontal: 1,
        vertical: 1,
        fibonacci: 2,
        rectangle: 2,
        ellipse: 2,
        text: 1,
      };

      const required = requiredPoints[selectedTool];
      
      if (drawingPointsRef.current.length >= required) {
        // Create drawing
        const newDrawing: Omit<Drawing, 'id'> = {
          symbol,
          type: selectedTool,
          points: [...drawingPointsRef.current],
          style,
          timeframe,
        };

        // Add to state (with temporary ID)
        const tempDrawing: Drawing = {
          ...newDrawing,
          id: `temp_${Date.now()}`,
        };

        setDrawings((prev) => [...prev, tempDrawing]);
        drawingHistoryRef.current.push(tempDrawing);

        // Render on chart
        renderDrawing(tempDrawing);

        // Reset points
        drawingPointsRef.current = [];

        message.success(`${selectedTool} created`);

        // Auto-deselect tool after single-point tools
        if (required === 1) {
          setSelectedTool(null);
        }
      } else {
        // Show feedback for multi-point tools
        message.info(`Click ${required - drawingPointsRef.current.length} more point(s)`);
      }
    },
    [selectedTool, chart, symbol, timeframe, style, chartPointToPoint, renderDrawing]
  );

  // Subscribe to chart clicks
  useEffect(() => {
    if (!chart) return;

    const clickHandler = (params: MouseEventParams) => {
      handleChartClick(params);
    };

    const extendedChart = chart as ExtendedChartApi;
    extendedChart.subscribeClick(clickHandler);

    return () => {
      try {
        extendedChart.unsubscribeClick(clickHandler);
      } catch (_err: unknown) {
        // Ignore unsubscribe errors
      }
    };
  }, [chart, handleChartClick]);

  // Select tool
  const selectTool = useCallback((tool: DrawingType | null) => {
    setSelectedTool(tool);
    drawingPointsRef.current = []; // Reset points when changing tool
    
    if (tool) {
      message.info(`${tool} tool selected. Click on chart to draw.`);
    }
  }, []);

  // Update style
  const updateStyle = useCallback((updates: Partial<DrawingStyle>) => {
    setStyle((prev) => ({ ...prev, ...updates }));
  }, []);

  // Save drawings to backend
  const saveDrawings = useCallback(async () => {
    setLoading(true);
    setError(null);

    try {
      // Filter out temporary drawings and save to backend
      const unsavedDrawings = drawings.filter((d) => d.id.startsWith('temp_'));

      for (const drawing of unsavedDrawings) {
        const { id: _id, ...drawingData } = drawing;
        await apiRef.current.createDrawing(drawingData);
      }

      // Reload all drawings from backend to get proper IDs
      await loadDrawings();

      message.success(`Saved ${unsavedDrawings.length} drawing(s)`);
    } catch (err) {
      const errorMsg = err instanceof Error ? err.message : 'Failed to save drawings';
      setError(errorMsg);
      message.error(errorMsg);
      console.error('Save drawings error:', err);
    } finally {
      setLoading(false);
    }
  }, [drawings]);

  // Load drawings from backend
  const loadDrawings = useCallback(async () => {
    setLoading(true);
    setError(null);

    try {
      const loadedDrawings = await apiRef.current.getDrawings(symbol, timeframe);
      
      // Clear existing chart drawings
      chartSeriesRef.current.forEach((_, id) => {
        removeDrawingFromChart(id);
      });

      // Render loaded drawings
      loadedDrawings.forEach((drawing) => {
        renderDrawing(drawing);
      });

      setDrawings(loadedDrawings);
      drawingHistoryRef.current = [...loadedDrawings];
    } catch (err) {
      // Silently handle auth errors (user not logged in)
      const errorMsg = err instanceof Error ? err.message : 'Failed to load drawings';
      if (!errorMsg.includes('Authentication')) {
        setError(errorMsg);
        console.error('Load drawings error:', err);
      }
    } finally {
      setLoading(false);
    }
  }, [symbol, timeframe, renderDrawing, removeDrawingFromChart]);

  // Clear all drawings
  const clearDrawings = useCallback(() => {
    // Remove from chart
    chartSeriesRef.current.forEach((_, id) => {
      removeDrawingFromChart(id);
    });

    // Clear state
    setDrawings([]);
    drawingHistoryRef.current = [];
    drawingPointsRef.current = [];
  }, [removeDrawingFromChart]);

  // Undo last drawing
  const undoLastDrawing = useCallback(() => {
    if (drawings.length === 0) {
      message.warning('No drawings to undo');
      return;
    }

    const lastDrawing = drawings[drawings.length - 1];
    
    // Remove from chart
    removeDrawingFromChart(lastDrawing.id);

    // Remove from state
    setDrawings((prev) => prev.slice(0, -1));
    drawingHistoryRef.current = drawingHistoryRef.current.slice(0, -1);
  }, [drawings, removeDrawingFromChart]);

  // Delete specific drawing
  const deleteDrawing = useCallback(
    async (id: string) => {
      try {
        // If it's a saved drawing (not temporary), delete from backend
        if (!id.startsWith('temp_')) {
          await apiRef.current.deleteDrawing(id);
        }

        // Remove from chart
        removeDrawingFromChart(id);

        // Remove from state
        setDrawings((prev) => prev.filter((d) => d.id !== id));
        drawingHistoryRef.current = drawingHistoryRef.current.filter((d) => d.id !== id);

        message.success('Drawing deleted');
      } catch (err) {
        const errorMsg = err instanceof Error ? err.message : 'Failed to delete drawing';
        message.error(errorMsg);
        console.error('Delete drawing error:', err);
      }
    },
    [removeDrawingFromChart]
  );

  // Load drawings on mount and when symbol/timeframe changes
  useEffect(() => {
    if (chart && symbol && timeframe) {
      loadDrawings();
    }
  }, [chart, symbol, timeframe]); // Intentionally not including loadDrawings to avoid loops

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      clearDrawings();
    };
  }, []); // Intentionally empty to only run on unmount

  return {
    drawings,
    selectedTool,
    style,
    loading,
    error,
    selectTool,
    updateStyle,
    saveDrawings,
    loadDrawings,
    clearDrawings,
    undoLastDrawing,
    deleteDrawing,
  };
};

export default useDrawingTools;

/**
 * useIndicators Hook
 * 
 * Manages technical indicators: fetching data, adding to chart, caching results.
 * 
 * Features:
 * - Fetch indicator data from backend API
 * - Add/remove indicators to/from chart
 * - Update indicator parameters
 * - Cache indicator results
 * - Handle loading/error states
 * 
 * Phase 7 - Market Data & Charting
 * Created: October 16, 2025
 */

import { useState, useCallback, useRef, useEffect } from 'react';
import { App } from 'antd';
import { LineSeries, HistogramSeries, type IChartApi, type ISeriesApi, type Time, type LineData, type HistogramData } from 'lightweight-charts';
import type { IndicatorConfig } from '../components/market/IndicatorPanel';
import { apiClient } from '../services/api';

// ============================================================================
// TYPES
// ============================================================================

interface IndicatorData {
  symbol: string;
  indicator: string;
  timeframe: string;
  values: Record<string, unknown>;
  params: Record<string, number>;
}

interface IndicatorSeries {
  id: string;
  config: IndicatorConfig;
  series: ISeriesApi<'Line'> | ISeriesApi<'Histogram'> | null;
  data: IndicatorData | null;
}

interface UseIndicatorsProps {
  chart: IChartApi | null;
  symbol: string;
  timeframe: string;
}

interface UseIndicatorsReturn {
  indicators: IndicatorSeries[];
  loading: boolean;
  error: string | null;
  addIndicator: (config: IndicatorConfig) => Promise<void>;
  removeIndicator: (id: string) => void;
  updateIndicator: (id: string, updates: Partial<IndicatorConfig>) => Promise<void>;
  clearIndicators: () => void;
  refreshIndicators: () => Promise<void>;
}

// ============================================================================
// API CLIENT
// ============================================================================

class IndicatorsAPI {
  async calculateIndicator(
    symbol: string,
    indicator: string,
    timeframe: string,
    params: Record<string, number>,
    start: Date,
    end: Date
  ): Promise<IndicatorData> {
    try {
      const response = await apiClient.post('/indicators/calculate', {
        symbol,
        indicator,
        timeframe,
        start: start.toISOString(),
        end: end.toISOString(),
        params,
      });
      
      return response.data;
    } catch (error: unknown) {
      const axiosError = error as { response?: { data?: unknown }; message?: string };
      console.error(`Failed to calculate ${indicator}:`, axiosError.response?.data || axiosError.message);
      throw error;
    }
  }

  async calculateBatch(
    symbol: string,
    timeframe: string,
    indicators: Array<{ indicator: string; params: Record<string, number> }>,
    start: Date,
    end: Date
  ): Promise<{ symbol: string; results: IndicatorData[] }> {
    const response = await apiClient.post('/indicators/batch', {
      symbol,
      timeframe,
      start: start.toISOString(),
      end: end.toISOString(),
      indicators,
    });

    return response.data;
  }
}

// ============================================================================
// HOOK
// ============================================================================

export const useIndicators = ({
  chart,
  symbol,
  timeframe,
}: UseIndicatorsProps): UseIndicatorsReturn => {
  // Get message API from App context
  const { message } = App.useApp();
  
  // State
  const [indicators, setIndicators] = useState<IndicatorSeries[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Refs
  const apiRef = useRef(new IndicatorsAPI());
  const cacheRef = useRef<Map<string, IndicatorData>>(new Map());

  // Generate cache key
  const getCacheKey = useCallback(
    (indicator: string, params: Record<string, number>) => {
      const paramsStr = Object.entries(params)
        .sort(([a], [b]) => a.localeCompare(b))
        .map(([k, v]) => `${k}=${v}`)
        .join('&');
      return `${symbol}_${indicator}_${timeframe}_${paramsStr}`;
    },
    [symbol, timeframe]
  );

  // Get dedicated scale ID for indicator
  const getScaleIdForIndicator = useCallback((indicatorName: string): string => {
    // OVERLAY INDICATORS: Display on main price scale (right)
    // These are price-based indicators that make sense at stock price levels
    const overlayIndicators = [
      'sma', 'ema', 'wma', 'vwma', 'tema', 'dema', 'trima', 'zlema',
      'bollinger', 'donchian', 'keltner', 'envelope',
      'ichimoku', 'parabolic_sar', 'supertrend', 'pivot',
      'vwap', 'twap', 'regression'
    ];
    
    // BOUNDED OSCILLATORS (0-100 range): Get dedicated scale
    const boundedOscillators: Record<string, string> = {
      'rsi': 'rsi-scale',           // 0-100
      'stochastic': 'stoch-scale',  // 0-100  
      'williams_r': 'williams-scale', // -100 to 0
      'mfi': 'mfi-scale',           // 0-100
    };
    
    // MOMENTUM INDICATORS: Get dedicated scales (unbounded, can go negative)
    const momentumIndicators: Record<string, string> = {
      'macd': 'macd-scale',
      'cci': 'cci-scale',
      'roc': 'roc-scale',
      'tsi': 'tsi-scale',
      'adx': 'adx-scale',
      'aroon': 'aroon-scale',
      'ultimate': 'ultimate-scale',
      'awesome': 'awesome-scale',
    };
    
    // VOLUME INDICATORS: Get dedicated scale
    const volumeIndicators: Record<string, string> = {
      'volume_ma': 'volume-scale',
      'obv': 'obv-scale',
      'ad': 'ad-scale',
      'cmf': 'cmf-scale',
    };
    
    // Determine scale ID
    if (overlayIndicators.includes(indicatorName)) {
      return 'right'; // Share main price scale
    } else if (boundedOscillators[indicatorName]) {
      return boundedOscillators[indicatorName];
    } else if (momentumIndicators[indicatorName]) {
      return momentumIndicators[indicatorName];
    } else if (volumeIndicators[indicatorName]) {
      return volumeIndicators[indicatorName];
    }
    
    // Default: separate scale
    return `${indicatorName}-scale`;
  }, []);

  // Configure scale options for indicator
  const configureScale = useCallback((indicatorName: string, scaleId: string) => {
    if (!chart || scaleId === 'right') return; // Don't configure main price scale
    
    const scale = chart.priceScale(scaleId);
    
    // Bounded oscillators (0-100 range)
    if (['rsi', 'stochastic', 'mfi'].includes(indicatorName)) {
      scale.applyOptions({
        scaleMargins: {
          top: 0.1,
          bottom: 0.1,
        },
        autoScale: false,
      });
    }
    // Williams %R (-100 to 0)
    else if (indicatorName === 'williams_r') {
      scale.applyOptions({
        scaleMargins: {
          top: 0.1,
          bottom: 0.1,
        },
        autoScale: false,
      });
    }
    // ADX (0-100, but typically 0-60)
    else if (indicatorName === 'adx') {
      scale.applyOptions({
        scaleMargins: {
          top: 0.1,
          bottom: 0.1,
        },
        autoScale: true,
      });
    }
    // Momentum indicators (unbounded, auto-scale)
    else if (['macd', 'cci', 'roc', 'tsi', 'aroon', 'ultimate', 'awesome'].includes(indicatorName)) {
      scale.applyOptions({
        scaleMargins: {
          top: 0.15,
          bottom: 0.15,
        },
        autoScale: true,
      });
    }
    // Volume indicators
    else if (['volume_ma', 'obv', 'ad', 'cmf'].includes(indicatorName)) {
      scale.applyOptions({
        scaleMargins: {
          top: 0.8, // Push to bottom like volume
          bottom: 0,
        },
        autoScale: true,
      });
    }
    // Default: auto-scale with margins
    else {
      scale.applyOptions({
        scaleMargins: {
          top: 0.15,
          bottom: 0.15,
        },
        autoScale: true,
      });
    }
  }, [chart]);

  // Create series on chart
  const createSeries = useCallback(
    (config: IndicatorConfig): ISeriesApi<'Line'> | ISeriesApi<'Histogram'> | null => {
      if (!chart) {
        console.error('Cannot create series: chart is null');
        return null;
      }

      try {
        const scaleId = getScaleIdForIndicator(config.name);
        const isHistogram = ['volume_ma', 'obv', 'ad', 'macd'].includes(config.name);
        
        console.log(`[useIndicators] Creating series for ${config.name}:`, {
          scaleId,
          isHistogram,
          color: config.color,
        });

        // Create series with dedicated scale
        let series;
        if (isHistogram) {
          series = chart.addSeries(HistogramSeries, {
            color: config.color,
            priceFormat: {
              type: 'volume',
            },
            priceScaleId: scaleId,
          });
        } else {
          series = chart.addSeries(LineSeries, {
            color: config.color,
            lineWidth: 2,
            priceScaleId: scaleId,
          });
        }
        
        // Configure the scale
        configureScale(config.name, scaleId);
        
        console.log(`[useIndicators] Created series for ${config.name} on scale '${scaleId}'`);
        return series;
      } catch (err) {
        console.error('Failed to create series:', err);
        return null;
      }
    },
    [chart, getScaleIdForIndicator, configureScale]
  );

  // Convert indicator data to chart format
  const convertToChartData = useCallback(
    (indicatorData: IndicatorData, indicator: string): LineData[] | HistogramData[] => {
      console.log(`[convertToChartData] Converting ${indicator}:`, {
        indicatorData,
        hasValues: !!indicatorData?.values,
        valuesType: typeof indicatorData?.values,
        valuesKeys: indicatorData?.values ? Object.keys(indicatorData.values).slice(0, 10) : [],
      });

      const { values } = indicatorData;
      
      if (!values) {
        console.warn(`[convertToChartData] No values in indicatorData for ${indicator}`);
        return [];
      }
      
      // Helper to filter out null/undefined values
      const filterValidEntries = (entries: [string, unknown][]): [string, number][] => {
        const filtered = entries.filter(([_key, value]) => value !== null && value !== undefined && !isNaN(value as number)) as [string, number][];
        console.log(`[convertToChartData] Filtered ${entries.length} entries to ${filtered.length} valid entries`);
        return filtered;
      };

      // Handle different indicator output formats
      if (indicator === 'macd') {
        // MACD returns histogram
        const histogram = values.histogram || {};
        const validEntries = filterValidEntries(Object.entries(histogram));
        return validEntries.map(([time, value]) => ({
          time: new Date(time).getTime() / 1000 as Time,
          value: value,
        }));
      } else if (indicator === 'bollinger') {
        // Bollinger returns 3 lines - just show middle for now
        const middle = values.middle || {};
        const validEntries = filterValidEntries(Object.entries(middle));
        return validEntries.map(([time, value]) => ({
          time: new Date(time).getTime() / 1000 as Time,
          value: value,
        }));
      } else if (indicator === 'ichimoku') {
        // Ichimoku returns 5 lines - show tenkan for now
        const tenkan = values.tenkan || {};
        const validEntries = filterValidEntries(Object.entries(tenkan));
        return validEntries.map(([time, value]) => ({
          time: new Date(time).getTime() / 1000 as Time,
          value: value,
        }));
      } else {
        // Standard format: {time: value}
        console.log(`[convertToChartData] Pre-access check:`, {
          hasValuesValues: !!(values && values.values),
          valuesValuesType: values && values.values ? typeof values.values : 'N/A',
          valuesKeys: values ? Object.keys(values) : [],
          valuesValuesKeys: values && values.values ? Object.keys(values.values).slice(0, 5) : [],
        });
        
        const dataValues = values.values || values;
        console.log(`[convertToChartData] Using dataValues:`, {
          dataValues: typeof dataValues,
          isObject: typeof dataValues === 'object',
          isNull: dataValues === null,
          isUndefined: dataValues === undefined,
          keys: typeof dataValues === 'object' && dataValues !== null ? Object.keys(dataValues).slice(0, 10) : [],
          firstEntry: typeof dataValues === 'object' && dataValues !== null ? Object.entries(dataValues)[0] : null,
          rawDataValues: dataValues, // Show actual object
        });
        
        if (!dataValues || typeof dataValues !== 'object' || Object.keys(dataValues).length === 0) {
          console.error(`[convertToChartData] dataValues is empty or invalid for ${indicator}:`, {
            dataValues,
            originalValues: values,
          });
          return [];
        }
        
        const validEntries = filterValidEntries(Object.entries(dataValues));
        
        const result = validEntries.map(([time, value]) => ({
          time: new Date(time).getTime() / 1000 as Time,
          value: value,
        }));
        
        console.log(`[convertToChartData] Converted to ${result.length} chart points`);
        return result;
      }
    },
    []
  );

  // Add indicator
  const addIndicator = useCallback(
    async (config: IndicatorConfig) => {
      if (!chart) {
        message.error('Chart not initialized');
        return;
      }

      setLoading(true);
      setError(null);

      try {
        // Check cache
        const cacheKey = getCacheKey(config.name, config.params);
        let indicatorData = cacheRef.current.get(cacheKey);

        // Fetch from API if not cached
        if (!indicatorData) {
          // Use last 6 months of data
          const end = new Date();
          const start = new Date();
          start.setMonth(start.getMonth() - 6);

          indicatorData = await apiRef.current.calculateIndicator(
            symbol,
            config.name,
            timeframe,
            config.params,
            start,
            end
          );

          console.log(`[useIndicators] Raw API response for ${config.name}:`, {
            fullResponse: indicatorData,
            indicator: indicatorData.indicator,
            valuesKeys: indicatorData.values ? Object.keys(indicatorData.values) : [],
            valuesValuesKeys: indicatorData.values?.values ? Object.keys(indicatorData.values.values) : [],
            firstValueSample: indicatorData.values?.values ? 
              Object.entries(indicatorData.values.values)[0] : null,
          });

          // Cache result
          cacheRef.current.set(cacheKey, indicatorData);
        }

        // Create series
        const series = createSeries(config);
        if (!series) {
          throw new Error('Failed to create chart series');
        }

        // Convert and set data
        const chartData = convertToChartData(indicatorData, config.name);
        console.log(`[useIndicators] Setting data for ${config.name}:`, {
          dataPoints: chartData.length,
          firstPoint: chartData[0],
          lastPoint: chartData[chartData.length - 1],
          rawDataStructure: indicatorData ? {
            hasValues: !!indicatorData.values,
            valuesKeys: indicatorData.values ? Object.keys(indicatorData.values).slice(0, 5) : [],
            firstValueKey: indicatorData.values ? Object.keys(indicatorData.values)[0] : null,
            firstValue: indicatorData.values ? indicatorData.values[Object.keys(indicatorData.values)[0]] : null,
          } : 'no data',
        });
        
        series.setData(chartData);
        console.log(`[useIndicators] Data set successfully for ${config.name}`);

        // Add to state
        setIndicators((prev) => [
          ...prev,
          {
            id: config.id,
            config,
            series,
            data: indicatorData,
          },
        ]);

        message.success(`Added ${config.displayName}`);
      } catch (err) {
        const errorMsg = err instanceof Error ? err.message : 'Failed to add indicator';
        setError(errorMsg);
        message.error(errorMsg);
        console.error('Failed to add indicator:', err);
      } finally {
        setLoading(false);
      }
    },
    [chart, symbol, timeframe, getCacheKey, createSeries, convertToChartData]
  );

  // Remove indicator
  const removeIndicator = useCallback(
    (id: string) => {
      let actuallyRemoved = false;
      
      setIndicators((prev) => {
        // Check if indicator exists before attempting removal
        const indicator = prev.find((ind) => ind.id === id);
        
        if (!indicator) {
          // Already removed in a previous call
          return prev;
        }
        
        // Mark that we're actually removing something
        actuallyRemoved = true;
        
        // Try to remove series from chart if it exists
        if (indicator.series && chart) {
          try {
            const series = indicator.series;
            
            // Check if series is actually a lightweight-charts series
            const isValidSeries = series && 
              typeof series === 'object' && 
              (typeof series.setData === 'function' || 
               typeof series.update === 'function' ||
               typeof series.applyOptions === 'function');
            
            if (isValidSeries) {
              try {
                // Wrapped in additional try-catch to handle chart internal errors
                chart.removeSeries(series);
              } catch (_removeErr: unknown) {
                // Silently handle "Value is undefined" errors from chart internals
                // Don't log - this is expected in some cases
              }
            }
          } catch (_err: unknown) {
            // Silently handle errors
          }
        }
        
        // Remove from state
        return prev.filter((ind) => ind.id !== id);
      });
      
      // Only show message if we actually removed something
      if (actuallyRemoved) {
        message.success('Indicator removed');
      }
    },
    [chart, message]
  );

  // Update indicator
  const updateIndicator = useCallback(
    async (id: string, updates: Partial<IndicatorConfig>) => {
      const indicator = indicators.find((ind) => ind.id === id);
      if (!indicator) return;

      // If just toggling enabled state
      if ('enabled' in updates && updates.enabled !== undefined) {
        setIndicators((prev) =>
          prev.map((ind) =>
            ind.id === id
              ? { ...ind, config: { ...ind.config, enabled: updates.enabled! } }
              : ind
          )
        );

        // Show/hide series
        if (indicator.series) {
          try {
            indicator.series.applyOptions({
              visible: updates.enabled,
            });
          } catch (err) {
            console.error('Failed to update series visibility:', err);
          }
        }
        return;
      }

      // If updating params, need to recalculate
      if (updates.params) {
        // Remove old series
        removeIndicator(id);

        // Add with new config
        const newConfig: IndicatorConfig = {
          ...indicator.config,
          ...updates,
          params: updates.params,
        };
        await addIndicator(newConfig);
      }
    },
    [indicators, addIndicator, removeIndicator]
  );

  // Clear all indicators
  const clearIndicators = useCallback(() => {
    setIndicators((currentIndicators) => {
      // Use functional update to access current state without dependency
      currentIndicators.forEach((indicator) => {
        if (indicator.series && chart) {
          try {
            chart.removeSeries(indicator.series);
          } catch (err) {
            console.error('Failed to remove series:', err);
          }
        }
      });
      return [];
    });
    message.info('All indicators cleared');
  }, [chart]); // Only depend on chart, not indicators

  // Refresh all indicators
  const refreshIndicators = useCallback(async () => {
    // Clear cache
    cacheRef.current.clear();

    // Get current indicator configs before clearing
    const configs = indicators.map((ind) => ind.config);
    
    // Clear all indicators
    clearIndicators();

    // Reload all enabled indicators
    for (const config of configs) {
      if (config.enabled) {
        await addIndicator(config);
      }
    }
  }, [indicators, clearIndicators, addIndicator]);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      clearIndicators();
    };
  }, [clearIndicators]);

  return {
    indicators,
    loading,
    error,
    addIndicator,
    removeIndicator,
    updateIndicator,
    clearIndicators,
    refreshIndicators,
  };
};

export default useIndicators;

/**
 * Market Data WebSocket Hook
 * 
 * React hook for managing WebSocket connection to market data service
 * Integrates WebSocket service with Zustand store
 */

import { useEffect, useCallback, useRef, useMemo } from 'react';
import { useMarketDataStore } from '../store/marketDataStore';
import { getMarketDataService } from '../services/marketDataWebSocketService';
import { ConnectionState } from '../types/marketData';
import type { Quote, ErrorMessage } from '../types/marketData';
import { getAuthToken } from '../utils/auth'; // Use centralized auth utility

/**
 * Hook for managing market data WebSocket connection
 * 
 * @example
 * ```tsx
 * function MyComponent() {
 *   const { subscribe, unsubscribe, connected } = useMarketDataWebSocket();
 *   
 *   useEffect(() => {
 *     subscribe('AAPL');
 *     return () => unsubscribe('AAPL');
 *   }, []);
 *   
 *   const quote = useQuote('AAPL');
 *   return <div>AAPL: ${quote?.last}</div>;
 * }
 * ```
 */
export function useMarketDataWebSocket() {
  const service = useRef(getMarketDataService());
  
  // Track if initialized
  const initialized = useRef(false);
  
  /**
   * Initialize WebSocket connection and callbacks
   */
  useEffect(() => {
    if (initialized.current) return;
    initialized.current = true;
    
    const marketDataService = service.current;
    
    // Set up connection state callback
    const unsubscribeConnection = marketDataService.onConnectionStateChange((state) => {
      const storeState = useMarketDataStore.getState();
      storeState.setConnectionState(state);
      
      // Clear quotes on disconnect
      if (state === ConnectionState.DISCONNECTED || state === ConnectionState.FAILED) {
        storeState.clearQuotes();
      }
    });
    
    // Set up error callback
    const unsubscribeError = marketDataService.onError((error: ErrorMessage) => {
      console.error('[useMarketDataWebSocket] Error:', error.message, error.code);
      const storeState = useMarketDataStore.getState();
      storeState.setError(error.message);
      
      // Clear error after 5 seconds
      setTimeout(() => {
        useMarketDataStore.getState().setError(null);
      }, 5000);
    });
    
    // Connect to WebSocket
    const token = getAuthToken();
    if (token) {
      marketDataService.connect(token).catch((error) => {
        console.error('[useMarketDataWebSocket] Connection failed:', error);
        useMarketDataStore.getState().setError('Failed to connect to market data service');
      });
    } else {
      console.warn('[useMarketDataWebSocket] No auth token found');
      useMarketDataStore.getState().setError('Authentication required');
    }
    
    // Cleanup on unmount
    return () => {
      unsubscribeConnection();
      unsubscribeError();
      // Note: Don't disconnect here as other components might be using it
      // Connection will be managed by the service singleton
    };
  }, []); // Run once on mount
  
  /**
   * Subscribe to symbol quotes
   */
  const subscribe = useCallback((symbol: string) => {
    const normalizedSymbol = symbol.toUpperCase();
    const storeState = useMarketDataStore.getState();
    
    // Add to store subscriptions
    storeState.addSubscription(normalizedSymbol);
    
    // Subscribe to service with callback
    const callback = (quote: Quote) => {
      useMarketDataStore.getState().updateQuote(normalizedSymbol, quote);
    };
    
    service.current.subscribe(normalizedSymbol, callback);
    
    return () => {
      service.current.unsubscribe(normalizedSymbol, callback);
      useMarketDataStore.getState().removeSubscription(normalizedSymbol);
      useMarketDataStore.getState().removeQuote(normalizedSymbol);
    };
  }, []); // Empty deps - all dependencies are stable
  
  /**
   * Unsubscribe from symbol quotes
   */
  const unsubscribe = useCallback((symbol: string) => {
    const normalizedSymbol = symbol.toUpperCase();
    const storeState = useMarketDataStore.getState();
    
    service.current.unsubscribe(normalizedSymbol);
    storeState.removeSubscription(normalizedSymbol);
    storeState.removeQuote(normalizedSymbol);
  }, []);
  
  /**
   * Subscribe to multiple symbols
   */
  const subscribeMultiple = useCallback((symbols: string[]) => {
    const unsubscribers = symbols.map(symbol => subscribe(symbol));
    
    return () => {
      unsubscribers.forEach(unsub => unsub());
    };
  }, [subscribe]);
  
  /**
   * Unsubscribe from all symbols
   */
  const unsubscribeAll = useCallback(() => {
    const subscriptions = Array.from(useMarketDataStore.getState().subscriptions);
    subscriptions.forEach(symbol => {
      unsubscribe(symbol);
    });
  }, [unsubscribe]);
  
  /**
   * Reconnect to WebSocket
   */
  const reconnect = useCallback(() => {
    const token = getAuthToken();
    if (token) {
      service.current.disconnect();
      setTimeout(() => {
        service.current.connect(token).catch((error) => {
          console.error('[useMarketDataWebSocket] Reconnection failed:', error);
          useMarketDataStore.getState().setError('Failed to reconnect to market data service');
        });
      }, 1000);
    }
  }, []);
  
  /**
   * Disconnect from WebSocket
   */
  const disconnect = useCallback(() => {
    service.current.disconnect();
    useMarketDataStore.getState().reset();
  }, []);
  
  // Use selectors for reactive values to prevent unnecessary re-renders
  const connectionState = useMarketDataStore((state) => state.connectionState);
  const error = useMarketDataStore((state) => state.error);
  // Don't subscribe to subscriptions here - it causes re-renders
  // Use getState() when needed instead
  
  // Memoize the return object to prevent identity changes
  return useMemo(() => ({
    // State
    connected: connectionState === ConnectionState.CONNECTED,
    connecting: connectionState === ConnectionState.CONNECTING,
    disconnected: connectionState === ConnectionState.DISCONNECTED,
    reconnecting: connectionState === ConnectionState.RECONNECTING,
    connectionState,
    error,
    
    // Subscriptions - use getState() to avoid reactivity
    get subscriptions() {
      return Array.from(useMarketDataStore.getState().subscriptions);
    },
    isSubscribed: (symbol: string) => useMarketDataStore.getState().subscriptions.has(symbol.toUpperCase()),
    
    // Actions
    subscribe,
    unsubscribe,
    subscribeMultiple,
    unsubscribeAll,
    reconnect,
    disconnect,
    
    // Service instance (for advanced usage)
    service: service.current,
  }), [connectionState, error, subscribe, unsubscribe, subscribeMultiple, unsubscribeAll, reconnect, disconnect]);
}

/**
 * Hook to subscribe to a symbol and get its quote
 * Automatically subscribes on mount and unsubscribes on unmount
 * 
 * @example
 * ```tsx
 * function StockPrice({ symbol }) {
 *   const quote = useSymbolQuote(symbol);
 *   
 *   if (!quote) return <div>Loading...</div>;
 *   
 *   return (
 *     <div>
 *       {symbol}: ${quote.last}
 *       <span>Bid: ${quote.bid} | Ask: ${quote.ask}</span>
 *     </div>
 *   );
 * }
 * ```
 */
export function useSymbolQuote(symbol: string) {
  const { subscribe } = useMarketDataWebSocket();
  // Use selector to only re-render when this symbol's quote changes
  const quote = useMarketDataStore((state) => state.quotes[symbol.toUpperCase()]);
  
  useEffect(() => {
    const cleanup = subscribe(symbol);
    return cleanup;
  }, [symbol, subscribe]);
  
  return quote;
}

/**
 * Hook to get latest price for a symbol
 * Automatically subscribes on mount and unsubscribes on unmount
 * 
 * @example
 * ```tsx
 * function CurrentPrice({ symbol }) {
 *   const price = useSymbolPrice(symbol);
 *   
 *   return <div>{symbol}: ${price?.toFixed(2) || '...'}</div>;
 * }
 * ```
 */
export function useSymbolPrice(symbol: string): number | undefined {
  const { subscribe } = useMarketDataWebSocket();
  // Use selector to only re-render when this symbol's price changes
  const price = useMarketDataStore((state) => {
    const quote = state.quotes[symbol.toUpperCase()];
    return quote ? (quote.last || quote.mid) : undefined;
  });
  
  useEffect(() => {
    const cleanup = subscribe(symbol);
    return cleanup;
  }, [symbol, subscribe]);
  
  return price;
}

/**
 * Hook to subscribe to multiple symbols
 * 
 * @example
 * ```tsx
 * function Watchlist({ symbols }) {
 *   useMultipleSymbols(symbols);
 *   
 *   return (
 *     <div>
 *       {symbols.map(symbol => (
 *         <QuoteRow key={symbol} symbol={symbol} />
 *       ))}
 *     </div>
 *   );
 * }
 * ```
 */
export function useMultipleSymbols(symbols: string[]) {
  const { subscribeMultiple } = useMarketDataWebSocket();
  
  useEffect(() => {
    if (symbols.length === 0) return;
    
    const cleanup = subscribeMultiple(symbols);
    return cleanup;
  }, [symbols.join(','), subscribeMultiple]); // Join symbols to create stable dependency
}

/**
 * Performance Optimization Hooks
 * Custom hooks for debouncing, throttling, and performance monitoring
 */

import { useState, useEffect, useRef, useCallback, useMemo } from 'react';

/**
 * Debounce hook - delays execution until user stops typing
 * Perfect for search inputs, filters, API calls
 */
export function useDebounce<T>(value: T, delay: number = 500): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedValue(value);
    }, delay);

    return () => {
      clearTimeout(handler);
    };
  }, [value, delay]);

  return debouncedValue;
}

/**
 * Debounced callback hook - delays function execution
 * Use when you need to debounce a specific function
 */
export function useDebouncedCallback<T extends (...args: unknown[]) => unknown>(
  callback: T,
  delay: number = 500
): (...args: Parameters<T>) => void {
  const timeoutRef = useRef<NodeJS.Timeout | undefined>(undefined);

  useEffect(() => {
    return () => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }
    };
  }, []);

  return useCallback(
    (...args: Parameters<T>) => {
      if (timeoutRef.current) {
        clearTimeout(timeoutRef.current);
      }

      timeoutRef.current = setTimeout(() => {
        callback(...args);
      }, delay);
    },
    [callback, delay]
  );
}

/**
 * Throttle hook - limits execution rate
 * Perfect for scroll handlers, resize handlers
 */
export function useThrottle<T>(value: T, limit: number = 200): T {
  const [throttledValue, setThrottledValue] = useState<T>(value);
  const lastRan = useRef<number>(Date.now());

  useEffect(() => {
    const handler = setTimeout(() => {
      if (Date.now() - lastRan.current >= limit) {
        setThrottledValue(value);
        lastRan.current = Date.now();
      }
    }, limit - (Date.now() - lastRan.current));

    return () => {
      clearTimeout(handler);
    };
  }, [value, limit]);

  return throttledValue;
}

/**
 * Throttled callback hook - limits function execution rate
 */
export function useThrottledCallback<T extends (...args: unknown[]) => unknown>(
  callback: T,
  limit: number = 200
): (...args: Parameters<T>) => void {
  const inThrottle = useRef<boolean>(false);

  return useCallback(
    (...args: Parameters<T>) => {
      if (!inThrottle.current) {
        callback(...args);
        inThrottle.current = true;
        setTimeout(() => {
          inThrottle.current = false;
        }, limit);
      }
    },
    [callback, limit]
  );
}

/**
 * Memoized computation hook with dependency array
 * More explicit than useMemo for complex calculations
 */
export function useMemoizedValue<T>(
  factory: () => T,
  deps: React.DependencyList
): T {
  return useMemo(factory, deps);
}

/**
 * Previous value hook - access previous render's value
 * Useful for comparing changes and optimization
 */
export function usePrevious<T>(value: T): T | undefined {
  const ref = useRef<T | undefined>(undefined);

  useEffect(() => {
    ref.current = value;
  }, [value]);

  return ref.current;
}

/**
 * Update effect hook - skip first render
 * Only runs on updates, not initial mount
 */
export function useUpdateEffect(
  effect: React.EffectCallback,
  deps?: React.DependencyList
) {
  const isMounted = useRef(false);

  useEffect(() => {
    if (isMounted.current) {
      return effect();
    } else {
      isMounted.current = true;
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps);
}

/**
 * Lazy state hook - only initializes on first access
 * Useful for expensive initial state calculations
 */
export function useLazyState<T>(
  initializer: () => T
): [T, React.Dispatch<React.SetStateAction<T>>] {
  const [state, setState] = useState<T>(initializer);
  return [state, setState];
}

/**
 * Async memoization hook - cache async results
 * Perfect for expensive API calls or calculations
 */
export function useAsyncMemo<T>(
  factory: () => Promise<T>,
  deps: React.DependencyList,
  defaultValue: T
): T {
  const [value, setValue] = useState<T>(defaultValue);

  useEffect(() => {
    let cancelled = false;
    
    factory().then((result) => {
      if (!cancelled) {
        setValue(result);
      }
    });

    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps);

  return value;
}

/**
 * Performance monitoring hook
 * Logs render times in development
 */
export function useRenderCount(componentName: string) {
  const renderCount = useRef(0);
  const startTime = useRef(performance.now());

  useEffect(() => {
    renderCount.current += 1;
    const endTime = performance.now();
    const renderTime = endTime - startTime.current;

    if (process.env.NODE_ENV === 'development') {
      console.log(
        `[${componentName}] Render #${renderCount.current} took ${renderTime.toFixed(2)}ms`
      );
    }

    startTime.current = performance.now();
  });

  return renderCount.current;
}

/**
 * Intersection observer hook for lazy loading
 * Detects when element enters viewport
 */
export function useIntersectionObserver(
  ref: React.RefObject<Element>,
  options: IntersectionObserverInit = {}
): boolean {
  const [isIntersecting, setIsIntersecting] = useState(false);

  useEffect(() => {
    const element = ref.current;
    if (!element) return;

    const observer = new IntersectionObserver(([entry]) => {
      setIsIntersecting(entry.isIntersecting);
    }, options);

    observer.observe(element);

    return () => {
      observer.disconnect();
    };
  }, [ref, options]);

  return isIntersecting;
}

/**
 * Idle callback hook - run code when browser is idle
 * Perfect for non-critical background tasks
 */
export function useIdleCallback(
  callback: () => void,
  deps: React.DependencyList
) {
  useEffect(() => {
    if ('requestIdleCallback' in window) {
      const id = requestIdleCallback(callback);
      return () => cancelIdleCallback(id);
    } else {
      // Fallback for browsers without requestIdleCallback
      const timeout = setTimeout(callback, 1);
      return () => clearTimeout(timeout);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps);
}

/**
 * Local storage with memoization
 * Caches values to avoid repeated parsing
 */
export function useLocalStorage<T>(
  key: string,
  initialValue: T
): [T, (value: T | ((val: T) => T)) => void] {
  const [storedValue, setStoredValue] = useState<T>(() => {
    try {
      const item = window.localStorage.getItem(key);
      return item ? JSON.parse(item) : initialValue;
    } catch (error) {
      console.warn(`Error loading localStorage key "${key}":`, error);
      return initialValue;
    }
  });

  const setValue = useCallback(
    (value: T | ((val: T) => T)) => {
      try {
        const valueToStore = value instanceof Function ? value(storedValue) : value;
        setStoredValue(valueToStore);
        window.localStorage.setItem(key, JSON.stringify(valueToStore));
      } catch (error) {
        console.warn(`Error saving localStorage key "${key}":`, error);
      }
    },
    [key, storedValue]
  );

  return [storedValue, setValue];
}

/**
 * Responsive Hooks
 * Hooks for detecting screen size and device type
 */

import { useState, useEffect } from 'react';
import { Grid } from 'antd';

const { useBreakpoint } = Grid;

/**
 * Breakpoint definitions matching Ant Design
 */
export const breakpoints = {
  xs: 480,
  sm: 576,
  md: 768,
  lg: 992,
  xl: 1200,
  xxl: 1600,
};

/**
 * Hook to detect if screen is mobile (< md breakpoint)
 */
export const useIsMobile = (): boolean => {
  const screens = useBreakpoint();
  return !screens.md;
};

/**
 * Hook to detect if screen is tablet (md to lg)
 */
export const useIsTablet = (): boolean => {
  const screens = useBreakpoint();
  return !!(screens.md && !screens.lg);
};

/**
 * Hook to detect if screen is desktop (>= lg)
 */
export const useIsDesktop = (): boolean => {
  const screens = useBreakpoint();
  return !!screens.lg;
};

/**
 * Hook to get current screen breakpoint
 */
export const useScreenSize = (): keyof typeof breakpoints | 'xs' => {
  const screens = useBreakpoint();
  
  if (screens.xxl) return 'xxl';
  if (screens.xl) return 'xl';
  if (screens.lg) return 'lg';
  if (screens.md) return 'md';
  if (screens.sm) return 'sm';
  return 'xs';
};

/**
 * Hook to get window dimensions
 */
export const useWindowSize = () => {
  const [windowSize, setWindowSize] = useState({
    width: window.innerWidth,
    height: window.innerHeight,
  });

  useEffect(() => {
    const handleResize = () => {
      setWindowSize({
        width: window.innerWidth,
        height: window.innerHeight,
      });
    };

    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  return windowSize;
};

/**
 * Hook to detect touch device
 */
export const useIsTouchDevice = (): boolean => {
  const [isTouch, setIsTouch] = useState(false);

  useEffect(() => {
    setIsTouch(
      'ontouchstart' in window ||
      navigator.maxTouchPoints > 0 ||
      // @ts-ignore - msMaxTouchPoints is IE-specific
      navigator.msMaxTouchPoints > 0
    );
  }, []);

  return isTouch;
};

/**
 * Hook to detect device orientation
 */
export const useOrientation = (): 'portrait' | 'landscape' => {
  const [orientation, setOrientation] = useState<'portrait' | 'landscape'>(
    window.innerHeight > window.innerWidth ? 'portrait' : 'landscape'
  );

  useEffect(() => {
    const handleOrientationChange = () => {
      setOrientation(
        window.innerHeight > window.innerWidth ? 'portrait' : 'landscape'
      );
    };

    window.addEventListener('resize', handleOrientationChange);
    window.addEventListener('orientationchange', handleOrientationChange);

    return () => {
      window.removeEventListener('resize', handleOrientationChange);
      window.removeEventListener('orientationchange', handleOrientationChange);
    };
  }, []);

  return orientation;
};

/**
 * Responsive value selector hook
 * Returns different values based on screen size
 */
export const useResponsiveValue = <T,>(values: {
  xs?: T;
  sm?: T;
  md?: T;
  lg?: T;
  xl?: T;
  xxl?: T;
  default: T;
}): T => {
  const screenSize = useScreenSize();
  return values[screenSize] ?? values.default;
};

/**
 * Hook to detect if user prefers reduced motion
 */
export const usePrefersReducedMotion = (): boolean => {
  const [prefersReducedMotion, setPrefersReducedMotion] = useState(false);

  useEffect(() => {
    const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
    setPrefersReducedMotion(mediaQuery.matches);

    const handleChange = (e: MediaQueryListEvent) => {
      setPrefersReducedMotion(e.matches);
    };

    mediaQuery.addEventListener('change', handleChange);
    return () => mediaQuery.removeEventListener('change', handleChange);
  }, []);

  return prefersReducedMotion;
};

/**
 * WebSocket Hook
 * React hook for subscribing to WebSocket topics
 */

import { useEffect } from 'react';
import { websocketManager } from '@/services/websocketManager';
import { useAuthStore } from '@/store/authStore';
import type { WebSocketTopic } from '@/types/websocket';

/**
 * Subscribe to a WebSocket topic
 * Automatically connects and subscribes when authenticated
 */
export const useWebSocket = (
  topic: WebSocketTopic,
  handler: (data: any) => void,
  symbols?: string[]
) => {
  const accessToken = useAuthStore((state) => state.accessToken);
  const isAuthenticated = useAuthStore((state) => state.isAuthenticated);

  useEffect(() => {
    if (!isAuthenticated || !accessToken) return;

    // Connect if not already connected
    if (!websocketManager.isConnected()) {
      websocketManager.connect(accessToken);
    }

    // Subscribe to topic
    websocketManager.subscribe(topic, handler, symbols);

    // Cleanup: Unsubscribe when component unmounts
    return () => {
      websocketManager.unsubscribe(topic, handler);
    };
  }, [topic, handler, symbols, accessToken, isAuthenticated]);
};

/**
 * Hook to monitor WebSocket connection state
 */
export const useWebSocketConnection = () => {
  const accessToken = useAuthStore((state) => state.accessToken);
  const isAuthenticated = useAuthStore((state) => state.isAuthenticated);

  useEffect(() => {
    if (isAuthenticated && accessToken && !websocketManager.isConnected()) {
      websocketManager.connect(accessToken);
    }

    // Cleanup: Disconnect when user logs out
    return () => {
      if (!isAuthenticated) {
        websocketManager.disconnect();
      }
    };
  }, [isAuthenticated, accessToken]);

  return {
    isConnected: websocketManager.isConnected(),
    connect: (token: string) => websocketManager.connect(token),
    disconnect: () => websocketManager.disconnect(),
  };
};

